window.WZ_DATA = {"generated":"2026-11-16T08:36:13.594Z","source":{"name":"Ondernemersplein (KVK, Rijksoverheid)","url":"https://ondernemersplein.overheid.nl/wetswijzigingen/","licence":"CC BY 4.0","licenceUrl":"https://creativecommons.org/licenses/by/4.0/deed.nl"},"sectors":[{"key":"agrosector","name":"Agrosector"},{"key":"bouwnijverheid","name":"Bouwnijverheid"},{"key":"cultuur-amusement-sport-en-media","name":"Cultuur, amusement, sport en media"},{"key":"detailhandel-groothandel-en-ambachten","name":"Detailhandel, groothandel en ambachten"},{"key":"horeca-recreatie-en-catering","name":"Horeca, recreatie en catering"},{"key":"industrie","name":"Industrie"},{"key":"kinderopvang","name":"Kinderopvang"},{"key":"persoonlijke-dienstverlening","name":"Persoonlijke dienstverlening"},{"key":"vervoer","name":"Vervoer"},{"key":"zakelijke-dienstverlening","name":"Zakelijke dienstverlening"},{"key":"zorg","name":"Zorg"}],"subjects":[{"key":"bedrijf-starten-of-overnemen","name":"Bedrijf starten of overnemen"},{"key":"bedrijf-stoppen-of-overdragen","name":"Bedrijf stoppen of overdragen"},{"key":"bedrijfshuisvesting","name":"Bedrijfshuisvesting"},{"key":"bedrijfsvoering","name":"Bedrijfsvoering"},{"key":"belastingen-en-heffingen","name":"Belastingen en heffingen"},{"key":"internationaal-ondernemen","name":"Internationaal ondernemen"},{"key":"klimaat-energie-en-natuur","name":"Klimaat, energie en natuur"},{"key":"personeel","name":"Personeel"},{"key":"product-dienst-en-innovatie","name":"Product, dienst en innovatie"}],"items":[{"id":"cryptoaanbieders-moeten-gegevens-delen-met-belastingdienst","t":"Cryptoaanbieders moeten gegevens delen met Belastingdienst","d":"2026-04-10","dn":"nog niet bekend","sec":["zakelijke-dienstverlening"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/cryptoaanbieders-moeten-gegevens-delen-met-belastingdienst/","sh":"Deze wet is ingegaan: zorg dat u aan de regels voldoet","se":"Deze wet is ingegaan. U moet aan de regels voldoen. De overheid controleert dit.","ph":"ingegaan","vw":["aanbieders van cryptoactivadiensten","financiële instellingen","intermediairs, waaronder belastingadviseurs"],"vwt":"","wat":["Biedt u cryptodiensten aan? Aanbieders van cryptodiensten moeten de gegevens van hun gebruikers verzamelen, controleren en delen met de Belastingdienst. Deze wijziging is onderdeel van de Europese DAC8-richtlijn (Richtlijn (EU) 2023/2226), die in de Nederlandse wet wordt ingevoerd.","Het doel van deze wijziging is om meer openheid te krijgen over het bezit van crypto’s. Dit helpt om belastingontwijking en -ontduiking te voorkomen."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-93.html","text":"Uitvoeringsbesluit verzamel- en verificatievereisten voor rapporterende aanbieders van cryptoactivadiensten (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-79.html","text":"Wet implementatie EU-richtlijn gegevensuitwisseling cryptoactiva (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/crypto/b1","text":"Consultatie Wet implementatie EU-richtlijn gegevensuitwisseling cryptoactiva (Overheid.nl)"},{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=OJ:L_202302226","text":"Europese DAC8-richtlijn (Richtlijn (EU) 2023/2226) EU"}],"en":"https://business.gov.nl/amendments/crypto-asset-providers-must-share-data-with-tax-administration/","mod":"2026-06-18"},{"id":"toegang-tot-werk-voor-asielzoekers-verandert","t":"Toegang tot werk voor asielzoekers is veranderd","d":"2026-06-12","dn":"","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/toegang-tot-werk-voor-asielzoekers-verandert/","sh":"Deze wet is ingegaan: zorg dat u aan de regels voldoet","se":"Deze wet is ingegaan. U moet aan de regels voldoen. De overheid controleert dit.","ph":"ingegaan","vw":["werkgevers die asielzoekers in dienst hebben","werkgevers die asielzoekers willen aannemen"],"vwt":"","wat":["Heeft u asielzoekers in dienst of wilt u een asielzoeker aannemen? Op 12 juni 2026 zijn de regels voor werkende asielzoekers veranderd.","Door nieuwe Europese regels mag niet iedere asielzoeker meer werken in Nederland. Of een asielzoeker mag werken, hangt af van de behandeling van de asielaanvraag.","De belangrijkste veranderingen zijn:","• Sommige asielzoekers mogen niet meer werken in Nederland.\n• Asielzoekers uit een veilig land van herkomst mogen mogelijk niet aan het werk in Nederland.\n• Asielzoekers die een gevaar vormen voor de openbare orde of nationale veiligheid mogen niet werken.\n• Asielzoekers met een grotere kans op een verblijfsvergunning mogen meestal wel werken.\n• U moet ook na 12 juni 2026 een tewerkstellingsvergunning (TWV) aanvragen bij het UWV, voor de asielzoeker die bij u aan de slag gaat.","Wat betekent dit voor u?","Wilt u een asielzoeker in dienst nemen? Dan moet u eerst controleren of deze asielzoeker mag werken. De Immigratie- en Naturalisatiedienst (IND) bepaalt dit. De asielzoeker krijgt hierover 3 maanden na de asielaanvraag bericht.","Daarna vraagt u een tewerkstellingsvergunning (TWV) aan bij het UWV. Het UWV controleert of aan de voorwaarden is voldaan. Daarna hoort u of de asielzoeker bij u mag werken."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-129.html","text":"Uitvoerings- en implementatiebesluit Asiel- en migratiepact 2026 (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-127.html","text":"Uitvoerings- en implementatiewet Asiel- en migratiepact 2026 (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-128.html","text":"Uitvoerings- en implementatiebesluit Asiel- en migratiepact 2026 (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/besluitasielenmigratiepact/b1","text":"Consultatie Uitvoerings- en implementatiebesluit Asiel- en Migratiepact 2026 (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/changes-to-access-to-work-for-asylum-seekers/","mod":"2026-07-09"},{"id":"webshops-moeten-een-herroepingsknop-hebben","t":"Webshops moeten een herroepingsknop hebben","d":"2026-06-25","dn":"","sec":[],"sub":["bedrijfsvoering"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/webshops-moeten-een-herroepingsknop-hebben/","sh":"Deze wet is ingegaan: zorg dat u aan de regels voldoet","se":"Deze wet is ingegaan. U moet aan de regels voldoen. De overheid controleert dit.","ph":"ingegaan","vw":["webshops die producten verkopen aan consumenten","aanbieders van diensten, zoals online cursussen of coachingstrajecten","online verkopers via social media"],"vwt":"","wat":["Heeft u een webshop of verkoopt u diensten online? U moet een duidelijke herroepingsknop op uw website hebben. Met deze knop kunnen klanten makkelijk en snel hun aankoop of dienst annuleren binnen de wettelijke bedenktermijn van 14 dagen.","Voor de verplichting van de herroepingsknop, moesten klanten een formulier invullen of contact opnemen met de klantenservice om gebruik te maken van hun herroepingsrecht. Dat is veranderd. Nu is 1 klik op de knop genoeg.","De knop moet een duidelijke tekst hebben, zoals ‘hier de overeenkomst ontbinden’. De knop vervangt het modelformulier voor herroeping niet. Het is een extra, makkelijkere mogelijkheid voor uw klanten.","Hoe werkt het?","Na een klik op de herroepingsknop volgen nog 2 stappen:","• De klant geeft aan de aankoop of dienst te willen annuleren.\n• U stuurt de klant een bericht om de annulering te bevestigen. Na bevestiging door de klant gaat de terugzendtermijn in."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-153.html","text":"Implementatiewet richtlijn op afstand gesloten overeenkomsten inzake financiële diensten (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/financieledienstenopafstand/b1","text":"Consultatie Implementatiewet richtlijn op afstand gesloten overeenkomsten inzake financiële diensten (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/online-shops-must-have-cancellation-button/","mod":"2026-10-13"},{"id":"bedrijfsvoertuigen-betalen-tijdelijk-minder-wegenbelasting","t":"Bedrijfsvoertuigen betalen tijdelijk minder wegenbelasting","d":"2026-07-01","dn":"","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/bedrijfsvoertuigen-betalen-tijdelijk-minder-wegenbelasting/","sh":"Deze wet is ingegaan: zorg dat u aan de regels voldoet","se":"Deze wet is ingegaan. U moet aan de regels voldoen. De overheid controleert dit.","ph":"ingegaan","vw":["ondernemers met een bestelauto met ondernemerstarief","transportbedrijven","ondernemers met 1 of meer vrachtauto’s"],"vwt":"","wat":["Heeft u een bestelauto met het ondernemerstarief of een vrachtauto? Dan betaalt u sinds 1 juli 2026 tijdelijk minder motorrijtuigenbelasting (mrb). Het kabinet heeft deze maatregel genomen vanwege de gestegen brandstofprijzen.","De belangrijkste veranderingen zijn:","• Heeft u een bestelauto met het ondernemerstarief? Dan betaalt u van 1 juli 2026 tot 1 januari 2027 50% minder motorrijtuigenbelasting.\n• Heeft u een vrachtauto van 12.000 kilo of meer? Dan betaalt u van 1 juli 2026 tot 1 januari 2027 geen motorrijtuigenbelasting.\n• Heeft u een vrachtauto lichter dan 12.000 kilo? Dan geldt vanaf 1 juli 2026 sowieso een nihiltarief. U betaalt dus geen motorrijtuigenbelasting.\n• De verlaging gaat niet altijd direct op 1 juli in. U betaalt motorrijtuigenbelasting per tijdvak van 3 maanden. Het lagere tarief geldt vanaf het eerste tijdvak dat op of na 1 juli 2026 begint."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/temporary-reduction-in-motor-vehicle-tax-for-commercial-vehicles/","mod":"2026-09-16"},{"id":"gastouderopvang-krijgt-nieuwe-regels","t":"Gastouderopvang heeft nieuwe regels","d":"2026-07-01","dn":"","sec":["kinderopvang"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/gastouderopvang-krijgt-nieuwe-regels/","sh":"Deze wet is ingegaan: zorg dat u aan de regels voldoet","se":"Deze wet is ingegaan. U moet aan de regels voldoen. De overheid controleert dit.","ph":"ingegaan","vw":["gastouders","gastouderbureaus"],"vwt":"Bent u gastouder of runt u een gastouderbureau? De regels voor gastouderopvang zijn veranderd. Dit verhoogt de kwaliteit van gastouderopvang en maakt het aantrekkelijker om gastouder te worden. Hier leest u wat er voor u is veranderd.","wat":["• Strengere kwaliteitseisen: Voor gastouderopvang gelden dezelfde pedagogische eisen als voor kinderdagverblijven en buitenschoolse opvang. Dit betekent dat u werkt aan een veilige en stimulerende omgeving voor kinderen.\n• Maximaal 2 gastouderbureaus: U mag zich aansluiten bij maximaal 2 gastouderbureaus. Wilt u overstappen? Dan mag u tijdelijk bij 3 bureaus zijn aangesloten. Lopende contracten met ouders blijven gewoon geldig.\n• Eigen kinderen meetellen: Uw eigen kinderen tot 8 jaar tellen mee bij het maximum aantal kinderen dat u mag opvangen. Eerder was dit tot 10 jaar.\n• Kinderopvangtoeslag voor gastouders: Heeft u zelf kinderen die naar een andere gastouder gaan? Dan kunt u hiervoor kinderopvangtoeslag krijgen. Dit gold eerder alleen voor kinderdagverblijven en buitenschoolse opvang.\n• Verplichte coaching en scholing: U krijgt minstens 3 uur pedagogische coaching per jaar van uw gastouderbureau. Ook volgt u scholing en werkt u met een pedagogisch werkplan.\n• Pedagogisch beleidsplan: Het gastouderbureau beschrijft hierin hoe het gastouders begeleidt, scholing aanbiedt en de pedagogische kwaliteit bewaakt."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-428.html","text":"Besluit inwerkingtreding Wet wijziging Wet kinderopvang voor verbetermaatregelen van de gastouderopvang (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-427.html","text":"Besluit wijziging Besluit kwaliteit kinderopvang in verband met het verhogen van de kwaliteit van de gastouderopvang (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-164.html","text":"Wet wijziging Wet kinderopvang voor verbetermaatregelen van de gastouderopvang (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/new-rules-for-childminding/","mod":"2026-09-24"},{"id":"helft-personeel-kinderopvang-mag-in-opleiding-zijn","t":"Helft personeel kinderopvang mag in opleiding zijn","d":"2026-07-01","dn":"","sec":["kinderopvang"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/helft-personeel-kinderopvang-mag-in-opleiding-zijn/","sh":"Deze wet is ingegaan: zorg dat u aan de regels voldoet","se":"Deze wet is ingegaan. U moet aan de regels voldoen. De overheid controleert dit.","ph":"ingegaan","vw":["houders van kinderdagverblijven","houders van buitenschoolse opvang (bso)","kinderopvangorganisaties"],"vwt":"","wat":["Heeft u een kinderopvangorganisatie? Dan mag u beroepskrachten in opleiding langer ruimer inzetten.","Sinds 2022 geldt een tijdelijke regeling waarmee maximaal 50% van de formatie mag bestaan uit beroepskrachten in opleiding. Zonder deze regeling is dat maximaal 33%.","De tijdelijke regeling zou aflopen op 1 juli 2026. De minister heeft de regeling verlengd met 2 jaar, tot 1 juli 2028.","Hierdoor heeft u meer mogelijkheden om personeelstekorten op te vangen. Ook kunt u groepen mogelijk vaker openhouden bij ziekte, verlof of pauzes van medewerkers.","Voorwaarden voor inzet beroepskrachten in opleiding","U moet aan bepaalde voorwaarden voldoen voordat u beroepskrachten in opleiding op de groep inzet:","• Maximaal 50% van de formatie mag bestaan uit beroepskrachten in opleiding.\n• U moet een begeleidingsplan opstellen.\n• De beroepskracht in opleiding gaat akkoord met het plan.\n• De praktijkbegeleider gaat akkoord met het plan.\n• De opleidingsbegeleider gaat akkoord met het plan."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/regelingwetkinderopvangstructureelverruimeninzetberoepskrachteninopleiding/b1","text":"Consultatie wijziging van de Regeling Wet kinderopvang in verband met het structureel verruimen van de inzet van beroepskrachten in opleiding op kindercentra (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/half-childcare-staff-may-consist-trainees/","mod":"2026-08-27"},{"id":"invoerrechten-gaan-gelden-voor-e-commercezendingen-tot-eur-150","t":"Invoerrechten gelden voor e-commercezendingen tot € 150","d":"2026-07-01","dn":"","sec":[],"sub":["internationaal-ondernemen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/invoerrechten-gaan-gelden-voor-e-commercezendingen-tot-eur-150/","sh":"Deze wet is ingegaan: zorg dat u aan de regels voldoet","se":"Deze wet is ingegaan. U moet aan de regels voldoen. De overheid controleert dit.","ph":"ingegaan","vw":["ondernemers die online bestellingen van buiten de EU aan consumenten in de EU leveren","douane-expediteurs","logistieke dienstverleners die douaneaangiften doen"],"vwt":"","wat":["Heeft u te maken met e-commercezendingen met een waarde tot € 150? En gaat het om online bestellingen die van buiten de Europese Unie (EU) rechtstreeks naar consumenten in de EU worden verzonden? Op 1 juli 2026 zijn de regels voor invoerrechten veranderd. Er is geen vrijstelling van invoerrechten meer.","De belangrijkste veranderingen zijn:","• Sinds 1 juli 2026 betaalt u invoerrechten voor e-commercezendingen met een waarde tot € 150. Tot die datum gold voor deze pakketten nog een vrijstelling.\n• Van 1 juli 2026 tot 1 juli 2028 betaalt u een vast invoerrecht van € 3 voor iedere aangifteregel. Heeft een pakket 2 verschillende soorten producten? Dan betaalt u 2 keer € 3.\n• Vanaf 1 juli 2028 betaalt u het gewone EU-douanetarief dat hoort bij het ingevoerde product.\n• Sinds 1 juli 2026 moet u zekerheid stellen voor de invoerrechten. Dat betekent dat u vooraf een financiële garantie moet afgeven voor de invoerrechten. Hiervoor heeft u een vergunning doorlopende zekerheid (CGU) en een vergunning uitstel van betaling (DPO) nodig.","Extra afhandelingsvergoeding vanaf 1 november 2026Vanaf 1 november 2026 betalen importeurs ook een afhandelingsvergoeding van € 2 per productgroep voor e-commercezendingen van buiten de EU. Deze vergoeding komt bovenop de invoerrechten.De afhandelingsvergoeding geldt niet alleen voor zendingen met een waarde tot € 150. Met de vergoeding worden de extra kosten betaald die de Douane maakt voor het verwerken en controleren van e-commercezendingen. De vergoeding moet het ook aantrekkelijker maken om dezelfde producten samen in grotere hoeveelheden te importeren. Zulke zendingen kan de Douane efficiënter controleren."],"doen":[],"law":[{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=OJ:L_202602108","text":"Verordening (EU) 2026/2108 tot vaststelling douanewetboek van de Unie (EU)"},{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=OJ:L_202600382","text":"Verordening (EU) 2026/382 voor de afschaffing van de vrijstelling van douanerechten op basis van drempelwaarden (EU)"}],"en":"https://business.gov.nl/amendments/import-duties-low-value-e-commerce-shipments/","mod":"2026-09-23"},{"id":"minimumloon-gaat-omhoog-op-1-juli-2026","t":"Minimumloon op 1 juli 2026 omhooggegaan","d":"2026-07-01","dn":"","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/minimumloon-gaat-omhoog-op-1-juli-2026/","sh":"Deze wet is ingegaan: zorg dat u aan de regels voldoet","se":"Deze wet is ingegaan. U moet aan de regels voldoen. De overheid controleert dit.","ph":"ingegaan","vw":["alle ondernemers met personeel van 15 jaar en ouder"],"vwt":"","wat":["Heeft u personeel? Het minimumloon is op 1 juli 2026 omhooggegaan van € 14,71 per uur naar € 14,99 per uur. Ook zijn de minimumjeugdlonen veranderd op 1 juli 2026. Die zijn met hetzelfde percentage omhooggegaan.","Bekijk de brutobedragen voor het minimumuurloon vanaf 1 juli 2026.","Voor werknemers van 15 tot en met 20 jaar geldt het wettelijk minimumjeugdloon. Voor werknemers onder 21 jaar is het minimumjeugdloon per uur voor iedere leeftijd anders.","Het minimumloon en het minimumjeugdloon worden elk half jaar aangepast: op 1 januari en 1 juli.","Let op!In uw branche kan een hoger minimumloon gelden! Kijk goed wat er in de collectieve arbeidsovereenkomst (cao) voor uw bedrijf staat."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stcrt-2026-16505.html","text":"Regeling Minister van SZW tot indexatie wettelijk minimumloon en bekendmaking minimumloon per 1 juli 2026 (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/minimum-wage-increases-july-2026/","mod":"2026-07-02"},{"id":"nieuwe-en-aangepaste-milieuprestatie-eisen-voor-gebouwen","t":"Nieuwe en aangepaste milieuprestatie-eisen voor gebouwen","d":"2026-07-01","dn":"","sec":["bouwnijverheid"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/nieuwe-en-aangepaste-milieuprestatie-eisen-voor-gebouwen/","sh":"Deze wet is ingegaan: zorg dat u aan de regels voldoet","se":"Deze wet is ingegaan. U moet aan de regels voldoen. De overheid controleert dit.","ph":"ingegaan","vw":["bouwbedrijven","projectontwikkelaars","vastgoedontwikkelaars","architecten","ondernemers die nieuwbouw laten realiseren"],"vwt":"","wat":["Werkt u in de bouw, projectontwikkeling of vastgoed? Vanaf 1 juli 2026 zijn de milieuprestatie-eisen voor gebouwen (MPG) veranderd. De overheid heeft bestaande eisen aangescherpt en voert voor meerdere gebouwtypen voor het eerst een milieuprestatie-eis in.","De belangrijkste veranderingen zijn:","• De milieuprestatie-eis voor kantoren wordt strenger.\n• Voor scholen, winkels, zorginstellingen en bedrijfshallen geldt voor het eerst een milieuprestatie-eis.\n• Voor kleine woningen en sommige kantoren geldt een soepelere milieuprestatie-eis.\n• De rekenmethode voor de milieuprestatie van gebouwen verandert. Daarbij worden 19 milieucategorieën gebruikt in plaats van 11."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-432.html","text":"Besluit wijziging Besluit bouwwerken leefomgeving voor aanscherpen milieuprestatie-eis voor kantoorfuncties en vastleggen milieuprestatie-eisen voor andere gebruiksfuncties (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stcrt-2025-44480.html","text":"Regeling Minister van Volkshuisvesting Ruimtelijke en Ordening tot wijziging Omgevingsregeling voor herziene Bepalingsmethode Milieuprestatie Bouwwerken (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/new-and-amended-environmental-performance-requirements-for-buildings/","mod":"2026-06-30"},{"id":"registratieplicht-voor-verkooppunten-tabak","t":"Registratieplicht voor verkooppunten van tabak","d":"2026-07-01","dn":"nog niet bekend","sec":["detailhandel-groothandel-en-ambachten"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/registratieplicht-voor-verkooppunten-tabak/","sh":"Deze wet is ingegaan: zorg dat u aan de regels voldoet","se":"Deze wet is ingegaan. U moet aan de regels voldoen. De overheid controleert dit.","ph":"ingegaan","vw":["eigenaren van verkooppunten van tabaksproducten en aanverwante producten"],"vwt":"","wat":["Heeft u een verkooppunt waar u tabak en aanverwante producten zoals e-sigaretten verkoopt? Dan moet u uw verkooppunt registreren.","Er is een registratieplicht voor verkooppunten van tabak en rookwaren. Het kabinet wil het aantal verkooppunten van tabak terugdringen. Door de registratieplicht kan de Nederlandse Voedsel- en Warenautoriteit (NVWA) bijhouden op hoeveel plekken tabak of aanverwante producten worden verkocht.","Onder aanverwante producten vallen producten zoals:","• elektronische sigaretten, ook wel vapes genoemd\n• navulverpakkingen en patronen, met en zonder nicotine\n• elektronische verhittingsapparaten\n• voor roken bestemde kruidenproducten\n• nicotineapparaten\n• nicotineproducten zonder tabak"],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-88.html","text":"Besluit inwerkingtreding Wet wijziging Tabaks- en rookwarenwet voor invoering registratieplicht verkooppunten tabaksproducten (Overheis.nl)"},{"href":"https://www.internetconsultatie.nl/registratieplichttabaksverkooppunten/b1","text":"Consultatie Regeling wijziging Tabaks- en rookwarenregeling voor uitwerking registratieplicht verkooppunten tabaksproducten (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-118.html","text":"Wet wijziging Tabaks- en rookwarenwet voor invoering registratieplicht verkooppunten tabaksproducten (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/registratieplichttabak/b1","text":"Consultatie Registratieplicht verkooppunten tabaksproducten (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/registration-duty-tobacco-outlets/","mod":"2026-08-19"},{"id":"tachograaf-smt2-verplicht-boven-2500-kg","t":"Slimme tachograaf type 2 verplicht voor voertuigen boven 2.500 kg","d":"2026-07-01","dn":"","sec":["vervoer"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/tachograaf-smt2-verplicht-boven-2500-kg/","sh":"Deze wet is ingegaan: zorg dat u aan de regels voldoet","se":"Deze wet is ingegaan. U moet aan de regels voldoen. De overheid controleert dit.","ph":"ingegaan","vw":["transportbedrijven die in het buitenland rijden","beroepsvervoerders die in het buitenland rijden","ondernemers die met een voertuig, bijvoorbeeld een bestelbus, van boven de 2.500 kg in het buitenland bezorgen"],"vwt":"","wat":["Heeft u een bedrijfswagen met een toegestaan maximumgewicht (Toegestane Maximum Massa, TMM) van boven de 2.500 kg? En verricht u met dit voertuig internationaal goederenvervoer of cabotage? Dan moet uw voertuig sinds 1 juli 2026 een slimme tachograaf type 2 (SMT2) hebben.","Vrijstelling eigen vervoer","Vervoert u met een voertuig met een toegestaan maximumgewicht van 2.501 tot en met 3.500 kg goederen voor eigen rekening? En is transport niet de hoofdactiviteit van de bestuurder? Dan is voor u de SMT2 niet verplicht. Dit is bijvoorbeeld zo bij een klusjesman die het voertuig gebruikt om met zijn gereedschap bij de klant te komen."],"doen":["• Controleer welke voertuigen een tachograaf moeten hebben.\n• Kijk of u onder een van de nationale of Europese vrijstellingen valt.\n• Plan zo snel mogelijk een afspraak bij een door RDW erkende werkplaats.\n• Vraag tijdig alle benodigde tachograafkaarten (bedrijfskaart en bestuurderskaart) aan.\n• Zorg ervoor dat uzelf en uw chauffeurs alles weten over hoe je de tachograaf gebruikt en wat de Europese rij- en rusttijdenregels zijn."],"law":[],"en":"https://business.gov.nl/amendments/smart-tachograph-type2-over-2500kg/","mod":"2026-08-07"},{"id":"telemarketing-uw-klant-niet-meer-ongevraagd-bellen","t":"Telemarketing: uw klant niet meer ongevraagd bellen","d":"2026-07-01","dn":"","sec":["zakelijke-dienstverlening"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/telemarketing-uw-klant-niet-meer-ongevraagd-bellen/","sh":"Deze wet is ingegaan: zorg dat u aan de regels voldoet","se":"Deze wet is ingegaan. U moet aan de regels voldoen. De overheid controleert dit.","ph":"ingegaan","vw":["ondernemers die telemarketing gebruiken"],"vwt":"","wat":["Verkoopt u een dienst of product aan de telefoon (telemarketing)? U mag sinds 1 juli 2026 consumenten niet meer ongevraagd bellen, zelfs niet als ze klant zijn (geweest). Deze strengere regels moeten consumenten beschermen tegen druk. De nieuwe regels gelden niet voor:","• goede doelen\n• loterijen die geld geven aan goede doelen\n• uitgevers van dagbladen, weekbladen en tijdschriften","Bedrijven mochten eerst alleen bellen als consumenten toestemming hadden gegeven of klant zijn. Met het vervallen van de uitzondering voor klanten, wordt ongevraagd bellen nog meer beperkt."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-89.html","text":"Besluit inwerkingtreding artikel 7.8 Energiewet (Overheid.nl)"},{"href":"https://wetten.overheid.nl/BWBR0050714/","text":"Energiewet (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/telemarketing-no-more-unsolicited-calling-your-customers/","mod":"2026-08-27"},{"id":"verbeterde-begeleiding-en-opleidingseisen-voor-gastouders","t":"Verbeterde begeleiding en opleidingseisen voor gastouders","d":"2026-07-01","dn":"nog niet bekend","sec":["kinderopvang"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/verbeterde-begeleiding-en-opleidingseisen-voor-gastouders/","sh":"Deze wet is ingegaan: zorg dat u aan de regels voldoet","se":"Deze wet is ingegaan. U moet aan de regels voldoen. De overheid controleert dit.","ph":"ingegaan","vw":["gastouders","houders van een gastouderbureau"],"vwt":"","wat":["Bent u gastouder of heeft u een gastouderbureau? Er gelden nieuwe regels voor gastouderopvang, die zijn bedoeld om de kwaliteit van de opvang verder te verbeteren. Gastouders krijgen betere begeleiding en worden professioneler opgeleid, wat bijdraagt aan een hogere professionaliteit. Gastouderbureaus hebben meer flexibiliteit in hoe zij gesprekken voeren, terwijl zij wel verantwoordelijk blijven voor een goede evaluatie met ouders.","Hieronder leest u wat er is veranderd en wat dit voor u betekent.","Strengere opleidingseisen voor gastouders","De opleiding van gastouders moet aan strengere eisen voldoen. Als iemand die als gastouder aan de slag wil gaan geen pedagogiek heeft gevolgd, moet de gastouder een aanvullende pedagogische module volgen. Gastouders die voor 1 juli 2026 geregistreerd zijn, hoeven niet aan deze nieuwe eis te voldoen. De eisen moeten zorgen voor hogere kwaliteit in de gastouderopvang.","Opleidingseis voor pedagogisch beleidsmedewerkers","Ook voor pedagogisch beleidsmedewerkers van gastouderbureaus is er een nieuwe opleidingseis. Deze medewerkers moeten gastouders coachen en moeten daarvoor de juiste kennis en vaardigheden hebben.","Veranderingen in begeleiding en bemiddeling","De begeleiding en bemiddeling die gastouderbureaus bieden, is op een aantal punten veranderd:","• Pedagogische coaching en permanente educatie\nPedagogische coaching en permanente educatie zijn vast onderdeel van de jaarlijkse gesprekken tussen gastouderbureau en gastouder. Zo blijven de vaardigheden van de gastouder up-to-date.\n• Minder verplichte gesprekken op locatie\nHet koppelingsgesprek en het voortgangsgesprek vinden niet meer verplicht op de locatie van de gastouderopvang plaats. Dit maakt het proces flexibeler voor zowel gastouders als ouders.\n• Inspanningsverplichting voor ouderevaluaties\nGastouderbureaus zijn verplicht om elk jaar de opvang te evalueren met ouders. Als ouders hier geen behoefte aan hebben en het bureau alles heeft gedaan om dit aan te bieden, kan het bureau hier niet op worden afgerekend. Dit zorgt voor een eerlijkere beoordeling van de inspanningen van het bureau."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/wijzigingregelingkwaliteitgastouderbureausenregelingwetkinderopvang/b1","text":"Consultatie Wijziging Regeling kwaliteit gastouderbureaus en Regeling Wet kinderopvang ivm verbetertraject gastouderopvang (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/improved-coaching-training-requirements-childminders/","mod":"2026-09-24"},{"id":"heffing-voor-vrachtwagens-vanaf-3500-kg","t":"Vrachtwagenheffing in Nederland","d":"2026-07-01","dn":"vanaf 2026","sec":["vervoer"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/heffing-voor-vrachtwagens-vanaf-3500-kg/","sh":"Deze wet is ingegaan: zorg dat u aan de regels voldoet","se":"Deze wet is ingegaan. U moet aan de regels voldoen. De overheid controleert dit.","ph":"ingegaan","vw":["eigenaren van vrachtwagens in de categorie N2 en N3. Dit zijn vrachtwagens met een technische maximum massa van meer dan 3500 kg. De categorie staat op het kentekenbewijs.","vrachtwagens van 40 jaar en ouder die alleen privé worden gebruikt","politie- en brandweerwagens","elektrische vracht- en bestelwagens (emissievrij) tot en met 4.250 kg","vuilniswagens","straatvegers","rioolzuigers","defensievoertuigen","voertuigen met een eendagskenteken, transitokenteken of handelaarskenteken"],"vwt":"De heffing geldt niet voor voertuigen uit een andere voertuigcategorie, zoals bussen en landbouwtrekkers en kampeerwagens. Voor een aantal voertuigen kan de eigenaar vanaf 2026 een ontheffing aanvragen. Dat geldt onder meer voor: Voor een aantal vrachtwagens wordt automatisch een vrijstelling geregeld. Voor voertuigen met een vrijstelling hoeft geen vrachtwagenheffing betaald te worden. Het gaat om:","wat":["Bent u eigenaar van een vrachtwagen? In Nederland is de vrachtwagenheffing op 1 juli 2026 gestart. Eigenaren van vrachtwagens betalen nu per gereden kilometer. Eigenaren van deze vrachtwagens moeten een bedrag per gereden kilometer betalen op:","• vrijwel alle snelwegen\n• een aantal provinciale wegen\n• een aantal gemeentelijke wegen","De heffing geldt voor Nederlandse én buitenlandse voertuigen in de categorieën N2 en N3. Deze hebben een technische maximummassa (TMM) van meer dan 3.500 kilo. U vindt de voertuigcategorie op het kentekenbewijs.","Het Eurovignet voor Nederland is gestopt op 1 juli 2026. Ook betaalt u geen motorrijtuigenbelasting voor vrachtwagens tot 12.000 kilo meer. En de motorrijtuigenbelasting voor vrachtwagens van 12.000 kilo en zwaarder is een stuk lager. In veel andere Europese landen geldde al een vrachtwagenheffing, zoals in Duitsland en België.","Om vrachtwagenheffing te betalen, heeft u het volgende nodig:","• een contract met een aanbieder (dit kan vanaf begin 2026), de aanbieder stuurt u de rekening en geeft het geld door aan de overheid\n• boordapparatuur (on-board-unit, OBU, tolkastje) die de afgelegde kilometers registreert, deze apparatuur krijgt u van de aanbieder","De vrachtwagenheffing is bedoeld om eigenaren van een vrachtwagen uit Nederland en het buitenland te laten betalen per gereden kilometer. De heffing draagt ook bij aan het verduurzamen en efficiënter maken van de sector. Hoe schoner en lichter uw vrachtwagen(s), hoe lager het bedrag per kilometer.","Dit gaat u betalen","Bij vrachtwagenheffing betaalt u een bedrag per gereden kilometer. De hoogte van het bedrag hangt af van het gewicht en de uitstoot van de vrachtwagen.","Subsidies verduurzaming","Een groot deel van het geld dat de heffing opbrengt, gaat naar subsidies voor verduurzaming en innovatie van de wegtransportsector. Bijvoorbeeld voor de aanschaf van elektrische of waterstoftrucks en laadpalen. Voor 2026 is er ruim € 253 miljoen beschikbaar. Zie de subsidies verder op deze pagina."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-119.html","text":"Besluit inwerkingtreding nog niet in werking getreden artikelen Wet vrachtwagenheffing (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-38.html","text":"Besluit inwerkingtreding Wet vrachtwagenheffing, Wet wijziging Wet vrachtwagenheffing voor Europese tolheffingsregels (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-6.html","text":"Besluit wijziging Besluit vrachtwagenheffing voor implementatie herziene Europese tolheffingsregels (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-402.html","text":"Wet wijziging Wet vrachtwagenheffing voor implementatie herziene Europese tolheffingsregels (Overheid.nl)"}],"en":"https://business.gov.nl/regulations/truck-toll/","mod":"2026-09-16"},{"id":"verkoop-consumentenvuurwerk-stopt-door-vuurwerkverbod","t":"Verkoop consumentenvuurwerk stopt door vuurwerkverbod","d":"2026-08-01","dn":"","sec":["detailhandel-groothandel-en-ambachten","cultuur-amusement-sport-en-media"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/verkoop-consumentenvuurwerk-stopt-door-vuurwerkverbod/","sh":"Deze wet is ingegaan: zorg dat u aan de regels voldoet","se":"Deze wet is ingegaan. U moet aan de regels voldoen. De overheid controleert dit.","ph":"ingegaan","vw":["vuurwerkverkopers","importeurs en distributeurs van vuurwerk","organisatoren van vuurwerkevenementen","verenigingen en stichtingen met vuurwerkactiviteiten"],"vwt":"","wat":["Verkoopt u consumentenvuurwerk of werkt u in de vuurwerkbranche? Dan heeft u te maken met een landelijk vuurwerkverbod voor consumenten. De Eerste Kamer heeft ingestemd met de Wet veilige jaarwisseling. Hierdoor stopt vanaf de jaarwisseling 2026/2027 de verkoop van consumentenvuurwerk aan consumenten.","F1-vuurwerk blijft wel toegestaan. Dit zijn lichte vuurwerkartikelen, zoals sterretjes en trektouwtjes.","De belangrijkste veranderingen op een rij:","• De verkoop van consumentenvuurwerk aan consumenten stopt.\n• Consumenten mogen geen consumentenvuurwerk meer afsteken.\n• F1-vuurwerk blijft toegestaan.\n• Professionele vuurwerkshows blijven mogelijk.\n• Verenigingen en stichtingen kunnen mogelijk een uitzondering krijgen voor vuurwerkactiviteiten.","Wat betekent dit voor u?","• Verkoopt u consumentenvuurwerk? Dan mag u dit niet meer aan consumenten verkopen.\n• Importeert of distribueert u consumentenvuurwerk? Dan moet u stoppen met activiteiten die te maken hebben met verkoop aan consumenten.\n• Organiseert u professionele vuurwerkshows? Dat mag nog steeds onder voorwaarden.\n• Bent u een vereniging of stichting die vuurwerkactiviteiten organiseert? Dan kunt u mogelijk een uitzondering aanvragen."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-168-n1.html","text":"Verbeterblad Besluit veilige jaarwisseling (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-169.html","text":"Besluit inwerkingtreding Wet veilige jaarwisseling (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-168.html","text":"Besluit veilige jaarwisseling (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-7.html","text":"Wet veilige jaarwisseling (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/no-sales-consumer-fireworks-due-to-ban/","mod":"2026-11-06"},{"id":"ppwr-stelt-strenger-eisen-aan-verpakkingen","t":"PPWR stelt strengere eisen aan verpakkingen","d":"2026-08-12","dn":"","sec":[],"sub":["bedrijfsvoering"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/ppwr-stelt-strenger-eisen-aan-verpakkingen/","sh":"Deze Europese wet geldt nu: zorg dat u aan de regels voldoet","se":"Deze Europese Verordening is ingegaan en geldt direct voor uw bedrijf. U moet nu helemaal aan deze regels voldoen.","ph":"ingegaan","vw":["fabrikanten van verpakkingen","importeurs","distributeurs","ondernemers die verpakkingen op de markt brengen","ondernemers die verpakkingen gebruiken"],"vwt":"","wat":["Sinds 12 augustus 2026 gelden de eerste verplichtingen uit de Europese Packaging and Packaging Waste Regulation (PPWR).","De PPWR moet ervoor zorgen dat verpakkingen duurzamer worden. Ook moeten in de hele Europese Unie dezelfde regels gaan gelden. Veel bedrijven die verpakkingen maken, op de markt brengen of gebruiken, kunnen te maken krijgen met de nieuwe regels.","De eerste verplichtingen zijn onder andere:","• Fabrikanten moeten voor hun verpakkingen een conformiteitsbeoordeling hebben afgerond en een conformiteitsverklaring opstellen.\n• Fabrikanten moeten technische documentatie over hun verpakkingen opstellen en bewaren. Daarin staat informatie waarmee zij kunnen aantonen dat de verpakking aan de eisen van de PPWR voldoet.\n• Fabrikanten moeten zich houden aan de grenswaarden voor PFAS in verpakkingen.\n• Bedrijven moeten bepalen welke rol of rollen zij hebben in de verpakkingsketen. Een bedrijf kan meerdere rollen hebben.\n• Welke verplichtingen gelden, hangt af van de rol van het bedrijf en de soorten verpakkingen.","Niet alle regels zijn al uitgewerkt. De Europese Unie werkt de PPWR de komende jaren verder uit. Daardoor volgen tot en met 2029 nog aanvullende regels.","Bereid u daarom op tijd voor. Bekijk het overzicht van Verpact om te bepalen welke rol uw bedrijf heeft. Uw rol bepaalt met welke nieuwe regels u te maken krijgt. Ontwikkelt u nieuwe verpakkingen of investeert u in verpakkingsmachines? Houd dan alvast rekening met de nieuwe Europese regels.","Verpact voert de uitgebreide producentenverantwoordelijkheid (UPV) voor verpakkingen uit namens bedrijven die verpakken. Bekijk bij Verpact het complete overzicht van alle wijzigingen die volgen uit de PPWR."],"doen":[],"law":[{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=OJ:L_202500040","text":"Verordening (EU) 2025/40 over verpakkingen en verpakkingsafval (PPWR) (EU)"}],"en":"https://business.gov.nl/amendments/ppwr-imposes-stricter-requirements-packaging/","mod":"2026-09-22"},{"id":"cer-richtlijn-beschermt-kritieke-infrastructuur-tegen-fysieke-risicos","t":"CER-richtlijn beschermt kritieke infrastructuur tegen fysieke risico’s","d":"2026-08-15","dn":"derde kwartaal van 2026","sec":[],"sub":["bedrijfsvoering"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/cer-richtlijn-beschermt-kritieke-infrastructuur-tegen-fysieke-risicos/","sh":"De wet is nu ingegaan: zorg dat u aan de regels voldoet","se":"De Nederlandse wet (op basis van de EU-regels) is ingegaan. Uw bedrijf moet nu aan de regels voldoen.","ph":"ingegaan","vw":["organisaties – de zogenoemde ‘kritieke’ entiteiten, die essentiële diensten verlenen"],"vwt":"","wat":["Steeds vaker staat de veiligheid van onze samenleving en economie onder druk. Daarom is er door de Europese Unie gewerkt aan twee richtlijnen:","• de Critical Entities Resilience directive (CER-richtlijn)\n• de Network and Information Security directive (NIS2-richtlijn)","Deze richtlijnen hebben als doel om de fysieke, digitale en economische weerbaarheid van de landen van de EU te verbeteren.","De CER-richtlijn is op genomen in de Nederlands Wet weerbaarheid kritieke entiteiten. Het moet bedrijven in onmisbare sectoren beschermen tegen fysieke risico’s, zoals de gevolgen van (terroristische) misdrijven, sabotage en natuurrampen.","Welke sectoren en organisaties vallen onder de CER-richtlijn?","De CER-richtlijn richt zich op het verhogen van de fysieke weerbaarheid van organisaties die essentiële diensten verlenen, zogenaamde 'kritieke entiteiten', binnen de volgende sectoren:","• energie\n• drinkwater\n• transport\n• digitale infrastructuur\n• levensmiddelenindustrie\n• gezondheidszorg\n• infrastructuur voor de financiële markt\n• afvalwater\n• overheidsdiensten\n• bankwezen\n• ruimtevaart","De ministeries die verantwoordelijk zijn voor deze sectoren bepalen welke organisaties als kritieke entiteit worden aangewezen. Dat gebeurt met een risicobeoordeling. Daarbij kijken zij onder meer in welke mate een organisatie een dienst verleent die onmisbaar is voor het functioneren van maatschappelijke functies en/of economische activiteiten. Heeft de overheid uw bedrijf in het verleden al aangemerkt als ‘vitale aanbieder’? Dan wordt uw bedrijf in elk geval aangewezen als kritieke entiteit, als u binnen 1 van de bovengenoemde sectoren actief bent.","Is uw bedrijf aangewezen als kritieke entiteit? Dan krijgt u hierover bericht van het verantwoordelijke ministerie. Dit gebeurt zo snel mogelijk na de inwerkingtreding van de wet. Na aanwijzing hebben organisaties nog 10 maanden om aan de wet te voldoen.","Welke verplichtingen schrijft de CER-richtlijn voor?","De CER-richtlijn schrijft een aantal belangrijke verplichtingen voor, zoals:","• Zorgplicht – Ondernemingen moeten zelf een risicobeoordeling uitvoeren en maatregelen nemen om incidenten te voorkomen, de gevolgen te beperken en na een incident te herstellen. Ook moeten zij onder meer gebouwen, infrastructuur en personeel beschermen.\n• Meldplicht - Ondernemingen moeten incidenten die hun essentiële dienstverlening aanzienlijk verstoren of kunnen verstoren binnen 24 uur melden bij de bevoegde autoriteit. Of een incident gemeld moet worden, hangt onder andere af van het aantal getroffen gebruikers, de duur van de verstoring en het getroffen geografische gebied.\n• Toezicht - Organisaties die onder de CER-richtlijn vallen komen onder toezicht te staan. Bij het toezicht wordt gekeken of de verplichtingen uit de richtlijn, zoals de zorg- en meldplicht, worden nageleefd.","Wat doet de overheid?","De CER-richtlijn verplicht de landen van de EU om kritieke, essentiële en belangrijke organisaties te helpen bij het verbeteren van hun weerbaarheid tegen fysieke risico’s. De overheid moet elke 4 jaar voor iedere sector een risicobeoordeling uitvoeren en die delen met kritieke entiteiten in die sector. De overheid kan verder ondersteuning geven door informatie-uitwisseling, het maken van richtlijnen en het aanbieden van instrumenten om de weerbaarheid van organisaties te verhogen, bijvoorbeeld voor het uitvoeren van een risicobeoordeling.","Wat kunnen organisaties doen om zich voor te bereiden?","Organisaties kunnen zich alvast voorbereiden op hun zorgplicht. Dat kunnen zij doen door maatregelen te nemen die de veiligheid en weerbaarheid van hun processen en diensten verbeteren. Bijvoorbeeld:","• Risico’s inventariseren en analyseren.\n• Bedrijfscontinuïteitplannen en protocollen voor crisisbeheersing schrijven en incident response organiseren.\n• Alternatieve toeleveringsketens identificeren.\n• Personeel bewust maken van de risico’s en de te nemen maatregelen.\n• Budget en capaciteit reserveren die nodig zijn om aan de richtlijn te voldoen."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-190.html","text":"Besluit weerbaarheid kritieke entiteiten (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-188.html","text":"Wet weerbaarheid kritieke entiteiten (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/regelingweerbaarheidkritiekeentiteitenzorg/b1","text":"Consultatie Regeling weerbaarheid kritieke entiteiten zorg (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/regeling_weerbaarheid_kritieke_entiteiten_ienw/b1","text":"Consultatie Regeling weerbaarheid kritieke entiteiten IenW (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/cer-directive-protects-critical-infrastructure/","mod":"2026-11-10"},{"id":"nis2-richtlijn-beschermt-netwerk-en-informatiesystemen-tegen-cyberbeveiligingsrisicos","t":"Meer bedrijven in kritieke sectoren hebben verplichtingen voor cyberbeveiliging (NIS2)","d":"2026-08-15","dn":"derde kwartaal van 2026","sec":[],"sub":["bedrijfsvoering"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/nis2-richtlijn-beschermt-netwerk-en-informatiesystemen-tegen-cyberbeveiligingsrisicos/","sh":"De wet is nu ingegaan: zorg dat u aan de regels voldoet","se":"De Nederlandse wet (op basis van de EU-regels) is ingegaan. Uw bedrijf moet nu aan de regels voldoen.","ph":"ingegaan","vw":["uw organisatie actief is in 1 van de sectoren in bijlage 1 van de NIS2-richtlijn of bijlage 2 van de NIS2-richtlijn, en","u heeft een middelgrote organisatie met minimaal 50 werknemers of een jaaromzet en balanstotaal van meer dan € 10 miljoen, of","u heeft een grote organisatie met meer dan 250 werknemers of een netto omzet van meer dan € 50 miljoen en een balanstotaal van meer dan € 43 miljoen."],"vwt":"De NIS2-richtlijn geldt voor sectoren die al onder de eerste NIS-richtlijn vallen en daar zijn nu sectoren bijgekomen. Uw organisatie valt automatisch onder de NIS2-richtlijn als: In bijlage 1 van de NIS2-richtlijn staan deze zeer kritieke sectorenenergietransportbankwezeninfrastructuur financiële marktgezondheidszorgdrinkwaterdigitale infrastructuurbeheerders van ict-dienstenafvalwateroverheidsdienstenruimtevaartIn bijlage 2 van de NIS2-richtlijn staan deze kritieke sectorendigitale aanbiederspost- en koeriersdienstenafvalstoffenbeheerlevensmiddelenchemische stoffenonderzoekvervaardiging/productie Deze micro- en kleine bedrijven vallen automatisch onder de NIS2-richtlijnaanbieders van vertrouwensdienstenregisters voor toplevel domeinnamenverleners van domeinnaamregistratiedienstenaanbieders van openbare elektronische communicatienetwerkenaanbieders van openbare elektronische communicatiedienstenVoor micro- en kleinbedrijven die niet bij een sector horen die automatisch onder de NIS2-richtlijn valt, geldt de NIS2-richtlijn in principe niet. De minister die verantwoordelijk is voor een bepaalde sector kan er wel voor kiezen om een micro- of kleinbedrijf aan te wijzen. Dan valt deze alsnog onder de NIS2-richtlijn. Dit gebeurt na een risicobeoordeling, bijvoorbeeld als blijkt dat hun dienstverlening van cruciaal belang is voor de Nederlandse economie of maatschappij. Als dat zo is, krijgt u hierover bericht. Geldt de NIS2-richtlijn voor uw organisatie?Doe de NIS2 Zelfevaluatie en daarna weet u:Is de NIS2-richtlijn van toepassing op uw organisatie?Is uw organisatie Essentieel of Belangrijk?Valt uw organisatie onder Nederlands toezicht?","wat":["Meer bedrijven en organisaties in kritieke sectoren krijgen verplichtingen (zorgplicht en meldplicht) om de cybersecurity te vergroten en cyberaanvallen tegen te gaan. Deze verplichtingen staan in de Network and Information Security directive (NIS2-richtlijn).","Wat is de NIS2-richtlijn?","Deze NIS2-richtlijn moet meehelpen aan een hoger niveau van cybersecurity voor netwerk- en informatiesystemen bij bedrijven en organisaties. De NIS2-richtlijn moet ervoor zorgen dat de EU-landen zich beter beschermen tegen dreigingen die de samenleving of economie kunnen verstoren of ontwrichten."],"doen":["Als uw organisatie onder de NIS2-richtlijn valt, gelden deze regels:","U heeft een zorgplicht.Organisaties moeten passende en evenredige maatregelen nemen om de risico’s voor de beveiliging van hun netwerk- en informatiesystemen te beheersen. Ook moeten zij deze maatregelen nemen om incidenten te voorkomen of de gevolgen daarvan te beperken.U heeft een meldplicht.Organisaties moeten significante incidenten binnen de wettelijke termijnen melden aan hun CSIRT en hun bevoegde autoriteit. Zij kunnen dit doen via het meldportaal van het NCSC. In de ministeriële regelingen van de betrokken vakministers zijn drempelwaarden opgenomen om te bepalen wanneer een incident significant is. Deze drempelwaarden kunnen per sector verschillen. U komt onder toezicht te staan.Dit toezicht houdt in dat wordt gekeken of u zich aan de verplichtingen uit de NIS2-richtlijn houdt. Zoals de zorg- en meldplicht. Op dit moment wordt uitgewerkt welke sectoren onder welke toezichthouder komen te vallen.","Voorbereiden op de NIS2Wacht niet af, maar ga nu al aan de slag met de cyberweerbaarheid van uw organisatie. Beantwoord de vragen in de NIS2 Quickscan en controleer hoe de cyberbeveiliging van uw organisatie ervoor staat. U krijgt adviezen en hulpmiddelen om te voldoen aan de NIS2-wetgeving."],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-189.html","text":"Cyberbeveiligingsbesluit (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-187.html","text":"Cyberbeveiligingswet (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/regelingcyberbeveiligingez/b1","text":"Consultatie Regeling cyberbeveiliging EZ (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/cyberbeveiligingsregelingzorg/b1","text":"Consultatie Cyberbeveiligingsregeling in de Zorg (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/nis2-directive-protects-network-information-systems/","mod":"2026-09-22"},{"id":"eevidence-verplicht-bedrijven-digitaal-bewijs-te-verstrekken","t":"eEvidence verplicht bedrijven digitaal bewijs te verstrekken","d":"2026-08-18","dn":"","sec":["zakelijke-dienstverlening"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/eevidence-verplicht-bedrijven-digitaal-bewijs-te-verstrekken/","sh":"Deze Europese wet geldt nu: zorg dat u aan de regels voldoet","se":"Deze Europese Verordening is ingegaan en geldt direct voor uw bedrijf. U moet nu helemaal aan deze regels voldoen. Let op: u kunt uw bedrijf pas in het 1e kwartaal van 2027 registreren.","ph":"ingegaan","vw":["aanbieders van internet- en communicatiediensten in de EU","bedrijven die cloud- of opslagdiensten leveren","platforms voor online communicatie of marktplaatsen","organisaties die domeinnamen of IP-diensten beheren"],"vwt":"","wat":["Werkt u met digitale diensten in de EU? Als uw organisatie elektronische communicatiediensten, online platforms, cloudopslag of diensten rond internetdomeinen aanbiedt, heeft u te maken met nieuwe EU-regels over digitaal bewijs. Deze regels staan in de eEvidence-verordening en richtlijn.","De eEvidence-wetgeving zorgt ervoor dat digitaal bewijs sneller en makkelijker gedeeld kan worden tussen landen. Dat helpt bij opsporing en vervolging van strafbare feiten.","Wat betekent dit voor u?","• Sinds 18 augustus 2026 heeft u te maken met nieuwe regels voor het delen van digitaal bewijsmateriaal met justitiële autoriteiten in andere EU-landen.\n• U moet zich inschrijven in een Europees register (Court Database, CDB) zodat autoriteiten uw organisatie kunnen vinden.\n• U moet uw systemen zo inrichten dat u gevraagd digitaal bewijs kunt overleggen binnen vastgestelde termijnen.\n• Autoriteiten kunnen een Europees verstrekkingsbevel of bewaringsbevel geven om digitaal bewijs te leveren of te bewaren.\n• U krijgt mogelijk snelle verzoeken direct uit andere EU-landen om data te delen.","Blijvende verplichtingen","• De regels gelden voor data die opgeslagen is en gebruikt kan worden in strafzaken. Denk aan e-mailgegevens, contactinformatie, IP-adressen en communicatiegegevens.\n• U moet op tijd reageren op verzoeken van justitiële autoriteiten.\n• U moet zich blijven houden aan privacy- en veiligheidsregels bij het delen van data."],"doen":[],"law":[{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/?uri=uriserv%3AOJ.L_.2023.191.01.0181.01.NLD&toc=OJ%3AL%3A2023%3A191%3AFULL","text":"Richtlijn (EU) 2023/1544 (EU)"},{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/?uri=uriserv%3AOJ.L_.2023.191.01.0118.01.NLD&toc=OJ%3AL%3A2023%3A191%3AFULL","text":"Verordening (EU) 2023/1543 (EU)"}],"en":"https://business.gov.nl/amendments/eevidence-requires-businesses-to-provide-digital-proof/","mod":"2026-08-18"},{"id":"tijdelijk-lagere-vrachtwagenheffing","t":"Tijdelijk lagere vrachtwagenheffing","d":"2026-09-01","dn":"","sec":["vervoer"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/tijdelijk-lagere-vrachtwagenheffing/","sh":"Deze wet is ingegaan: zorg dat u aan de regels voldoet","se":"Deze wet is ingegaan. U moet aan de regels voldoen. De overheid controleert dit.","ph":"ingegaan","vw":["ondernemers die vrachtwagenheffing moeten betalen"],"vwt":"","wat":["Het kabinet heeft de tarieven van de vrachtwagenheffing tijdelijk met 22,3% verlaagd. Ondernemers die vrachtwagenheffing betalen, hebben hierdoor lagere kosten. Aanleiding zijn de sterk gestegen brandstofprijzen door het conflict in het Midden-Oosten.","Bekijk hoeveel u moet betalen bij RDW."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/temporary-reduction-in-truck-toll/","mod":"2026-10-14"},{"id":"duurzaamheidsclaims-moeten-duidelijk-en-controleerbaar-zijn","t":"Duurzaamheidsclaims moeten duidelijk en controleerbaar zijn","d":"2026-09-27","dn":"","sec":[],"sub":["klimaat-energie-en-natuur"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/duurzaamheidsclaims-moeten-duidelijk-en-controleerbaar-zijn/","sh":"De wet is nu ingegaan: zorg dat u aan de regels voldoet","se":"De Nederlandse wet (op basis van de EU-regels) is ingegaan. Uw bedrijf moet nu aan de regels voldoen.","ph":"ingegaan","vw":["ondernemers die producten of diensten verkopen aan consumenten","webshops en retailers","bedrijven die duurzaamheidsclaims gebruiken in reclame of marketing"],"vwt":"","wat":["Bent u ondernemer en claimt u dat uw product, dienst of bedrijf duurzaam is? U heeft te maken met strengere regels voor duurzaamheidsclaims. De Europese Unie wil consumenten zo beter beschermen tegen het kopen van producten die minder duurzaam zijn dan de verkoper beweert.","De belangrijkste veranderingen op een rij:","• U mag geen vage duurzaamheidsclaims meer gebruiken zonder duidelijke uitleg. Woorden zoals duurzaam, groen of milieuvriendelijk mag u alleen gebruiken als u ze onderbouwt met controleerbaar bewijs.\n• U moet bewijs van duurzaamheidsclaims beschikbaar hebben als een toezichthouder hierom vraagt.\n• U mag geen duurzaamheidsclaims gebruiken die niet kloppen of die consumenten kunnen misleiden over de milieuprestaties van een product of dienst.\n• U mag alleen nog duurzaamheidslabels gebruiken die betrouwbaar en onafhankelijk zijn. Deze labels moeten door een onafhankelijke partij of overheidsorganisatie zijn erkend. Bijvoorbeeld: het EU-ecolabel voor onder andere elektronica en textiel. Eigen labels zonder controle zijn niet toegestaan.\n• U moet duidelijk en volledig zijn over de duurzaamheid van uw product. U mag geen informatie weglaten die belangrijk is voor de consument."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-204.html","text":"Besluit inwerkingtreding Implementatiewet richtlijn betere duurzaamheidsinformatie voor consumenten (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-152.html","text":"Implementatiewet richtlijn betere duurzaamheidsinformatie voor consumenten (Overheid.nl)"},{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=OJ:L_202400825","text":"Richtlijn (EU) 2024/825 (Empowering the Consumer for the Green Transition/EmpCo Richtlijn/ECGT Richtlijn) (EU)"}],"en":"https://business.gov.nl/amendments/sustainability-claims-must-be-clear-and-easy-to-verify/","mod":"2026-11-03"},{"id":"verkopers-moeten-consumenten-informeren-over-garantie","t":"Verkopers moeten consumenten informeren over garantie","d":"2026-09-27","dn":"","sec":["detailhandel-groothandel-en-ambachten"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/verkopers-moeten-consumenten-informeren-over-garantie/","sh":"De wet is ingegaan: zorg dat u aan de regels voldoet","se":"De Nederlandse wet (op basis van de EU-regels) is ingegaan. Uw bedrijf moet nu aan de regels voldoen.","ph":"ingegaan","vw":["winkeliers die producten verkopen aan consumenten","webshops die producten verkopen aan consumenten"],"vwt":"","wat":["Verkoopt u producten aan consumenten? Dan moet u hen duidelijker informatie geven over hun recht op wettelijke garantie en mogelijke extra garantie van de fabrikant. Hiervoor moet u nieuwe Europese garantielabels gebruiken. Dit geldt voor winkels en webshops.","Er zijn 2 soorten garantielabels:","• Kennisgeving over wettelijke garantie: deze is altijd verplicht. Hiermee geeft u klanten informatie over hun wettelijke garantierechten.\n• EU GARAN-label: dit label is onder bepaalde voorwaarden verplicht. Het geeft informatie over extra garantie van de fabrikant.","Kennisgeving over wettelijke garantie","U moet de kennisgeving over wettelijke garantie duidelijk laten zien voordat de consument een product koopt. Hiervoor gebruikt u een standaard Europees document met een QR-code. U hoeft dit document niet zelf in te vullen.","• In uw winkel: plaats de kennisgeving op een goed zichtbare plek, bijvoorbeeld bij de kassa. Gebruik minimaal A4-formaat.\n• In uw webshop: zorg dat de kennisgeving opvalt op een goed zichtbare plek, bijvoorbeeld op de productpagina. U mag ook een duidelijke link gebruiken die naar de kennisgeving leidt. Alleen een vermelding in de algemene voorwaarden is niet voldoende.","Met de QR-code kan de consument meer informatie lezen over wettelijke garantie. In uw webshop moet u ook een klikbare link naar dezelfde informatie plaatsen.","U moet de kennisgeving ook na aankoop aan de consument geven, bijvoorbeeld per e-mail.","EU GARAN-label voor extra garantie","Het EU GARAN-label is verplicht als:","• de fabrikant meer dan 2 jaar gratis garantie geeft\n• de garantie voor het hele product geldt\n• de fabrikant u over deze garantie heeft geïnformeerd","U hoeft niet zelf bij de fabrikant naar deze informatie te zoeken.","Op het label vult u de garantieduur, de naam van de fabrikant en de naam van het model in.","In uw winkel moet het label duidelijk zichtbaar bij het juiste product staan. In uw webshop moet u het label tonen direct voordat de consument bestelt. Ook na aankoop moet u het volledige label aan de consument geven, bijvoorbeeld per e-mail. Alleen een link naar het label is niet voldoende.","Gebruik de officiële Europese garantielabels. Op de website van de ACM vindt u de labels en uitleg over hoe u deze moet gebruiken. U mag de kleuren, vormgeving, teksten en QR-codes niet zelf aanpassen."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-204.html","text":"Besluit inwerkingtreding Implementatiewet richtlijn betere duurzaamheidsinformatie voor consumenten (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-152.html","text":"Implementatiewet richtlijn betere duurzaamheidsinformatie voor consumenten (Overheid.nl)"},{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=OJ:L_202400825","text":"Richtlijn (EU) 2024/825 EmpCo-richtlijn (Empowering Consumers for the Green Transition) (EU)"}],"en":"https://business.gov.nl/amendments/retailers-must-inform-consumers-about-guarantee/","mod":"2026-11-10"},{"id":"meer-partijen-aansprakelijk-voor-gebrekkige-producten","t":"Meer partijen aansprakelijk voor gebrekkige producten","d":"2026-12-09","dn":"nog niet bekend","sec":[],"sub":["product-dienst-en-innovatie"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/meer-partijen-aansprakelijk-voor-gebrekkige-producten/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["fabrikanten en importeurs","ontwikkelaars en verkopers van software en AI","fulfilmentbedrijven, distributeurs en onlineplatforms","gemachtigden van fabrikanten in de EU"],"vwt":"","wat":["Bent u fabrikant, importeur, distributeur of verkoopt u software of producten met kunstmatige intelligentie (AI)? Dan krijgt u te maken met nieuwe regels voor productaansprakelijkheid. De wet is aangepast zodat consumenten beter worden beschermd als zij schade lijden door een gebrekkig product. Ook komt er meer rechtszekerheid voor bedrijven en een meer gelijk speelveld binnen de Europese Unie (EU).","Dit verandert er voor u als ondernemer:","• Meer producten vallen onder de productaansprakelijkheidNaast gewone fysieke producten gelden de regels nu ook voor software en systemen met kunstmatige intelligentie (AI). Ontwikkelt of verkoopt u software of AI-producten? Dan bent u misschien aansprakelijk als deze producten schade aan consumenten veroorzaken.\n• Meer bedrijven kunnen aansprakelijk zijnOnder de nieuwe productaansprakelijkheidsregeling kunnen er voor producten van buiten de EU meer partijen aansprakelijk zijn dan onder de oude regeling. Zo kunnen ook in de EU gevestigde gemachtigden van fabrikanten en, onder voorwaarden, fulfilmentdienstverleners worden aangesproken. Ook onlineplatforms kunnen onder voorwaarden aansprakelijk zijn, zonder zelf een andere rol in de distributieketen te vervullen. Controleer dus goed welke rol uw bedrijf speelt in de distributieketen.\n• Vergoeding voor meer soorten schadeDe oude regeling geldt kort gezegd voor letsel- en overlijdensschade en voor schade aan andere producten die worden gebruikt in de privésfeer boven € 500. U kunt onder de nieuwe regeling ook een schadevergoeding moeten betalen voor schade aan andere producten lager dan € 500 en voor schade aan gegevens (die niet voor een beroep worden gebruikt). Als door uw gebrekkige product gegevens worden vernietigd of beschadigd, bijvoorbeeld als ze van een harde schijf zijn verwijderd, bent u daarvoor mogelijk aansprakelijk.","Deze veranderingen kunnen gevolgen hebben voor het risico dat u loopt op productaansprakelijkheid. Controleer daarom goed of uw verzekering nog voldoende dekking biedt."],"doen":[],"law":[{"href":"https://www.eerstekamer.nl/9370000/1/j9vvkfvj6b325az/vmvifheuxiyp","text":"Implementatiewet richtlijn herziening productaansprakelijkheid (Eerste Kamer)"},{"href":"https://www.internetconsultatie.nl/implementatierichtlijnherzieningproductaansprakelijkheid/b1","text":"Consultatie Implementatiewet richtlijn herziening productaansprakelijkheid (Overheid.nl)"},{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=OJ:L_202402853","text":"Richtlijn Productaansprakelijkheid (EU) 2024/2853 (EU)"}],"en":"https://business.gov.nl/amendments/more-parties-liable-for-defective-products/","mod":"2026-11-12"},{"id":"door-eudr-alleen-nog-import-van-ontbossingsvrije-producten","t":"Door EUDR alleen nog import van ontbossingsvrije producten","d":"2026-12-30","dn":"","sec":[],"sub":["internationaal-ondernemen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/door-eudr-alleen-nog-import-van-ontbossingsvrije-producten/","sh":"Deze Europese wet is goedgekeurd: bereid uw bedrijf voor","se":"Dit is een Europese Verordening. Deze wet is goedgekeurd in Europa. Er is vaak een overgangstermijn van 1 of 2 jaar, maar de regels staan vast. U moet uw bedrijf aanpassen.","ph":"vast","vw":["importeurs en handelaren die producten of grondstoffen binnen de EU willen importeren, exporteren of produceren, met als doel om ze in de handel te brengen"],"vwt":"","wat":["Importeert u goederen van buiten de EU? Mogelijk moet u bewijzen dat uw producten ontbossingsvrij zijn.","Volgens de Regulation on Deforestation-free products (EUDR) mag u alleen goederen en producten op de markt brengen, die niet zorgen voor ontbossing of aantasting van bossen. Daarnaast moeten de producten legaal geproduceerd zijn. Producten die afkomstig zijn uit gebieden die na 30 december 2020 zijn ontbost, mag u niet op de EU-markt brengen en niet exporteren.","De EUDR is van toepassing op de volgende 7 grondstoffen:","• runderen\n• palmolie\n• soja\n• cacao\n• koffie\n• rubber\n• hout","De EUDR geldt ook voor afgeleide producten zoals leer, chocolade en meubels.","Bedrijven die handelen in deze grondstoffen of afgeleide producten, moeten bewijzen dat hun producten ontbossingsvrij zijn met een zorgvuldigheidsverklaring. Lees hoe u dit moet doen in Verordening ontbossingsvrije producten (EUDR): wat betekent dit voor u?"],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-45.html","text":"Besluit uitvoering verordening ontbossingsvrije grondstoffen en producten (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2024-242.html#d17e386","text":"Wet uitvoering verordening ontbossingsvrije grondstoffen en producten (Overheid.nl)"},{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=CELEX%3A32023R1115","text":"EU Verordening 2023/1115 Ontbossingsverordening EUDR (EU)"}],"en":"https://business.gov.nl/amendments/only-imports-deforestation-free-products-allowed-eudr/","mod":"2026-08-19"},{"id":"laag-uurtarief-van-zzper-kan-leiden-tot-arbeidsovereenkomst","t":"Laag uurtarief van zzp'er kan leiden tot arbeidsovereenkomst","d":"2026-12-31","dn":"nog niet bekend","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/laag-uurtarief-van-zzper-kan-leiden-tot-arbeidsovereenkomst/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is officieel aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["opdrachtgevers die werken met zzp'ers","zzp'ers"],"vwt":"","wat":["Werkt u met zzp'ers? Dan veranderen de regels voor de beoordeling van een arbeidsovereenkomst. Bij een uurtarief lager dan € 38 geldt straks een rechtsvermoeden van een arbeidsovereenkomst. Dat betekent dat een zzp’er met een laag uurtarief eerder wordt gezien als werknemer. Zo wil de overheid schijnzelfstandigheid tegengaan en zzp'ers beter beschermen.","Let op: Het bedrag was eerst € 36 per uur. Dit bedrag stijgt mee met het wettelijk minimumloon en is sinds 1 januari 2026 € 38 per uur.","De belangrijkste veranderingen zijn:","• Verdient een zzp'er minder dan € 38 per uur? Dan kan deze een beroep doen op het rechtsvermoeden van een arbeidsovereenkomst.\n• Doet een zzp'er een beroep op het rechtsvermoeden? Dan moet u bewijzen dat geen sprake is van een arbeidsovereenkomst.\n• Kunt u dat niet bewijzen? Dan kan de zzp'er aanspraak maken op de rechten die horen bij een arbeidsovereenkomst, zoals loondoorbetaling bij ziekte en ontslagbescherming."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-207.html","text":"Besluit inwerkingtreding Wet wijziging Boek 7 BW voor invoeren rechtsvermoeden arbeidsovereenkomst op basis van uurtarief (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-158.html","text":"Wet wijziging Boek 7 BW voor invoeren rechtsvermoeden arbeidsovereenkomst op basis van uurtarief (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/wetverduidelijkingbeoordelingarbeidsrelatiesenrechtsvermoeden/b1","text":"Consultatie Wet verduidelijking beoordeling arbeidsrelaties en rechtsvermoeden (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/low-hourly-rate-for-self-employed-can-lead-to-employment-contract/","mod":"2026-10-08"},{"id":"accijnskorting-op-benzine-en-diesel-verlengd-tot-2028","t":"Accijnskorting op benzine en diesel verlengd tot 2028","d":"2027-01-01","dn":"","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/accijnskorting-op-benzine-en-diesel-verlengd-tot-2028/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["ondernemers die brandstofkosten hebben voor zakelijk rijden"],"vwt":"","wat":["Het kabinet wil de accijnskorting op benzine en diesel met een jaar verlengen tot 1 januari 2028. Daardoor bedraagt de accijns op een liter benzine € 0,85 en op een liter diesel € 0,55. Vanaf 2028 wordt de korting verlaagd.","De korting op de accijns op LPG wordt niet verlengd.","Het kabinet wil met de verlenging van de accijnskorting autorijden voor iedereen betaalbaar houden."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/reduced-excise-duty-petrol-diesel-extended/","mod":"2026-11-13"},{"id":"alcoholaccijns-stijgt-jaarlijks-mee-met-inflatie","t":"Alcoholaccijns gaat jaarlijks meestijgen met de inflatie","d":"2027-01-01","dn":"","sec":["detailhandel-groothandel-en-ambachten","horeca-recreatie-en-catering"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/alcoholaccijns-stijgt-jaarlijks-mee-met-inflatie/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["verkopers van alcohol","horecaondernemers die alcohol schenken","producenten van alcohol","importeurs van alcohol"],"vwt":"","wat":["Verkoopt u bier, wijn of ander alcoholhoudende dranken? Vanaf 1 januari 2027 stijgt de alcoholaccijns jaarlijks mee met de inflatie. Inflatie is het duurder worden van producten en diensten, waardoor mensen met hetzelfde geld minder kunnen kopen. Als de accijns meestijgt met de inflatie, gaat u ieder jaar een hoger bedrag aan accijns betalen voor dezelfde hoeveelheid alcoholhoudende drank. U kunt de accijns doorberekenen aan uw klant. Het Centraal Bureau voor de Statistiek (CBS) berekent elk jaar hoe hoog de inflatie is en hoeveel de accijns dus stijgt.","Dit geldt voor:","• bier en wijn\n• tussenproducten zoals port, sherry en vermout\n• overige alcoholhoudende producten zoals whisky, wodka en rum"],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/excise-duty-on-alcohol-to-rise-annually-in-line-with-inflation/","mod":"2026-11-13"},{"id":"lagere-belasting-aandelenopties-startups-en-scale-ups","t":"Belasting op aandelenopties start-ups en scale-ups daalt","d":"2027-01-01","dn":"","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/lagere-belasting-aandelenopties-startups-en-scale-ups/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["start-ups en scale-ups die aandelenopties geven aan werknemers"],"vwt":"","wat":["Heeft u een start-up of scale-up? U kunt uw werknemers straks makkelijker belonen met aandelenopties. Met aandelenopties kunnen werknemers financieel meegroeien met uw bedrijf. Als de aandelen na een tijd meer waard zijn, kunnen zij die nog steeds kopen voor het oorspronkelijke bedrag.","De belastingregels veranderen voor aandelen in start-ups en scale-ups en voor het geven van aandelenopties. De belangrijkste veranderingen zijn:","• Lagere belasting op aandelenopties: Uw werknemers betalen minder belasting over aandelenopties. Straks telt een kleiner deel van het voordeel uit aandelenopties mee voor de belasting. Dit maakt aandelenopties aantrekkelijker.\n• Belasting op z’n laatst betalen bij verkoop: Uw werknemers betalen op z’n laatst pas belasting als zij de aandelen uit de aandelenoptierechten verkopen. Dit geeft (oud-)werknemers meer financiële ruimte.","Wilt u gebruikmaken van de nieuwe regels voor aandelenopties? Dan moet uw bedrijf erkend zijn als start-up of scale-up. Hiervoor gelden specifieke voorwaarden. U vraagt hiervoor een beoordeling aan bij de Rijksdienst voor Ondernemend Nederland (RVO). Voldoet uw bedrijf niet meer aan de voorwaarden? Dan moet u dit melden bij RVO.","Een start-up of scale-up is een bedrijf dat bijvoorbeeld:","• gericht is op snelle groei\n• een verdienmodel heeft dat makkelijk kan groeien\n• vernieuwende producten, diensten, processen of technologieën ontwikkelt of verbetert"],"doen":[],"law":[{"href":"https://internetconsultatie.nl/startup/b1","text":"Consultatie Wet fiscale stimulering startups en scale-ups (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/lower-taxation-share-options-start-ups-scale-ups/","mod":"2026-11-13"},{"id":"belasting-op-leidingwater-omhoog","t":"Belasting op leidingwater (BoL) omhoog","d":"2027-01-01","dn":"","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/belasting-op-leidingwater-omhoog/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["ondernemers die leidingwater van drinkwaterkwaliteit gebruiken"],"vwt":"","wat":["Gebruikt u in uw bedrijf leidingwater van drinkwaterkwaliteit? U moet hiervoor belasting op leidingwater (BoL) betalen. Dit doet u via uw drinkwaterrekening. Vanaf 1 januari 2027 wordt deze belasting verhoogd met € 0,11 per kubieke meter geleverd leidingwater. Hierbij is indexering meegerekend. U betaalt dan per kubieke meter € 0,55.","Daarnaast verdwijnt het heffingsplafond voor grootverbruikers helemaal in 2027. Over elke kubieke meter leidingwater van drinkwaterkwaliteit moet u dan belasting betalen.","Deze maatregel draagt onder meer bij aan het zuiniger gebruik van water."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/tap-water-tax-will-go-up/","mod":"2026-11-13"},{"id":"afval-verwerken-wordt-duurder","t":"Belastingen voor afvalverwerking veranderen","d":"2027-01-01","dn":"","sec":[],"sub":["klimaat-energie-en-natuur","belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/afval-verwerken-wordt-duurder/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["afvalverbrandingsinstallaties (AVI’s)","stortplaatsen","bedrijven die afval exporteren"],"vwt":"","wat":["Verbrandt, stort of exporteert u afval? Het kabinet past de maatregelen uit het Belastingplan 2026 aan:","• De CO2-heffing stijgt vanaf 2027 langzamer dan eerst het plan was. Het tarief komt in 2035 uit op € 304 per ton CO2. Eerder zou dit tarief al in 2030 gelden.\n• Vanaf 2028 wordt het tarief van de afvalstoffenbelasting lager:vanaf 2028 € 64 per ton afval (het plan was € 92,82) vanaf 2030 structureel € 81 per ton afval (plan was € 124,20 in 2030 en structureel € 117,10 vanaf 2035)\n• vanaf 2028 € 64 per ton afval (het plan was € 92,82)\n• vanaf 2030 structureel € 81 per ton afval (plan was € 124,20 in 2030 en structureel € 117,10 vanaf 2035)","Afvalverbrandingsinstallaties gaan meer betalen, ten opzichte van huidige belastingtarieven (maar minder dan de tarieven uit het Belastingplan 2026). Zij kunnen (een deel van) deze extra kosten in rekening brengen bij bedrijven en gemeenten die afval laten verwerken.","De kosten voor burgers en bedrijven kunnen lager uitvallen dan gepland in het Belastingplan 2026. Dat hangt af van de kosten die afvalverwerkers bij hun klanten in rekening brengen. Bedrijven kunnen de kosten ook verlagen door minder afval te produceren en afval beter te scheiden.","Door de CO2-heffing blijft het aantrekkelijk om CO2 af te vangen en op te slaan (dit heet CCS)."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-444.html","text":"Belastingplan 2026 (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/taxes-on-waste-processing-are-changing/","mod":"2026-11-13"},{"id":"gezoete-alcoholvrije-dranken-met-vleugje-zuivel-worden-belast","t":"Dranken met vleugje zuivel en gezoete alcoholvrije dranken worden belast","d":"2027-01-01","dn":"","sec":["industrie"],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/gezoete-alcoholvrije-dranken-met-vleugje-zuivel-worden-belast/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["ondernemers die gezoete en aromatische dranken produceren","ondernemers die gezoete en aromatische dranken importeren"],"vwt":"","wat":["Produceert of importeert u dranken met een vleugje zuivel of gezoete zuiveldranken of sojadranken? U gaat verbruiksbelasting betalen. Dit geldt voor:","• vruchtensappen en groentesappen met een vleugje zuivel\n• frisdranken met een vleugje zuivel\n• zuiveldranken die zijn gezoet of gearomatiseerd of met toegevoegde smaakstoffen of geurstoffen\n• sojadranken met een hoog suikergehalte of verzadigd vetgehalte","U moet hiervoor aangifte doen voor de verbruiksbelasting van alcoholvrije dranken.","Nu vallen dranken met een vleugje zuivel en de gezoete zuiveldranken en sojadranken onder de zuiveluitzondering voor de verbruiksbelasting. Deze uitzondering was oorspronkelijk bedoeld voor melkproducten zoals melk en karnemelk. In de praktijk vallen ook gezoete en aromatische dranken met een vleugje melkvet onder de uitzondering. Dat gaat veranderen.","De regering wil dat alleen gezonde dranken zoals melk en karnemelk onder de uitzondering van de verbruiksbelasting vallen."],"doen":[],"law":[{"href":"https://wetten.overheid.nl/BWBR0005802/2027-01-01/0","text":"Wet op de verbruiksbelasting van alcoholvrije dranken (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-444.html","text":"Belastingplan 2026 (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/tax-on-beverages-with-hint-of-dairy-and-sweetened-beverages/","mod":"2026-10-12"},{"id":"extra-belasting-op-uitstotende-leaseautos","t":"Extra belasting op zakelijke benzine- en dieselauto’s voor werknemers","d":"2027-01-01","dn":"","sec":[],"sub":["personeel","belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/extra-belasting-op-uitstotende-leaseautos/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["ondernemers die zakelijke personenauto's met uitstoot (eigen wagenpark of lease) aan werknemers aanbieden die deze auto's ook privé of voor woon-werkverkeer gebruiken"],"vwt":"","wat":["Biedt u een zakelijke personenauto aan uw werknemer, bijvoorbeeld een auto uit uw eigen wagenpark of een leaseauto? En gebruikt uw werknemer de personenauto ook privé of voor woon-werkverkeer? Dan betaalt u vanaf 1 januari 2027 extra belasting op zakelijke auto's met uitstoot of die niet helemaal uitstootvrij zijn. Het gaat om personenauto's met benzine-, diesel- of hybride aandrijving.","De grens van 500 kilometer privégebruik per jaar geldt niet voor deze extra belasting. Woon-werkverkeer telt hierbij als privégebruik.","De belasting is per jaar:","• 12% van de catalogusprijs van de auto bij auto's tot en met 25 jaar oud.\n• 12% van de marktwaarde bij auto's ouder dan 25 jaar.","U betaalt de belasting via de loonheffing (pseudo-eindheffing). U mag deze belasting niet doorberekenen aan uw werknemer.","Het doel van de belasting is dat werkgevers alleen nog zakelijke auto's zonder uitstoot aan hun werknemers aanbieden, zoals volledig elektrische auto's.","Overgangsregeling","Voor zakelijke auto's met uitstoot die u voor 1 januari 2027 al aan uw werknemers beschikbaar heeft gesteld, geldt een overgangsregeling. Vanaf 1 januari 2031 betaalt u de extra belasting ook voor deze auto's. Eerder was dit vanaf 17 september 2030."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-444.html","text":"Belastingplan 2026 (Overheid.nl)"},{"href":"https://wetten.overheid.nl/BWBR0002471/#HoofdstukV","text":"Wet op de loonbelasting 1964, Hoofdstuk 5. Heffing van de inhoudingsplichtige"}],"en":"https://business.gov.nl/amendments/extra-tax-on-fossil-fueled-company-cars/","mod":"2026-10-05"},{"id":"geen-overdrachtsbelasting-als-woningcorporaties-daeb-woningen-overnemen","t":"Geen overdrachtsbelasting als woningcorporaties DAEB-woningen overnemen","d":"2027-01-01","dn":"","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/geen-overdrachtsbelasting-als-woningcorporaties-daeb-woningen-overnemen/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["woningcorporaties die DAEB-woningen overnemen van een andere woningcorporatie"],"vwt":"","wat":["Neemt uw woningcorporatie DAEB-woningen (sociale huurwoningen) over van een andere woningcorporatie? Dan betaalt u straks geen overdrachtsbelasting.","Woningcorporaties kunnen daardoor makkelijker woningen van elkaar overnemen. Bijvoorbeeld om ze te verduurzamen.","Deze vrijstelling geldt alleen voor DAEB-woningen. Dat zijn sociale huurwoningen. Voor andere gebouwen (zoals bedrijfspanden) en grond geldt de vrijstelling niet.","U moet de notaris laten zien welk deel van de overdracht uit DAEB-woningen bestaat. Dat doet u met een taxatierapport."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/no-property-transfer-tax-for-daeb-houses/","mod":"2026-11-13"},{"id":"grootverbruikers-betalen-belasting-over-al-het-drinkwater","t":"Grootverbruikers betalen belasting over al het drinkwater","d":"2027-01-01","dn":"","sec":["industrie"],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/grootverbruikers-betalen-belasting-over-al-het-drinkwater/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["ondernemers die meer dan 50.000 m³ water van drinkwaterkwaliteit per aansluiting per jaar gebruiken"],"vwt":"","wat":["Gebruikt u meer dan 50.000 m³ water van drinkwaterkwaliteit per jaar? Vanaf 1 januari 2027 betaalt u belasting over al het water dat u gebruikt.","In 2026 geldt nog een heffingsplafond van 50.000 m³ per aansluiting per jaar. Dat betekent dat u over het verbruik boven de 50.000 m³ geen belasting betaalt.","Vanaf 1 januari 2027 verdwijnt dit heffingsplafond. U betaalt dan belasting over elke m³ water van drinkwaterkwaliteit die u gebruikt.","Gebruikt u water dat niet van drinkwaterkwaliteit is, bijvoorbeeld oppervlaktewater om te koelen? Dan betaalt u daar vanaf 1 januari 2027 geen belasting op leidingwater over."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/large-consumers-pay-more-tap-water-tax/","mod":"2026-09-15"},{"id":"hoge-tarief-vliegbelasting-stijgt-minder-hard","t":"Hoge tarief vliegbelasting stijgt minder hard","d":"2027-01-01","dn":"","sec":["vervoer"],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/hoge-tarief-vliegbelasting-stijgt-minder-hard/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["exploitanten van een Nederlandse luchthaven","luchtvaartmaatschappijen","ondernemers die (zakelijk) lange afstanden vliegen of van wie het personeel (zakelijk) lange afstanden vliegt"],"vwt":"","wat":["Het hoge tarief van de vliegbelasting voor langeafstandsvluchten gaat minder stijgen dan gepland. Het hoge tarief zou eerst € 74,81 per passagier worden, maar dit is verlaagd naar € 59,43 per passagier.","De vliegbelastingtarieven worden vanaf 2027:","• laag tarief (onder de 2.000 km): € 31,04 per passagier\n• midden tarief (2.000 – 5.500 km): € 49,87 per passagier\n• hoog tarief (meer dan 5.500 km): € 59,43 per passagier","De exploitant van de luchthaven draagt de vliegbelasting af aan de Belastingdienst. De luchtvaartmaatschappij brengt de vliegbelasting in rekening aan de passagier als onderdeel van de prijs van het vliegticket."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/flight-tax-long-distance-flights-increase-less/","mod":"2026-11-13"},{"id":"hogere-bijtelling-voor-oude-zakelijke-auto-youngtimer","t":"Hogere bijtelling voor oude zakelijke auto (youngtimer)","d":"2027-01-01","dn":"","sec":["vervoer"],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/hogere-bijtelling-voor-oude-zakelijke-auto-youngtimer/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["ondernemers en werknemers met een oudere zakelijke auto (youngtimer) die de youngtimerregeling gebruiken"],"vwt":"","wat":["Heeft u een oudere zakelijke auto (16 jaar of ouder) en gebruikt u de youngtimerregeling? De leeftijdsgrens voor de youngtimerregeling gaat veranderen:","• vanaf 1 januari 2027 geldt de regeling voor auto’s vanaf 17 jaar (in 2026 is dat vanaf 16 jaar)\n• vanaf 1 januari 2028 geldt de regeling voor auto’s vanaf 20 jaar","De eerdere verhoging van leeftijd naar 25 jaar gaat niet door. Het kabinet bouwt de regeling geleidelijk af, zodat autobedrijven en ondernemers minder plotseling geraakt worden door stijgende kosten.","Met de youngtimerregeling geldt er voor oudere auto’s (youngtimers) een bijtellingspercentage van 35% over de waarde in het economisch verkeer (dagwaarde). Voor auto’s die geen youngtimer zijn, geldt een bijtellingspercentage van 22% of 25% (afhankelijk van de exacte leeftijd) over de cataloguswaarde. De bijtelling op basis van de dagwaarde is bij een youngtimer over het algemeen lager dan de bijtelling over de cataloguswaarde.","Als uw auto niet meer onder de regeling valt door de nieuwe leeftijdsgrens, dan betaalt u over het algemeen een hogere bijtelling."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/higher-addition-for-private-use-of-old-company-car-youngtimer/","mod":"2026-11-13"},{"id":"maximum-forfait-innovatiebox-gaat-omhoog-naar-eur-100000","t":"Maximum forfait innovatiebox gaat omhoog naar € 100.000","d":"2027-01-01","dn":"","sec":[],"sub":["product-dienst-en-innovatie"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/maximum-forfait-innovatiebox-gaat-omhoog-naar-eur-100000/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["ondernemers die zelf innovaties ontwikkelen en de forfaitaire regeling van de innovatiebox (willen) gebruiken"],"vwt":"","wat":["Heeft uw bedrijf zelf innovaties ontwikkeld? Dan kunt u met de innovatiebox mogelijk belastingvoordeel krijgen over de winst uit deze innovaties. Het kabinet wil het maximum forfait van de innovatiebox verhogen van € 25.000 naar € 100.000. Hierdoor kunt u meer belastingvoordeel krijgen via de innovatiebox.","De innovatiebox is een fiscale regeling binnen de vennootschapsbelasting. U kunt nu in bepaalde situaties de voordelen uit uw innovaties berekenen met een vast percentage (de forfaitaire regeling). U hoeft dan niet precies te berekenen welk voordeel de zelf ontwikkelde innovaties uw bedrijf opleveren. U mag voor dit voordeel uitgaan van 25% van de winst, met op dit moment een maximum van € 25.000."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/maximum-flat-fee-innovation-box-will-rise/","mod":"2026-11-13"},{"id":"meewerkaftrek-wordt-minder-en-verdwijnt-daarna","t":"Meewerkaftrek wordt minder en verdwijnt daarna","d":"2027-01-01","dn":"","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/meewerkaftrek-wordt-minder-en-verdwijnt-daarna/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["ondernemers met een fiscale partner die meewerkt in de onderneming en die de meewerkaftrek (willen) gebruiken"],"vwt":"","wat":["De meewerkaftrek gaat met 75% omlaag vanaf 1 januari 2027. De meewerkaftrek stopt helemaal in 2030.","U kunt de meewerkaftrek (onder voorwaarden) gebruiken als uw fiscale partner meewerkt in uw onderneming. U betaalt dan minder belasting over uw winst. Hoe hoog de meewerkaftrek is, heeft te maken met uw winst en het aantal uren dat uw fiscale partner meewerkt.","De verlaging van de meewerkaftrek ziet er zo uit:","• 525-875 meegewerkte uren: meewerkaftrek is nu 1,25% van de winst, vanaf 2027 is dat 0,313%\n• 875 – 1.225 meegewerkte uren: meewerkaftrek is nu 2% van de winst, vanaf 2027 is dat 0,5%\n• 1.225 – 1.750 meegewerkte uren: meewerkaftrek is nu 3% van de winst, vanaf 2027 is dat 0,75%\n• 1.750 of meer meegewerkte uren: meewerkaftrek is nu 4% van de winst, vanaf 2027 is dat 1%","Let op: Krijgt u een toeslag? Omdat de meewerkaftrek lager wordt en daarna stopt, wordt uw verzamelinkomen hoger. Het kan zijn dat u dan een te hoog voorschot op uw toeslag krijgt. Controleer daarom of het verzamelinkomen nog klopt en geef als het nodig is uw nieuwe geschatte verzamelinkomen door."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/co-working-partner-tax-relief-to-be-reduced-then-end/","mod":"2026-11-13"},{"id":"minimumjeugdloon-vanaf-2027-omhoog","t":"Minimumjeugdloon vanaf 2027 omhoog","d":"2027-01-01","dn":"","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/minimumjeugdloon-vanaf-2027-omhoog/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["ondernemers die werknemers tussen de 16 en 20 jaar in dienst hebben"],"vwt":"","wat":["Bent u werkgever? En heeft u werknemers tussen de 16 en 20 jaar in dienst? Dan gaat voor uw werknemers het minimumjeugdloon op 1 januari 2027 omhoog. Het minimumjeugdloon komt zo dichter bij het standaard minimumloon. Bekijk hier de minimumjeugdloonpercentages na 1 januari 2027."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-279.html","text":"Besluit bijzondere verhoging wettelijk minimumjeugdloon (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/wijzigingvanhetbesluitminimumjeugdlooninverbandmetdeverhogingvanhetminimumjeugdloon/b1","text":"Consultatie Wijziging Besluit minimumjeugdloon voor verhoging minimumjeugdloon (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/youth-minimum-wage-to-go-up-from-2027/","mod":"2026-09-25"},{"id":"uitzendbureaus-moeten-gecertificeerd-zijn","t":"Nieuwe regels voor bedrijven die personeel in- of uitlenen (Wtta)","d":"2027-01-01","dn":"nog niet bekend","sec":["zakelijke-dienstverlening"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/uitzendbureaus-moeten-gecertificeerd-zijn/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is officieel aangenomen en de ingangsdatum is bekend. U kunt zich voorbereiden.","ph":"vast","vw":["Uitleners: ondernemingen die werknemers ter beschikking stellen aan andere organisaties, zoals uitzendbureaus, detacheerders en andere bedrijven die personeel uitlenen","Inleners: ondernemingen die werknemers inhuren van een uitlener om werkzaamheden binnen hun organisatie uit te voeren."],"vwt":"","wat":["Heeft u een uitzendbureau of een ander bedrijf dat arbeidskrachten ter beschikking stelt (uitlener)? Of huurt u uitzendkrachten in? Uitleners van arbeid, zoals uitzendbureaus en detacheerders, mogen alleen nog werknemers aan het werk zetten als zij door de Nederlandse Autoriteit Uitleenmarkt (NAU) zijn toegelaten tot de markt. Zonder toelating (vergunning) mag u geen arbeidskrachten uitlenen. Ondernemingen die arbeidskrachten inhuren (inleners) mogen geen zaken meer doen met niet-toegelaten uitleners.","Het toelatingsstelsel beschermt werknemers en met name arbeidsmigranten tegen slechte werkomstandigheden, weert malafide partijen van de markt, pakt misstanden in de uitzendsector aan en zorgt voor een eerlijke concurrentie tussen uitleners van personeel.","Om toelating (vergunning) te krijgen moet u als uitlener:","• het juiste loon betalen aan uw arbeidskrachten\n• de juiste belastingaangifte doen\n• een verklaring omtrent het gedrag (VOG) hebben\n• een waarborgsom van € 100.000 betalen, tenzij u vrijstelling krijgt\n• goedgekeurde huisvesting aanbieden (voor buitenlandse arbeidskrachten)","Vrijstelling van de waarborgsom","Leent u al minstens 4 jaar personeel uit? Dan kunt u onder voorwaarden vrijstelling krijgen van de waarborgsom. KVK heeft de registratiegegevens hiervoor al doorgegeven aan de NAU. U moet zelf nog andere bewijsstukken aanleveren.","Lees meer over de voorwaarden op Toelating uitleenmarkt.","Hoe kunt u zich voorbereiden als uitlener?","Leent u personeel uit? Dan kunt u zich met deze stappen voorbereiden:","• Controleer op Toelating uitleenmarkt of u toelating moet aanvragen.\n• Vraag eHerkenning niveau 3 en een Berichtenbox voor bedrijven aan. Registreer uw Berichtenbox ook bij KVK.\n• Meld u tussen 1 november en 31 december 2026 aan voor de overgangsregeling als u hiervan gebruik wilt maken.\n• Bereid uw bedrijf voor op de toelating. Controleer of u aan de eisen voldoet.\n• Vraag tussen 1 mei en 30 juni 2027 toelating of ontheffing aan bij de NAU.","Meldt u zich op tijd aan voor de overgangsregeling en voldoet u aan de voorwaarden? Dan mag u personeel blijven uitlenen terwijl de NAU uw aanvraag beoordeelt.","Lees meer over de overgangsregeling.","Wat moet u doen als inlener?","Huurt u personeel in via een uitzendbureau of een ander bedrijf? Controleer dan vanaf 1 januari 2028 in het openbare register van de NAU of de uitlener personeel mag uitlenen. De huidige Waadi-check bij KVK vervalt op die datum.","Lees meer over de regels voor inleners op Toelating uitleenmarkt.","De Arbeidsinspectie gaat controleren","De Arbeidsinspectie gaat regelmatig controleren of uitleners zich aan de regels houden. Als u de toelating verliest, mag u niet meer arbeidskrachten uitlenen. Als u werkt zonder toelating, kunt u een boete krijgen.","Ook bedrijven die arbeidskrachten inlenen van uitzendbureaus zonder toelating kunnen een boete krijgen."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/wijzigingsregelingwaadinormenkader/b1","text":"Consultatie Wijzigingsregeling Waadi (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-159.html","text":"Besluit inwerkingtreding Wet toelating terbeschikkingstelling van arbeidskrachten voor invoering toelatingsplicht (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/wijzigingsbesluitbaadi/b1","text":"Consultatie Wijzigingsbesluit Baadi (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-41.html","text":"Besluit wijziging Besluit allocatie arbeidskrachten door intermediairs voor invoering toelatingsplicht ter beschikking stellen arbeidskrachten (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/certificate-for-temporary-employment-agencies/","mod":"2026-10-27"},{"id":"nieuwe-veiligehavenregels-voor-wereldwijde-minimumbelasting","t":"Nieuwe veiligehavenregels voor wereldwijde minimumbelasting","d":"2027-01-01","dn":"","sec":[],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/nieuwe-veiligehavenregels-voor-wereldwijde-minimumbelasting/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["een groep entiteiten (bedrijven) met een omzet van € 750 miljoen of meer"],"vwt":"","wat":["Is uw bedrijf onderdeel van een groep entiteiten met een omzet van € 750 miljoen of meer? Dan moet u voldoen aan de Wet minimumbelasting 2024 (Pijler 2). Dit is een wereldwijde minimumbelasting van 15% die grote groepen entiteiten moeten betalen. Is de belastingdruk in het land waar het bedrijf gevestigd is lager? Dan betaalt deze groep een bijheffing.","Met het voorstel Wet veiligehavenregels Wet minimumbelasting 2024 worden er vier nieuwe veiligehavenregels toegevoegd aan de Wet minimumbelasting 2024. Het kabinet verwerkt met dit wetsvoorstel internationale afspraken uit een OESO-akkoord in de Nederlandse belastingwet.","Vereenvoudigde effectieve belastingtarief-veiligehavenregel","Het doel van deze veiligehavenregel is om administratieve lastenvermindering te bereiken. Een groep entiteiten kan ervoor kiezen om in een staat bij het toepassen van de minimumbelasting een vereenvoudigde berekening te gebruiken, in plaats van een gedetailleerde berekening.","Kwalificerend equivalent minimumbelastingstelsel-veiligehavenregel","Als het land waarin de uiteindelijkemoederentiteit (het hoofd van een groep entiteiten) is gevestigd al een vorm van een minimumbelasting kent, wordt de Nederlandse bijheffing voor bepaalde winsten van deze groep op nul gezet.","Uiteindelijkemoederentiteit-veiligehavenregel","Als een dochterbedrijf en de uiteindelijkemoederentiteit allebei gevestigd zijn in een land dat een kwalificerende belastingstelsel kent, wordt de Nederlandse bijheffing voor bepaalde winsten van deze groep op nul gezet.","Kwalificerende fiscale stimuleringsregeling-veiligehavenregel","Deze veiligehavenregel regelt de gunstige behandeling van bepaalde fiscale stimuleringsregelingen voor bedrijven met reële economische activiteit.","Het wetsvoorstel verlengt ook de tijdelijke kwalificerend landenrapport veiligehavenregel (CbCR-veiligehavenregel) met een jaar en heeft een technische wijziging voor groepen entiteiten met een verslagjaar van 52 of 53 weken."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/new-safe-harbour-rules-for-global-minimum-tax/","mod":"2026-11-13"},{"id":"overgebleven-recht-op-loonkostenvoordeel-gaat-over-op-nieuwe-werkgever","t":"Overgebleven recht op loonkostenvoordeel gaat over op nieuwe werkgever","d":"2027-01-01","dn":"","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/overgebleven-recht-op-loonkostenvoordeel-gaat-over-op-nieuwe-werkgever/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["ondernemers die werknemers in dienst nemen die een doelgroepverklaring hebben","ondernemers die een onderneming overnemen waarin werknemers een doelgroepverklaring hadden"],"vwt":"","wat":["Bent u werkgever en neemt u een werknemer in dienst die eerder recht had op loonkostenvoordeel (LKV) bij een andere werkgever? Dan kan uw werknemer een nieuwe doelgroepverklaring aanvragen. Uw werknemer moet u dan een kopie van de doelgroepverklaring geven. Het overgebleven recht op LKV gaat dan over op u als nieuwe werkgever."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-118.html","text":"Besluit inwerkingtreding Wet wijziging Wet tegemoetkomingen loondomein teneinde voor een nieuwe werkgever een recht te regelen op een loonkostenvoordeel voor de resterende duur daarvan (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-27.html","text":"Wet wijziging Wet tegemoetkomingen loondomein teneinde voor nieuwe werkgever recht te regelen op loonkostenvoordeel voor de resterende duur daarvan (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/labour-costs-compensation-entitlement-transfers-to-new-employer/","mod":"2026-09-15"},{"id":"personeelskorting-niet-meer-standaard-belastingvrij","t":"Personeelskorting niet meer standaard belastingvrij","d":"2027-01-01","dn":"","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/personeelskorting-niet-meer-standaard-belastingvrij/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["ondernemers die hun personeel korting geven op producten uit hun eigen bedrijf"],"vwt":"","wat":["Bent u werkgever en geeft u uw personeel korting op producten uit uw eigen bedrijf? Bijvoorbeeld personeelskorting op boodschappen, kleding, elektronica, gezinsabonnementen, vliegtickets, hypotheekadvies of verzekeringspremies. Vanaf 1 januari 2027 kan dat niet meer standaard belastingvrij.","Nu kunt u uw personeel 20% korting geven tot maximaal € 500 per jaar zonder dat u hierover loonbelasting moet betalen.","Vanaf 1 januari 2027 kunt u uw personeel wel nog belastingvrij korting geven via de vrije ruimte van de werkkostenregeling (WKR). Is de vrije ruimte op? Dan moet u over dat extra deel wel belasting (de eindheffing) betalen. De eindheffing is 80%."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/staff-discounts-no-longer-automatically-tax-free/","mod":"2026-11-13"},{"id":"rechtspersonen-mogen-digitaal-vergaderen","t":"Rechtspersonen mogen digitaal vergaderen","d":"2027-01-01","dn":"nog niet bekend","sec":[],"sub":["bedrijfsvoering"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/rechtspersonen-mogen-digitaal-vergaderen/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["Besturen, leden, aandeelhouders van nv's, bv's, verenigingen, VvE's, coöperaties en onderlinge waarborgmaatschappijen."],"vwt":"","wat":["Bent u bestuurslid of aandeelhouder van een nv of bv? Het wordt voor rechtspersonen zoals naamloze vennootschappen (nv’s), besloten vennootschappen (bv’s), verenigingen, coöperaties en VvE’s mogelijk om een volledig digitale algemene vergadering te houden. Dit komt naast de al de bestaande mogelijkheid van een gedeeltelijk digitale (hybride) algemene vergadering.","Rechtspersonen kunnen zelf kiezen of zij digitaal willen vergaderen en welk elektronisch communicatiemiddel zij daarvoor willen gebruiken.","Voorwaarden","De voorwaarden voor een volledig digitale algemene vergadering zijn:","• Een digitale vergadering moet zoveel mogelijk een afspiegeling vormen van een fysieke vergadering.\n• Deelnemers moeten ook langs digitale weg volwaardig kunnen meedoen.\n• Leden en aandeelhouders moeten met beeld én geluid kunnen meedoen aan de vergadering en het woord kunnen voeren.\n• De algemene leden- of aandeelhoudersvergadering moet vooraf akkoord gaan met de optie om digitaal te vergaderen.","Nu staat nog in de wet dat algemene vergaderingen (gedeeltelijk) fysiek moeten plaatsvinden."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-259.html","text":"Besluit inwerkingtreding Wet digitale algemene vergadering privaatrechtelijke rechtspersonen (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-161-n1.html","text":"Wet digitale algemene vergadering privaatrechtelijke rechtspersonen (Verbetering) (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-161.html","text":"Wet digitale algemene vergadering privaatrechtelijke rechtspersonen (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/digiava/b1","text":"Consultatie Wet digitale algemene vergadering privaatrechtelijke rechtspersonen. (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/legal-entities-may-hold-digital-meetings/","mod":"2026-09-14"},{"id":"afschaffen-salderingsregeling-vanaf-2027","t":"Salderingsregeling zonnepanelen stopt vanaf 2027","d":"2027-01-01","dn":"","sec":[],"sub":["bedrijfsvoering","klimaat-energie-en-natuur"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/afschaffen-salderingsregeling-vanaf-2027/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["mkb-bedrijven met een elektriciteitsaansluiting van maximaal 3x80 ampère (kleinverbruikers) en zonnepanelen of kleine windmolens","installateurs van zonnepanelen","fabrikanten van zonnepanelen","energieleveranciers"],"vwt":"","wat":["Heeft u zonnepanelen voor uw bedrijf en levert u stroom terug aan het net? Of heeft u kleine windmolens voor uw bedrijf? De salderingsregeling stopt per 1 januari 2027.","Als kleinverbruiker mag u nu de stroom die u elk jaar teruglevert, verrekenen met de stroom die u gebruikt. Dat heet salderen. Levert u meer stroom terug dan u gebruikt? Dan ontvangt u over het verschil een vergoeding van uw energieleverancier. Als de salderingsregeling stopt, kan dit verrekenen niet meer.","In plaats hiervan komt er een nieuwe regeling. U ontvangt straks een redelijke vergoeding van uw energieleverancier voor alle stroom die u teruglevert.","Met deze maatregel stimuleert het kabinet dat u uw zelfopgewekte stroom zoveel mogelijk zelf verbruikt. Zo wordt het elektriciteitsnet minder belast."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-17.html","text":"Wet beëindiging salderingsregeling voor elektriciteit (Rijksoverheid)"}],"en":"https://business.gov.nl/amendments/netting-scheme-solar-panels-ends/","mod":"2026-08-28"},{"id":"stakingsaftrek-wordt-minder-en-verdwijnt-daarna","t":"Stakingsaftrek wordt minder en verdwijnt daarna","d":"2027-01-01","dn":"","sec":[],"sub":["bedrijf-stoppen-of-overdragen","belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/stakingsaftrek-wordt-minder-en-verdwijnt-daarna/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["ondernemers die stoppen met hun onderneming en de stakingsaftrek willen gebruiken"],"vwt":"","wat":["De stakingsaftrek gaat omlaag van € 3.630 naar € 908 vanaf 1 januari 2027. De stakingsaftrek stopt helemaal in 2030.","Als u stopt met uw onderneming (bijvoorbeeld door verkoop), dan kunt u daardoor stakingswinst hebben. U moet belasting betalen over deze stakingswinst. U kunt dan de stakingsaftrek gebruiken. Zo betaalt u minder belasting over de stakingswinst."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/discontinuation-relief-reduced-and-then-end/","mod":"2026-11-13"},{"id":"startersaftrek-gaat-omlaag-en-verdwijnt","t":"Startersaftrek gaat omlaag en verdwijnt","d":"2027-01-01","dn":"","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/startersaftrek-gaat-omlaag-en-verdwijnt/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["startende ondernemers die de startersaftrek gebruiken of willen gebruiken"],"vwt":"","wat":["Bent u startende ondernemer? En vult u de startersaftrek in bij uw aangifte inkomstenbelasting? Vanaf 1 januari 2027 daalt de startersaftrek van € 2.123 naar € 10. Vanaf 1 januari 2028 bestaat de startersaftrek niet meer. Voor uw aangifte inkomstenbelasting hoeft u niets extra’s te doen.","Er is geen speciale regeling voor ondernemers die al een onderneming zijn gestart. Ook voor hen daalt de startersaftrek in 2027 en verdwijnt die in 2028."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/tax-relief-for-new-companies-reduced-and-abolished/","mod":"2026-11-13"},{"id":"uitzendbureaus-moeten-arbeidsmigranten-helpen-bij-brp-registratie","t":"Uitzendbureaus moeten arbeidsmigranten helpen bij BRP-registratie","d":"2027-01-01","dn":"nog niet bekend","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/uitzendbureaus-moeten-arbeidsmigranten-helpen-bij-brp-registratie/","sh":"De wet is aangenomen, de regels worden nog uitgewerkt","se":"De wet is aangenomen door de Tweede en Eerste Kamer. De regels worden nog verder uitgewerkt. Daarom kunnen de regels en de ingangsdatum nog veranderen, maar het is goed om dit alvast te weten.","ph":"vast","vw":["uitzendbureaus die arbeidsmigranten uitzenden","werkgevers die arbeidsmigranten inzetten"],"vwt":"","wat":["Heeft u een uitzendbureau? Dan krijgt u straks extra taken. U moet arbeidsmigranten helpen om zich goed te registreren in de Basisregistratie Personen (BRP). Nu moeten zij dat nog helemaal zelf doen, maar dat gaat vaak mis. Straks moet u arbeidsmigranten bijvoorbeeld juiste informatie geven, in hun eigen taal. Ook controleert u of de inschrijving gelukt is.","Dit geldt als arbeidsmigranten langer dan 4 maanden in Nederland blijven en zich als ingezetene moeten inschrijven bij de gemeente. Of als ze korter blijven en zich als niet-ingezetene melden. Zo hebben gemeenten en andere overheidsorganisaties beter zicht op waar arbeidsmigranten verblijven. Als dit onduidelijk is, kan de arbeidsmigrant tegen problemen aanlopen, zoals onverzekerd zijn bij het verliezen van een baan.","Arbeidsmigranten blijven wel zelf verantwoordelijk voor een juiste inschrijving in de BRP, maar uitzendbureaus krijgen dus de plicht ze te ondersteunen."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-385.html","text":"Wet toelating terbeschikkingstelling van arbeidskrachten (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/zorgplichtuitlenersbaadi/b1","text":"Consultatie Zorgplicht uitleners bij registratie in lagere regelgeving (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/employment-agencies-must-help-migrant-workers-with-brp-registration/","mod":"2026-09-30"},{"id":"vapes-en-sigaren-krijgen-neutrale-verpakking","t":"Vapes en sigaren krijgen neutrale verpakking","d":"2027-01-01","dn":"nog niet bekend","sec":["detailhandel-groothandel-en-ambachten"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/vapes-en-sigaren-krijgen-neutrale-verpakking/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["fabrikanten, importeurs en verkopers van sigaren en e-sigaretten"],"vwt":"","wat":["Verkoopt u vapes en sigaren? Binnenkort moeten deze producten in neutrale verpakking verkocht worden. Sinds 2020 geldt al voor sigaretten en shagtabak dat die een neutrale verpakking moeten hebben.","Nu zien verpakkingen van vapes en sigaren er vaak aantrekkelijk uit. Ze geven het bijvoorbeeld de uitstraling van een luxeproduct. De eis dat vapes en sigaren in een neutrale verpakking moeten zitten, moet de aantrekkingskracht van de producten beperken."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stcrt-2026-25166.html","text":"Regeling Minister van VWS wijziging Tabaks- en rookwarenregeling voor invoeren standaardverpakkingen sigaren en elektronische dampwaar"},{"href":"https://www.internetconsultatie.nl/standaardverpakkingensigarenesigaretten/b1","text":"Consultatie wijziging Tabaks- en rookwarenregeling voor invoeren van standaardverpakkingen voor sigaren en elektronische dampwaar (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-8.html","text":"Besluit wijziging Tabaks- en rookwarenbesluit voor invoering standaardverpakkingen voor sigaren en elektronisch dampwaar (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/standaardverpakkingen","text":"Internetconsultatie. Verhittingsapparaten en standaardverpakkingen e-sigaretten en sigaren (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/plain-packaging-vapes-cigars/","mod":"2026-09-23"},{"id":"vergoeding-30-procent-regeling-expats-wordt-27-procent","t":"Vergoeding 30%-regeling expats wordt 27%","d":"2027-01-01","dn":"","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/vergoeding-30-procent-regeling-expats-wordt-27-procent/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["ondernemers met hoogopgeleide buitenlandse werknemers","ondernemers die werknemers met een specifieke vaardigheid uitzenden naar het buitenland"],"vwt":"","wat":["Bent u werkgever? En huurt u hoogopgeleide buitenlandse werknemers in om voor u in Nederland te werken? Of zendt u werknemers met een specifieke vaardigheid uit naar het buitenland? Het belastingvoordeel van de 30%-regeling (expatregeling) gaat omlaag. Dat wordt 27% vanaf 2027. Ook moet het loon van de werknemer (inkomensnorm) hoger zijn om de expatregeling te kunnen gebruiken.","Met de 30%-regeling kunt u uw buitenlandse of uitgezonden werknemer belastingvoordeel geven om te helpen bij de verhuiskosten of de hogere levenskosten. U kunt met deze regeling een percentage van het salaris belastingvrij betalen. U en uw werknemer moeten aan de voorwaarden van de 30%-regeling voldoen.","Wat er precies verandert, hangt af van de datum waarop de regeling voor uw werknemer ingaat:","De 30%-regeling is ingegaan voor 1 januari 2024:","U mag 5 jaar lang maximaal 30% van het salaris belastingvrij blijven betalen. De inkomensnorm blijft € 46.107 (dit bedrag wordt jaarlijks geïndexeerd).","De 30%-regeling (expatregeling) is ingegaan na 1 januari 2024:","• U mag in 2024, 2025 en 2026 uw werknemers tot maximaal 30% van hun salaris belastingvrij betalen. De inkomensnorm blijft: € 46.107 (dit bedrag wordt jaarlijks geïndexeerd).\n• Vanaf 2027 mag u uw werknemers tot maximaal 27% belastingvrij vergoeden. De inkomensnorm wordt vanaf 2027 hoger: € 50.436 in plaats van € 46.107 (dit bedrag wordt jaarlijks geïndexeerd).","Let op: Voor hoogopgeleide buitenlandse werknemers jonger dan 30 jaar met een mastergraad in dienst geldt een andere inkomensnorm voor de expatregeling. Ook die inkomensnorm wordt per 1 januari 2027 verhoogd, van € 35.048 naar € 38.388 (dit bedrag wordt jaarlijks geïndexeerd)."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2024-434","text":"Belastingplan 2025 (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/30-percent-ruling-compensation-down-to-27-percent/","mod":"2026-10-01"},{"id":"verlaging-algemeen-woningtarief-overdrachtsbelasting","t":"Verlaging algemeen woningtarief overdrachtsbelasting van 8% naar 7%","d":"2027-01-01","dn":"","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/verlaging-algemeen-woningtarief-overdrachtsbelasting/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["ondernemers die (meer) woningen willen verhuren","investeerders van huurwoningen","investeerders van nieuwbouwwoningen"],"vwt":"","wat":["Wilt u woningen kopen om te verhuren of investeert u al in huurwoningen? Het algemene woningtarief in de overdrachtsbelasting wordt op 1 januari 2027 verlaagd van 8% naar 7%.","Dit tarief is voor woningen dit u niet als hoofdverblijf gebruikt. Bijvoorbeeld huurwoningen die u koopt als investeerder. Het tarief voor andere onroerende zaken, zoals bedrijfspanden, blijft gelijk."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/reduction-in-property-transfer-tax-from-8-to-7/","mod":"2026-11-13"},{"id":"werkgevers-moeten-loonverschillen-tussen-mannen-en-vrouwen-tegengaan","t":"Werkgevers moeten loonverschillen tussen mannen en vrouwen tegengaan","d":"2027-01-01","dn":"nog niet bekend","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/werkgevers-moeten-loonverschillen-tussen-mannen-en-vrouwen-tegengaan/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ondernemers met personeel"],"vwt":"","wat":["Bent u werkgever? Dan moet u ervoor zorgen dat mannen en vrouwen binnen uw organisatie gelijk worden beloond. In Nederland komt het nog steeds voor dat vrouwen met vergelijkbare achtergrond en ervaring en in vergelijkbare functies minder verdienen dan mannen. De overheid werkt aan een nieuwe wet om deze loonverschillen tussen mannen en vrouwen tegen te gaan. Dit betekent voor u als werkgever het volgende:","• U moet open zijn over salarissen en loonverschillen in uw bedrijf.\n• U mag niet meer vragen naar het vorige salaris van een sollicitant.\n• U moet eerlijke en duidelijke regels voor salarissen maken, zodat de beloning eerlijk is en gecontroleerd kan worden.\n• Heeft u meer dan 100 werknemers? Dan moet u op vaste, terugkerende momenten laten zien hoe groot de loonverschillen zijn."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/regelingimplementatierichtlijnloontransparantiemannenenvrouwen/b1","text":"Consultatie Regeling implementatie Richtlijn Loontransparantie mannen en vrouwen (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/besluitimplementatierichtlijnloontransparantie/b1","text":"Consultatie Besluit implementatie Richtlijn loontransparantie mannen en vrouwen"},{"href":"https://www.internetconsultatie.nl/wetimplementatierichtlijnloontransparantiemannenenvrouwen/b1","text":"Consultatie Wet implementatie Richtlijn loontransparantie mannen en vrouwen (Overheid.nl)"},{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=CELEX:32023L0970","text":"Richtlijn (EU) 2023/970 loontransparantie mannen en vrouwen (EU)"}],"en":"https://business.gov.nl/amendments/employers-must-prevent-pay-gap-between-men-women/","mod":"2026-10-15"},{"id":"zelfstandigenaftrek-verder-omlaag-0","t":"Zelfstandigenaftrek verder omlaag","d":"2027-01-01","dn":"","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/zelfstandigenaftrek-verder-omlaag-0/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen en deels ingegaan. U kunt zich voorbereiden op de laatste stap.","ph":"vast","vw":["zelfstandig ondernemers die recht hebben op zelfstandigenaftrek"],"vwt":"","wat":["Heeft u recht op zelfstandigenaftrek? Het bedrag dat u mag aftrekken van uw winst wordt lager. In 2025 was de zelfstandigenaftrek nog € 2.470 en in 2026 is dat: € 1.200. In 2027 wordt de zelfstandigenaftrek verder afgebouwd naar € 900.","U betaalt meer belasting als de zelfstandigenaftrek daalt. De afbouw van de zelfstandigenaftrek maakt de verschillen in de belastingen tussen zelfstandigen en werknemers kleiner.","De voorwaarden voor de zelfstandigenaftrek blijven hetzelfde:","• u bent ondernemer voor de inkomstenbelasting, en\n• u werkt per jaar minimaal 1.225 uren aan uw onderneming","Deze wetswijziging werd al eerder bekendgemaakt. Dit is de aanpassing voor 2027."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-444.html","text":"Belastingplan 2026 (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/private-business-ownership-allowance-reduced-further/","mod":"2026-09-17"},{"id":"digitaal-productpaspoort-dpp-voor-batterijen-en-accus-verplicht","t":"Digitaal productpaspoort (DPP) voor batterijen en accu's verplicht","d":"2027-02-18","dn":"","sec":[],"sub":["product-dienst-en-innovatie"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/digitaal-productpaspoort-dpp-voor-batterijen-en-accus-verplicht/","sh":"Deze Europese wet is goedgekeurd: bereid uw bedrijf voor","se":"Dit is een Europese Verordening. Deze wet is goedgekeurd in Europa. U moet uw bedrijf aanpassen.","ph":"vast","vw":["batterijen voor lichte vervoermiddelen, zoals elektrische fietsen en elektrische steps (LMT-batterijen)","industriële batterijen met een capaciteit van meer dan 2 kWh","batterijen voor elektrische voertuigen (EV-batterijen)"],"vwt":"Ondernemers die de volgende batterijen voor het eerst op de EU-markt aanbieden of voor eigen gebruik naar de Europese Unie halen:","wat":["Biedt u een van deze batterijen voor het eerst aan op de EU-markt of haalt u deze voor eigen gebruik naar de EU? Dan moet de batterij een batterijpaspoort hebben. Dit is een digitaal productpaspoort (DPP) met informatie over de batterij. U koppelt het batterijpaspoort met een QR-code aan de batterij.","In het batterijpaspoort staat informatie over het batterijmodel en over de batterij zelf. Bijvoorbeeld informatie over:","• de batterij en de fabrikant\n• het type en model van de batterij\n• de samenstelling van de batterij\n• de prestaties en levensduur\n• reparatie, hergebruik en recycling","Welke informatie verplicht is, hangt onder andere af van het soort batterij. Niet alle informatie in het batterijpaspoort is voor iedereen zichtbaar. Sommige gegevens zijn openbaar. Andere gegevens zijn alleen te zien voor bijvoorbeeld toezichthouders, reparateurs en recyclers.","De ondernemer die de complete batterij voor het eerst op de EU-markt aanbiedt of voor eigen gebruik naar de EU haalt, is verantwoordelijk voor het batterijpaspoort.","Batterijpaspoort registreren","U moet het batterijpaspoort ook registreren in het Europese DPP-register. Hiervoor maakt u een account aan en laat u uw identiteit controleren. Daarna registreert u het batterijpaspoort met een uniek identificatienummer. Het register bevat niet alle informatie uit het batterijpaspoort."],"doen":[],"law":[{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=CELEX%3A32023R1542","text":"Batterijenverordening (EU) 2023/1542 (EUR-Lex)"}],"en":"https://business.gov.nl/amendments/mandatory-digital-product-passport-dpp-for-batteries/","mod":"2026-10-20"},{"id":"apparaten-moeten-voldoen-aan-strengere-eisen-standby-verbruik","t":"Apparaten moeten voldoen aan strengere eisen standby-verbruik","d":"2027-05-09","dn":"","sec":[],"sub":["product-dienst-en-innovatie"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/apparaten-moeten-voldoen-aan-strengere-eisen-standby-verbruik/","sh":"Deze Europese wet is goedgekeurd: bereid uw bedrijf voor","se":"Dit is een Europese Verordening. Deze wet is goedgekeurd in Europa. U moet uw bedrijf aanpassen.","ph":"vast","vw":["fabrikanten van elektronica","importeurs van apparaten uit landen buiten de EU"],"vwt":"","wat":["Produceert of levert u elektrische of elektronische apparaten op de EU-markt? Sinds 9 mei 2025 gelden nieuwe Europese eisen voor het energieverbruik van apparaten in standby-stand, uitstand en networked standby. Vanaf 9 mei 2027 worden sommige grenswaarden verder aangescherpt. Daardoor mogen deze apparaten in bepaalde standen minder energie verbruiken. De regels staan in de Europese verordening (EU) 2023/826.","Dit zijn de nieuwe grenswaarden vanaf 9 mei 2027:","• Apparaten mogen in standby-stand maximaal 0,5 watt verbruiken.\n• In uitstand (off mode) geldt een maximum van 0,3 watt.\n• Toont een apparaat informatie in standby? Dan is maximaal 0,8 watt toegestaan.\n• Apparaten in networked standby mogen tussen de 2 en 7 watt verbruiken, afhankelijk van het type product.","Networked standby betekent dat een apparaat uit lijkt te staan, maar nog verbonden is met een netwerk, zoals wifi of internet. Het apparaat verbruikt dan nog stroom, bijvoorbeeld om updates te ontvangen of op afstand te starten.","Wat betekent dit voor u?","• U moet uw producten aanpassen of opnieuw ontwerpen zodat ze voldoen aan de nieuwe energie-eisen.\n• U mag alleen producten op de EU-markt brengen die binnen de verbruiksgrenzen blijven."],"doen":[],"law":[{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=CELEX:32023R0826","text":"Verordening (EU) 2023/826 (Ecodesign-verordening) (EU)"}],"en":"https://business.gov.nl/amendments/stricter-requirements-standby-energy-consumption-applicances/","mod":"2026-09-30"},{"id":"horeca-mag-kreeften-en-krabben-niet-meer-levend-koken","t":"Horeca mag kreeften en krabben niet meer levend koken","d":"2027-07-01","dn":"","sec":["horeca-recreatie-en-catering"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/horeca-mag-kreeften-en-krabben-niet-meer-levend-koken/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ondernemers die Europese kreeften, Canadese kreeften of Noordzeekrab bereiden"],"vwt":"","wat":["Bereidt u Europese kreeften, Canadese kreeften of Noordzeekrab? Deze mag u straks niet meer levend koken. De overheid wil het levend koken van kreeften en krabben verbieden, omdat deze dieren daarbij pijn en stress kunnen ervaren.","De belangrijkste veranderingen zijn:","• U mag Europese kreeften, Canadese kreeften en Noordzeekrab straks niet meer levend koken. Het verbod geldt eerst alleen voor deze soorten.\n• De overheid kan later ook andere soorten onder het verbod laten vallen.\n• De overheid kan later regels vaststellen over hoe deze dieren vóór het koken buiten bewustzijn moeten worden gebracht."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/levendkokenkreeftkrab/b1","text":"Consultatie Invoering verbod op het levend koken van kreeften en krabben (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/cooking-live-lobsters-and-crabs-banned-in-hospitality/","mod":"2026-09-08"},{"id":"wijziging-regels-voor-ondernemende-overheden","t":"Strengere spelregels voor ondernemende overheden","d":"2027-07-01","dn":"nog niet bekend","sec":[],"sub":["product-dienst-en-innovatie"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/wijziging-regels-voor-ondernemende-overheden/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ondernemers die diensten of producten aanbieden die mogelijk ook door overheden worden geleverd"],"vwt":"","wat":["Overheden die economische activiteiten uitvoeren die ook door bedrijven kunnen worden aangeboden krijgen te maken met strengere spelregels. Ondernemende overheden moeten:","• hun marktactiviteiten beter motiveren\n• inspraak voor ondernemers organiseren\n• besluiten elke vijf jaar evalueren"],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-152.html","text":"Besluit van 16 mei 2025 tot wijziging van het Besluit van 31 januari 2017, houdende verlenging van de werkingsduur van de gedragsregels voor de overheid in de Mededingingswet"},{"href":"https://www.internetconsultatie.nl/wijzigingmarktenoverheid","text":"Consultatie. Wetsvoorstel wijziging markt en overheid (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/stricter-rules-entrepreneurial-governments/","mod":"2026-10-14"},{"id":"uitzendbureaus-moeten-ongevallen-melden-aan-arbeidsinspectie","t":"Uitzendbureaus moeten ongevallen melden aan Arbeidsinspectie","d":"2027-07-01","dn":"","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/uitzendbureaus-moeten-ongevallen-melden-aan-arbeidsinspectie/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["bedrijven die uitzendkrachten inzetten (inleners)","uitzendbureaus en payrollers (uitleners)"],"vwt":"","wat":["Werkt u met uitzendkrachten of bent u uitzendondernemer? Dan gaan er nieuwe regels gelden voor het melden van arbeidsongevallen. Ook krijgt u extra verantwoordelijkheden voor de veiligheid van uw werknemers.","De Arbeidsomstandighedenwet wordt aangepast. Door deze wijziging moeten het bedrijf waar de werknemer werkt (de inlener) en het uitzendbureau (de uitlener) samen zorgen voor de veiligheid van uitgeleende werknemers.","Wat betekent dit voor u?","• Bent u inlener? Dan moet u ernstige en dodelijke arbeidsongevallen met uitgeleende werknemers niet alleen melden bij de Nederlandse Arbeidsinspectie, maar ook direct aan het uitzendbureau.\n• Bent u uitlener? U moet deze ongelukken ook melden aan de Nederlandse Arbeidsinspectie.\n• Na een ongeluk moet u als uitlener controleren of het bedrijf waar het ongeluk is gebeurd genoeg veiligheidsmaatregelen heeft genomen. Dit heet de vergewisplicht."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/arbeidsomstandighedenbesluitmeldenvergewisplichtuitleners/b1","text":"Consultatie Arbeidsomstandighedenbesluit meld- en vergewisplicht uitleners"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-69.html","text":"Wet invoering meld- en vergewisplicht arbeidsongevallen voor uitleners (Overheid.nl)"},{"href":"https://internetconsultatie.nl/wetinvoeringmeldplichtarbeidsongevallenenvergewisplichtenuitleners/b1","text":"Consultatie Wet invoering meldplicht arbeidsongevallen en vergewisplichten uitleners (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/employment-agencies-must-report-accidents-to-the-labour-inspectorate/","mod":"2026-09-08"},{"id":"veilige-digitale-producten-verplicht-cra","t":"Veilige digitale producten verplicht (Cyber Resilience Act)","d":"2027-12-11","dn":"","sec":[],"sub":["product-dienst-en-innovatie"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/veilige-digitale-producten-verplicht-cra/","sh":"Deze Europese wet is goedgekeurd: bereid uw bedrijf voor","se":"Dit is een Europese Verordening. Deze wet is goedgekeurd in Europa. U moet uw bedrijf aanpassen.","ph":"vast","vw":["fabrikanten van producten met digitale elementen","importeurs die deze producten in de EU op de markt brengen","distributeurs die deze producten verkopen","gemachtigde vertegenwoordigers van fabrikanten"],"vwt":"","wat":["De Cyber Resilience Act stelt eisen aan de digitale veiligheid van producten met digitale elementen. Het gaat om hardware en software die direct of indirect verbonden kunnen worden met een apparaat of netwerk.","Meldplicht voor fabrikanten geldt al","Sinds 11 september 2026 moeten fabrikanten actief misbruikte kwetsbaarheden en ernstige beveiligingsincidenten melden. Dit doen zij via het CRA-meldformulier van het NCSC.","Deze meldplicht geldt ook voor producten met digitale elementen die al vóór 11 december 2027 op de Europese markt zijn gebracht.","Meer regels vanaf 11 december 2027","Vanaf 11 december 2027 gelden de meeste andere regels van de CRA. Fabrikanten moeten dan onder andere:","• digitale producten veilig ontwerpen en ontwikkelen\n• risico's voor de digitale veiligheid beoordelen\n• kwetsbaarheden tijdens de ondersteuningsperiode van een product aanpakken\n• zorgen voor beveiligingsupdates\n• informatie geven over de veiligheid en het veilige gebruik van het product\n• aantonen dat het product aan de regels voldoet","Producten die aan de regels voldoen, krijgen een CE-markering. Voor sommige producten is een beoordeling door een externe partij nodig.","Ook importeurs en distributeurs krijgen verplichtingen. Zij moeten onder andere controleren of producten aan de CRA voldoen voordat zij deze op de Europese markt aanbieden."],"doen":[],"law":[{"href":"https://www.rijksfinancien.nl/memorie-van-toelichting/2026/OWB/XIII/onderdeel/9647760","text":"Memorie van Toelichting EZ (Overheid.nl)"},{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=OJ:L_202402847","text":"Cyberweerbaarheidsverordening Verordening 2024/2847 (EU)"},{"href":"https://www.internetconsultatie.nl/uitvoeringswetcra/b1","text":"Consultatie Uitvoeringswet Verordening cyberweerbaarheid (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/mandatory-cybersecurity-requirements-for-products-cra/","mod":"2026-09-14"},{"id":"bedrijven-moeten-dwangarbeid-in-keten-tegengaan","t":"Bedrijven moeten dwangarbeid in keten tegengaan","d":"2027-12-14","dn":"","sec":[],"sub":["internationaal-ondernemen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/bedrijven-moeten-dwangarbeid-in-keten-tegengaan/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["importeurs en exporteurs van producten","producenten van producten (diensten vallen er niet onder)","ondernemers die producten online verkopen"],"vwt":"De Anti-dwangarbeidsverordening geldt voor alle producten en voor alle bedrijven en economische sectoren, zoals:","wat":["Bent u ondernemer en importeert of exporteert u producten? Dan moet u vanaf 2027 rekening houden met de Anti-dwangarbeidverordening (FLR). Deze nieuwe EU-wet verbiedt het aanbieden, verkopen of exporteren van producten die (voor een deel) zijn gemaakt met dwangarbeid of gedwongen kinderarbeid. Dit geldt voor alle bedrijven, sectoren en producten. Het maakt dus niet uit waar die vandaan komen. Ook producten die u online verkoopt vallen onder deze regel.","Wat betekent dit voor u?","• U mag geen producten meer op de EU-markt brengen als deze (voor een deel) zijn gemaakt met dwangarbeid.\n• De overheid controleert actief op overtredingen. Is er een vermoeden van dwangarbeid? Dan wordt dat onderzocht en kunnen uw producten worden tegenhouden of in beslag genomen aan de grens.\n• Als u due diligence (gepaste zorgvuldigheid) gebruikt, kunt u voorkomen dat er dwangarbeid in uw keten zit. Met due diligence kunt u bewijzen dat er geen dwangarbeid in uw keten zit, of dat u stappen heeft ondernomen om dit tegen te gaan."],"doen":[],"law":[{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=OJ:L_202403015","text":"Anti-dwangarbeidverordening (Forced Labour Regulation) (FLR) (EU)"}],"en":"https://business.gov.nl/amendments/businesses-must-combat-forced-labour/","mod":"2026-08-25"},{"id":"btw-op-bloemen-en-planten-gaat-omhoog-van-9-naar-21","t":"Afschaffing laag btw-tarief (9%) op bloemen en planten","d":"2028-01-01","dn":"nog niet bekend","sec":["agrosector","horeca-recreatie-en-catering"],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/btw-op-bloemen-en-planten-gaat-omhoog-van-9-naar-21/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel is doorgeschoven naar het Belastingplan 2028. Het voorstel wordt in 2027 besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["sierteeltbedrijven en kwekers","bloemisten en tuincentra","supermarkten, benzinestations en overige ondernemers die bloemen en planten verkopen","importeurs van sierteeltproducten"],"vwt":"","wat":["Bent u ondernemer in de sierteelt of verkoopt u bloemen en planten? De btw op sierteeltproducten verandert. De regering wil het verlaagde btw-tarief van 9% afschaffen. Het algemene btw-tarief van 21% gaat dan gelden voor alle sierteeltproducten, zoals:","• bloembollen, snijbloemen en planten\n• kamer- en balkonplanten\n• perk- en vaste planten\n• boomkwekerijproducten\n• geïmporteerde sierteeltproducten","Let op: Verkoopt u sierteeltproducten naar het buitenland? Dat blijft buiten deze btw-verhoging."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/btwsierteelt/b1","text":"Consultatie Afschaffing verlaagd btw-tarief voor sierteeltproducten (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/vat-on-flowers-and-plants-to-go-up-from-9-to-21-percent/","mod":"2026-11-05"},{"id":"btw-op-ballonvaarten-gaat-omhoog-naar-21-procent","t":"Btw op ballonvaarten gaat omhoog naar 21%","d":"2028-01-01","dn":"","sec":["horeca-recreatie-en-catering"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/btw-op-ballonvaarten-gaat-omhoog-naar-21-procent/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["ondernemers die ballonvaarten aanbieden"],"vwt":"","wat":["Biedt u ballonvaarten aan? Vanaf 1 januari 2028 stijgt de btw op ballonvaarten van 9% naar 21%.","Het btw-tarief van 21% geldt voor ballonvaarten die vanaf 1 januari 2028 plaatsvinden. Betaalt een klant in 2027 voor een ballonvaart in 2028? Dan geldt ook al het btw-tarief van 21%."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/vat-on-hot-air-balloon-rides-set-to-rise-to-21/","mod":"2026-11-13"},{"id":"compensatie-voor-transitievergoeding-verdwijnt","t":"Compensatie voor transitievergoeding verdwijnt","d":"2028-01-01","dn":"","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/compensatie-voor-transitievergoeding-verdwijnt/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["ondernemers met personeel","werkgevers die een werknemer ontslaan na langdurige arbeidsongeschiktheid","werkgevers die hun bedrijf beëindigen door pensioen of overlijden"],"vwt":"","wat":["Moet u een transitievergoeding betalen, omdat u bijvoorbeeld een werknemer ontslaat? U kunt in sommige situaties een compensatie krijgen voor een betaalde transitievergoeding. Vanaf 1 januari 2028 verdwijnen deze compensatieregelingen.","Eerder was het plan om deze compensatieregelingen vanaf 1 januari 2027 af te schaffen. Het kabinet stelt de afschaffing met 1 jaar uit. U kunt dan geen compensatie meer krijgen als u een werknemer ontslaat die langer dan 2 jaar ziek is. Ook de compensatie bij bedrijfsbeëindiging door pensioen of overlijden van de werkgever verdwijnt."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/wijzigingivmbeperkencompensatieregelingtransitievergoedinglangdurigearbeidsongeschiktheid/b1","text":"Consultatie Wijziging van Boek 7 van het Burgerlijk Wetboek in verband met het beperken van de compensatieregeling transitievergoeding bij ontslag wegens langdurige arbeidsongeschiktheid tot kleine werkgevers (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/compensation-for-transition-payment-to-end/","mod":"2026-11-13"},{"id":"grote-bedrijven-moeten-rapporteren-over-duurzaamheid","t":"CSRD: minder bedrijven moeten rapporteren over duurzaamheid","d":"2028-01-01","dn":"stapsgewijs vanaf 2028","sec":[],"sub":["klimaat-energie-en-natuur"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/grote-bedrijven-moeten-rapporteren-over-duurzaamheid/","sh":"De EU heeft deze nieuwe regels aangenomen: houd hier rekening mee","se":"Dit is een Europese richtlijn. Nederland moet deze gewijzigde regels nog verwerken in de Nederlandse wetgeving. De precieze Nederlandse regels en ingangsdata zijn nog niet allemaal bekend.","ph":"vast","vw":["ondernemingen die onder de CSRD vallen","bedrijven die zakendoen met ondernemingen die onder de CSRD vallen en daarom mogelijk informatie over duurzaamheid moeten aanleveren"],"vwt":"","wat":["De Europese regels voor duurzaamheidsrapportage (CSRD) veranderen. Daardoor hoeven minder bedrijven dan eerder was voorzien een duurzaamheidsrapport op te stellen. Ook worden de rapportageverplichtingen voor een deel van de bedrijven met 2 jaar uitgesteld.","De belangrijkste veranderingen zijn:","• Vanaf boekjaar 2027 moeten alleen ondernemingen met meer dan 1.000 werknemers én een netto-omzet van meer dan € 450 miljoen een verplichte duurzaamheidsrapportage opstellen.\n• Andere bedrijven zijn niet verplicht om te rapporteren. Zij kunnen wel vrijwillig rapporteren volgens de Europese vrijwillige rapportagestandaard voor mkb-bedrijven (VSME).\n• Bedrijven die niet rapportageplichtig zijn, kunnen nog wel vragen krijgen van klanten of andere bedrijven in hun keten om informatie over duurzaamheid.","In een duurzaamheidsrapport beschrijven bedrijven onder meer de gevolgen van hun activiteiten voor mens, milieu en bestuur."],"doen":[],"law":[{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=OJ:L_202500794","text":"Wijzigingsrichtlijn (EU) 2025/794 (uitstel van rapportageverplichtingen)(EU)"},{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=CELEX:32022L2464","text":"EU-richtlijn (EU) 2022/2464 Corporate Sustainability Reporting Standards (ESRS)"},{"href":"https://www.rijksoverheid.nl/documenten/rapporten/2024/06/12/tk-bijlage-implementatiebesluit-richtlijn-duurzaamheidsrapportering-versie-voorhang-mr","text":"Ontwerpbesluit tot implementatie van de richtlijn duurzaamheidsrapportering (Rijksoverheid)"},{"href":"https://www.eerstekamer.nl/wetsvoorstel/36678_wet_implementatie_richtlijn","text":"Wet implementatie richtlijn duurzaamheidsrapportering (Eerste Kamer)"}],"en":"https://business.gov.nl/amendments/large-companies-must-report-sustainability/","mod":"2026-06-23"},{"id":"doorgeven-loongegevens-via-ikv-wordt-makkelijker","t":"Doorgeven loongegevens via IKV wordt makkelijker","d":"2028-01-01","dn":"","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/doorgeven-loongegevens-via-ikv-wordt-makkelijker/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["werkgevers die loongegevens doorgeven (loonadministratie)","ondernemers met personeel in opvolgende contracten","salarisprofessionals","ontwikkelaars van salarissoftware"],"vwt":"","wat":["Bent u werkgever en geeft u loongegevens door aan de Belastingdienst en UWV? Dan wordt het binnenkort makkelijker. De regering past de regels aan rond de inkomstenverhouding (IKV). U maakt niet langer voor elk nieuw contract een aparte IKV.","U moet direct opvolgende contracten voortaan in 1 IKV zetten. Dit past beter bij hoe het in de praktijk vaak gaat. Het verlaagt administratieve lasten.","De belangrijkste veranderingen op een rij:","• U combineert opvolgende contracten met dezelfde werknemer in één inkomstenverhouding (IKV).\n• U hoeft geen nieuwe IKV meer te starten bij een nieuw contract als dit contract direct aansluit op het einde van het vorige contract.\n• Dit levert minder werk en minder regeldruk op bij de loonaangifte.\n• De kwaliteit van de gegevens in de polisadministratie gaat omhoog."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/wijzigingsbesluitopvolgendedienstbetrekkingen/b1","text":"Consultatie Wijzigingsbesluit opvolgende dienstbetrekkingen (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/supplying-wage-data-via-income-relationship-ikv-will-be-easier/","mod":"2026-09-08"},{"id":"kleine-brouwerijen-gaan-meer-accijns-betalen","t":"Kleine brouwerijen gaan meer accijns betalen","d":"2028-01-01","dn":"","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/kleine-brouwerijen-gaan-meer-accijns-betalen/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["zelfstandige kleine brouwerijen die niet meer dan 200.000 hectoliter bier per jaar produceren."],"vwt":"","wat":["Heeft u een kleine brouwerij met een productie van niet meer dan 200.000 hectoliter bier per jaar? Dan gaat u meer accijns betalen. De kleine brouwersregeling stopt. Het accijnstarief voor kleine brouwers wordt zo even hoog als voor andere brouwers."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/small-breweries-will-pay-more-excise-duty/","mod":"2026-11-13"},{"id":"meer-bedrijven-moeten-milieugegevens-rapporteren","t":"Meer bedrijven moeten milieugegevens rapporteren","d":"2028-01-01","dn":"","sec":[],"sub":["klimaat-energie-en-natuur"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/meer-bedrijven-moeten-milieugegevens-rapporteren/","sh":"Deze Europese wet is goedgekeurd: bereid uw bedrijf voor","se":"Dit is een Europese Verordening. Deze wet is goedgekeurd in Europa. Er is vaak een overgangstermijn van 1 of 2 jaar, maar de regels staan vast. U moet uw bedrijf aanpassen.","ph":"vast","vw":["bedrijven die nu al een PRTR-verslag moeten indienen","bepaalde stookinstallaties vanaf 20 MW","mijnbouwbedrijven en bedrijven die olie of gas winnen","bedrijven in dagbouw en steenwinning vanaf 25 hectare","rioolwaterzuiveringsinstallaties vanaf 100.000 bevolkingsequivalenten","aquacultuurbedrijven met een productiecapaciteit van meer dan 500 ton per jaar","bepaalde scheepswerven met capaciteit voor schepen van 100 meter","bedrijven die op industriële schaal waterstof maken door elektrolyse van water"],"vwt":"De nieuwe regels gelden voor grote industriële bedrijven en bepaalde andere bedrijven die het milieu kunnen vervuilen. Bijvoorbeeld: Of u jaarlijks milieugegevens moet rapporteren, hangt af van uw activiteiten, de grootte of capaciteit van uw installatie en de hoeveelheid uitstoot of afval. In bijlage I van de Europese PIE-verordening staan alle activiteiten en de bijbehorende capaciteitsgrenzen. In artikel 6 van de Europese PIE-verordening staan de voorwaarden voor de rapportageplicht.","wat":["Meer bedrijven moeten milieugegevens gaan rapporteren. De Europese regels voor het PRTR-verslag worden vervangen door nieuwe regels voor het Portaal Industriële Emissies (PIE). Vervuilt u met uw (grote) industriële bedrijf mogelijk het milieu? Dan moet u misschien milieugegevens rapporteren.","Moet u nu al een PRTR-verslag indienen? Dan krijgt u te maken met de nieuwe PIE-regels. Ook als u nu nog geen PRTR-verslag hoeft in te dienen, kunt u straks verplicht worden om milieugegevens te rapporteren.","Meer milieugegevens rapporteren","Onder de nieuwe PIE-regels moet u meer informatie over uw bedrijf aanleveren. Afhankelijk van uw activiteiten rapporteert u onder andere over:","• uitstoot van bepaalde vervuilende stoffen in lucht, water en bodem\n• afval dat uw bedrijf naar een andere locatie brengt\n• vervuilende stoffen in afvalwater dat uw bedrijf naar een andere locatie brengt\n• watergebruik\n• energiegebruik\n• gebruik van relevante grondstoffen\n• productie en bedrijfsuren","Rapporteren per industriële installatie","De nieuwe regels maken meer onderscheid tussen verschillende industriële installaties. Heeft uw bedrijf meerdere installaties? Dan moet u voor bepaalde gegevens aangeven over welke installatie ze gaan.","Zo wordt duidelijker welke installaties vervuilende stoffen uitstoten en hoeveel water, energie en grondstoffen zij gebruiken.","De milieugegevens komen in het Europese Portaal Industriële Emissies. Dit portaal vervangt het Europese PRTR-register."],"doen":[],"law":[{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=OJ:L_202401244","text":"Verordening (EU) 2024/1244 – Portaal Industriële Emissies (PIE) (Eur-lex)"}],"en":"https://business.gov.nl/amendments/more-businesses-must-report-environmental-data/","mod":"2026-10-13"},{"id":"motorrijtuigenbelasting-voor-oldtimers-van-na-1988","t":"Motorrijtuigenbelasting voor oldtimers vanaf 1988","d":"2028-01-01","dn":"","sec":["vervoer"],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/motorrijtuigenbelasting-voor-oldtimers-van-na-1988/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["ondernemers met een oldtimer"],"vwt":"","wat":["Heeft u een oldtimer? Dan betaalt u vanaf 2028 mogelijk motorrijtuigenbelasting als uw auto vanaf 1988 is gebouwd. Is uw auto vóór 1988 gebouwd dan hoeft u geen motorrijtuigenbelasting te betalen. Een auto uit 1988 is in 2028 40 jaar oud.","Op dit moment hoeft u geen belasting te betalen als uw auto minimaal 40 jaar geleden voor het eerst geregistreerd is."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-444.html","text":"Belastingplan 2026 (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/motor-vehicle-tax-old-timers/","mod":"2026-08-31"},{"id":"nieuwe-aanvraag-ioaz-uitkering-niet-meer-mogelijk","t":"Nieuwe aanvraag IOAZ-uitkering niet meer mogelijk","d":"2028-01-01","dn":"","sec":[],"sub":["bedrijf-stoppen-of-overdragen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/nieuwe-aanvraag-ioaz-uitkering-niet-meer-mogelijk/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["oudere ondernemers die stoppen met hun bedrijf door te weinig inkomsten of gedeeltelijk arbeidsongeschikt raken"],"vwt":"","wat":["Vanaf 1 januari 2028 kunt u niet meer de uitkering Inkomensvoorziening oudere en gedeeltelijke arbeidsongeschikte zelfstandigen (IOAZ) aanvragen.","De IOAZ is een uitkering voor oudere ondernemers die stoppen omdat het bedrijf te weinig inkomsten oplevert of door gedeeltelijke arbeidsongeschiktheid. Bent u 55 jaar of ouder, maar heeft u de AOW-leeftijd nog niet bereikt? Dan kunt u nog tot 1 januari 2028 de IOAZ aanvragen. Nieuwe aanvragen zijn daarna niet meer mogelijk. Voor ondernemers die op dat moment al een IOAZ-uitkering krijgen, verandert er niets."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/new-applications-for-ioaz-no-longer-possible/","mod":"2026-11-13"},{"id":"nulurencontracten-niet-meer-toegestaan","t":"Nulurencontracten niet meer toegestaan","d":"2028-01-01","dn":"nog niet bekend","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/nulurencontracten-niet-meer-toegestaan/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["ondernemers met personeel met een nulurencontract"],"vwt":"","wat":["Heeft u werknemers met een nulurencontract? Voor structureel werk is een (vast) contract het uitgangspunt. U moet werknemers met een oproepcontract in de toekomst een vast basiscontract geven voor de uren die ze minimaal standaard worden ingeroosterd. Nulurencontracten zijn niet meer toegestaan. Zo weten werknemers beter waar ze aan toe zijn.","Bandbreedtecontract","In plaats van de nulurencontracten komt er een bandbreedtecontract. Daarin wordt er een minimum- en een maximumaantal uren afgesproken, waarbij het verschil maximaal 30% is. Dit betekent dat bij een minimum van 10 uur het maximum 13 uur is.","Jongeren, scholieren, studenten met bijbanen en AOW-gerechtigden mogen straks nog wel op een oproepcontract werken."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-206.html","text":"Besluit inwerkingtreding Wet meer zekerheid flexwerkers (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-205.html","text":"Wet meer zekerheid flexwerkers (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/wetverbeteringrechtspositieflexibelearbeidskrachten/b1","text":"Consultatie. Wet verbetering zekerheid flexibele arbeidskrachten (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/zero-hours-contracts-banned/","mod":"2026-09-17"},{"id":"taxis-krijgen-nieuw-verplicht-registratiesysteem","t":"Taxi’s krijgen nieuw verplicht registratiesysteem","d":"2028-01-01","dn":"","sec":["vervoer"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/taxis-krijgen-nieuw-verplicht-registratiesysteem/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["taxiondernemers","taxichauffeurs"],"vwt":"","wat":["Bent u taxiondernemer of taxichauffeur? Dan kunt u gebruikmaken van het nieuwe registratiesysteem voor taxiritten: de Centrale Database Taxivervoer (CDT). Dit digitale systeem maakt het voor u makkelijker om ritgegevens door te geven. Ook maakt het de taximarkt veiliger.","Met de CDT bent u straks verplicht om ritgegevens automatisch en direct aan te leveren bij de Inspectie Leefomgeving en Transport (ILT). U kiest voor een apparaat of app die hiervoor geschikt is. Dit vervangt de huidige boordcomputer (BCT), waar de gegevens nog handmatig moeten worden uitgehaald. Met het nieuwe systeem bespaart u tijd en kosten, omdat het invoeren en verwerken automatisch gaat.","Met de CDT kan de inspectie beter controleren of chauffeurs zich aan werk- en rusttijden houden. Dit maakt de taximarkt veiliger. Doordat gegevens direct worden gedeeld, kan fraude sneller worden ontdekt."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-161.html","text":"Besluit wijziging Besluit personenvervoer 2000 en het Arbeidstijdenbesluit vervoer voor invoering centrale database taxivervoer (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/centrale_database_taxivervoer/b1","text":"Consultatie. Wijzigingen ten behoeve van de Centrale Database Taxivervoer (CDT)"}],"en":"https://business.gov.nl/amendments/new-mandatory-registration-system-for-taxi-rides/","mod":"2026-08-31"},{"id":"werkgever-mag-tijdelijk-contract-niet-blijven-verlengen","t":"Werkgever mag tijdelijk contract niet blijven verlengen","d":"2028-01-01","dn":"","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/werkgever-mag-tijdelijk-contract-niet-blijven-verlengen/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["ondernemers met personeel met tijdelijke contracten"],"vwt":"","wat":["Werkt u met tijdelijke contracten voor uw personeel? U mag straks een tijdelijk contract (arbeidscontract voor bepaalde tijd) niet blijven verlengen.","Als na 3 tijdelijke contracten het contract afloopt, mag u de werknemer 5 jaar geen tijdelijk contract geven.","Nu is die wachttijd 6 maanden. Door deze korte periode ontstaan draaideurconstructies waarbij een werknemer 6 maanden moet stoppen of ander werk moet zoeken om daarna weer terug te komen.","De regering wil dat tijdelijke contracten alleen gebruikt worden voor tijdelijk werk. En dat werknemers sneller een vast contract (vast dienstverband) krijgen."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-206.html","text":"Besluit inwerkingtreding Wet meer zekerheid flexwerkers (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2026-205.html","text":"Wet meer zekerheid flexwerkers (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/employer-may-not-keep-renewing-temporary-contracts/","mod":"2026-08-27"},{"id":"willekeurige-afschrijving-starters-stopt","t":"Willekeurige afschrijving starters stopt","d":"2028-01-01","dn":"","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/willekeurige-afschrijving-starters-stopt/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["startende ondernemers die de willekeurige afschrijving starters gebruiken"],"vwt":"","wat":["De willekeurige afschrijving starters wordt vanaf 2028 afgeschaft, tegelijk met de startersaftrek. Dat betekent dat vanaf 2028 de gebruikelijke afschrijvingsregels voor bedrijfsmiddelen weer gelden.","Bent u een startende ondernemer voor de inkomstenbelasting en gebruikt u de startersaftrek? Dan mag u nu nog zelf bepalen hoe snel u wilt afschrijven op bedrijfsmiddelen die u kocht in de jaren dat u startersaftrek kon krijgen of in het jaar ervoor (het aanloopjaar). Deze regeling heet de willekeurige afschrijving starters."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/random-depreciation-for-starting-entrepreneurs-to-end/","mod":"2026-11-13"},{"id":"vleesbedrijven-mogen-geen-uitzendkrachten-meer-inzetten","t":"Vleesbedrijven mogen geen uitzendkrachten meer inzetten","d":"2028-03-01","dn":"","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/vleesbedrijven-mogen-geen-uitzendkrachten-meer-inzetten/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["ondernemers in de vleesketen","bedrijven die arbeidskrachten uitlenen aan de vleesketen"],"vwt":"","wat":["Zet u uitzendkrachten in voor werkzaamheden in de vleesketen? Dan krijgt u te maken met nieuwe regels. Er komt een verbod op het inlenen en uitlenen van arbeidskrachten in de vleesketen.","Het verbod geldt bijvoorbeeld voor:","• slachthuizen\n• koelhuizen\n• vleesverwerkende bedrijven","De Nederlandse Arbeidsinspectie controleert of bedrijven zich aan het in- en uitleenverbod houden.","Het verbod geldt niet voor werkzaamheden die niet direct te maken hebben met de productie of verwerking van vlees. Bijvoorbeeld verkoop en administratie.","Kleine bedrijven waar minder dan 20 arbeidskrachten werken, vallen niet onder het verbod. Behalve als het bedrijf onderdeel is van een groep waar samen 20 of meer arbeidskrachten werken. Eigen werknemers en ingeleende arbeidskrachten tellen allebei mee."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/uitzendverbodindevleesketen/b1","text":"Consultatie Uitzendverbod in de vleesketen (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/meat-industry-no-longer-allowed-to-employ-agency-workers/","mod":"2026-11-13"},{"id":"werkgevers-mogen-geen-huur-meer-inhouden-op-minimumloon","t":"Werkgevers mogen geen huur meer inhouden op minimumloon","d":"2028-07-01","dn":"","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/werkgevers-mogen-geen-huur-meer-inhouden-op-minimumloon/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt ook nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["werkgevers die huur inhouden op het minimumloon van werknemers","uitzendbureaus die huur inhouden op het minimumloon van werknemers"],"vwt":"","wat":["Regelt u huisvesting voor uw werknemers? Dan mag u straks geen huurkosten meer inhouden op het wettelijk minimumloon. Verdient uw werknemer meer dan het minimumloon? Dan kunt u onder voorwaarden nog wel huurkosten verrekenen met het loon boven het minimumloon.","Nu mag u onder voorwaarden nog maximaal 25% van het bruto minimumloon inhouden voor huisvesting. De woning moet bijvoorbeeld gecertificeerd zijn.","Het kabinet wil deze mogelijkheid afschaffen. Zo wil het voorkomen dat werkgevers te veel huur vragen voor woonruimte. Ook wil het kabinet arbeidsmigranten minder afhankelijk maken van hun werkgever."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/employers-no-longer-allowed-to-deduct-rent-from-minimum-wage/","mod":"2026-10-19"},{"id":"bosbouwvrijstelling-voor-bosbouwbedrijven-afgeschaft","t":"Bosbouwvrijstelling voor bosbouwbedrijven afgeschaft","d":"2029-01-01","dn":"","sec":["agrosector"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/bosbouwvrijstelling-voor-bosbouwbedrijven-afgeschaft/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["ondernemers in de bosbouw"],"vwt":"","wat":["Bent u ondernemer in de bosbouw? Vanaf 1 januari 2029 wordt de bosbouwvrijstelling afgeschaft. Met de bosbouwvrijstelling hoeft u over de winst uit uw bosbouwbedrijf geen belasting te betalen. Vanaf 2029 moet u dus over winst uit uw bosbedrijf belasting betalen.","Het kabinet wil een deel van de opbrengst van het afschaffen van de bosbouwvrijstelling (€ 5 miljoen) gebruiken voor natuurbeleid (Ministerie van LVVN)."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/exemption-for-income-from-forestry-activities-abolished/","mod":"2026-11-13"},{"id":"startersaftrek-bij-arbeidsongeschiktheid-verdwijnt","t":"Startersaftrek bij arbeidsongeschiktheid verdwijnt","d":"2029-01-01","dn":"","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/startersaftrek-bij-arbeidsongeschiktheid-verdwijnt/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["startende ondernemers met recht op een arbeidsongeschiktheidsuitkering"],"vwt":"","wat":["Het kabinet wil stoppen met de startersaftrek bij arbeidsongeschiktheid vanaf 1 januari 2029. U kunt de aftrekpost dan niet meer gebruiken bij de aangifte inkomstenbelasting.","De startersaftrek bij arbeidsongeschiktheid is een speciale regeling voor startende ondernemers die recht hebben op een (kwalificerende) arbeidsongeschiktheidsuitkering. Dit is een aftrekpost voor de inkomstenbelasting in de eerste jaren van de onderneming. De ondernemer moet dan wel minimaal 800 uur (maar minder dan 1225 uur) aan werkzaamheden voor de onderneming besteden.","Het verdwijnen van de startersaftrek bij arbeidsongeschiktheid levert het kabinet geld op om het maatregelenpakket energieschok te betalen. Ook komt er geld vrij om de belastingverhoging op arbeid te beperken.","Let op: Krijgt u een toeslag? Als de regeling stopt, wordt uw verzamelinkomen hoger. Het kan zijn dat u dan een te hoog voorschot op uw toeslag krijgt. Controleer daarom voor 2029 of het verzamelinkomen nog klopt of geef uw nieuwe geschatte verzamelinkomen door."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/tax-relief-for-new-companies-in-case-of-occupational-disability-to-end/","mod":"2026-11-13"},{"id":"e-factuur-verplicht-bij-transactie-tussen-ondernemers","t":"E-factuur verplicht bij transactie tussen ondernemers","d":"2030-07-01","dn":"","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/e-factuur-verplicht-bij-transactie-tussen-ondernemers/","sh":"De EU heeft deze nieuwe regels aangenomen: houd hier rekening mee","se":"Dit is een Europese Richtlijn. Nederland moet deze nieuwe regels de komende 2 jaar invoeren. De precieze Nederlandse regels en datums zijn er nog niet.","ph":"vast","vw":["ondernemers die facturen sturen aan of ontvangen van andere ondernemers","ondernemers die zakendoen met bedrijven in andere EU-landen"],"vwt":"","wat":["Stuurt u facturen aan andere ondernemers? Dan moet u straks e-facturen gebruiken. De Europese regels gelden voor zakelijke transacties tussen ondernemers in EU-landen. Het kabinet wil e-facturatie ook verplicht stellen voor binnenlandse zakelijke transacties. De e-facturen moeten voldoen aan een vaste Europese standaard.","Een e-factuur heeft gestructureerde gegevens die software automatisch kan inlezen en verwerken. Een pdf-factuur die per e-mail is verstuurd, voldoet niet aan deze Europese standaard.","Doet u zaken met ondernemers in andere EU-landen? Dan moet u ook bepaalde gegevens uit uw facturen digitaal doorgeven aan de Belastingdienst. U rapporteert dan per transactie.","De rapportageverplichtingen kunnen invloed hebben op het werk van kopers en verkopers. Ook als u alleen zakelijke facturen uit een ander EU-land ontvangt, kunnen de regels voor u relevant zijn.","Voor transacties met ondernemers in andere EU-landen gaan de volgende regels gelden:","• U verstuurt een e-factuur binnen 10 dagen nadat u een product heeft geleverd of een dienst heeft uitgevoerd.\n• U geeft de factuurgegevens digitaal door aan de Belastingdienst.\n• U geeft de gegevens per factuur door aan de Belastingdienst. De nieuwe digitale rapportage vervangt de opgaaf ICP voor transacties met ondernemers in andere EU-landen.","Voor zakelijke transacties binnen Nederland wil het kabinet ook een digitale rapportageplicht invoeren. U moet dan bepaalde gegevens uit uw e-facturen doorgeven aan de Belastingdienst.","Doet u mee aan de kleineondernemersregeling (KOR)? Dan wil het kabinet u vrijstellen van de verplichting om e-facturen te versturen en factuurgegevens digitaal door te geven voor zakelijke transacties binnen Nederland."],"doen":[],"law":[{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=OJ:L_202500516","text":"Richtlijn (EU) 2025/516 over de btw-regels voor het digitale tijdperk (EU)"}],"en":"https://business.gov.nl/amendments/e-invoicing-mandatory-for-business-to-business-transactions/","mod":"2026-10-20"},{"id":"bezorgdiensten-moeten-leeftijd-controleren-bij-afleveren-alcohol","t":"Bezorgdiensten moeten leeftijd controleren bij afleveren alcohol","d":null,"dn":"in 2027","sec":["vervoer","detailhandel-groothandel-en-ambachten"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/bezorgdiensten-moeten-leeftijd-controleren-bij-afleveren-alcohol/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt ook nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["bezorgdiensten die alcohol thuisbezorgen","pakketbezorgers die alcohol afleveren","online verkopers van alcohol"],"vwt":"Werkt u bij een bezorgdienst en bezorgt u alcohol aan huis? Vanaf 2027 krijgt uw bedrijf een boete als u alcohol aflevert bij minderjarigen.","wat":["De regering scherpt de regels aan voor het handhaven van de leeftijdsgrens voor alcoholverkoop. U moet voortaan altijd de leeftijd controleren bij het bezorgen van bier, wijn of sterke drank.","Nu kan alleen de webshop die alcohol verkoopt een boete krijgen. Maar de online verkoper en de bezorgdienst zijn vaak niet hetzelfde bedrijf. Daarom komen er nieuwe regels voor bezorgdiensten.","De volgende regels gaan gelden voor bezorgdiensten:","• U moet de leeftijd van de ontvanger controleren als u alcohol aflevert aan huis.\n• Levert u alcohol af bij een minderjarige? Dan krijgt uw bedrijf een boete.\n• Voor pakketbezorgers gelden dezelfde regels als voor personeel in de horeca, supermarkten en sportkantines.","Extra maatregel: duidelijke verpakking","Op de buitenste verpakking van pakketten met alcohol is straks een fysiek kenmerk verplicht. Zo ziet u meteen dat in een pakket een product zit waarvoor een minimumleeftijd geldt."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/wijzigingalcoholbesluit2026/b1","text":"Consultatie Wijziging Alcoholbesluit voor het leeftijdsverificatiesysteem, een fysiek kenmerk (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/delivery-services-must-check-age-upon-delivery-alcohol/","mod":"2026-11-02"},{"id":"bingo-mag-weer-op-plekken-met-alcoholvergunning","t":"Bingo mag weer op plekken met alcoholvergunning","d":null,"dn":"in 2026","sec":["horeca-recreatie-en-catering"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/bingo-mag-weer-op-plekken-met-alcoholvergunning/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["horecaondernemers met een alcoholvergunning","verenigingen die bingo’s organiseren"],"vwt":"","wat":["Organiseert u bingo’s in een horecagelegenheid? Dan mag dat binnenkort weer, ook als er alcohol wordt geschonken. Zonder dat dat de bedoeling was, verbood de Alcoholwet het om een bingo te houden op plekken met een alcoholvergunning. Het kabinet past de wet aan, zodat kleinschalige bingo’s, waarbij niet het doel is om winst te maken, weer mogelijk worden.","De volgende voorwaarden blijven gelden:","• Bingo mag alleen worden georganiseerd zonder het doel om winst te maken.\n• De maximale prijs per ronde is € 400.\n• De organisatie moet in handen zijn van een Nederlandse vereniging die minimaal 3 jaar bestaat en niet gericht is op kansspelen."],"doen":[],"law":[{"href":"https://wetgevingskalender.overheid.nl/Regeling/WGK026972","text":"Wijziging van de Alcoholwet ivm het organiseren van kleine kansspelen in horecalokaliteiten (Wetgevingskalender)"}],"en":"","mod":"2026-09-08"},{"id":"colportage-krijgt-verplichte-afkoelperiode-van-3-dagen","t":"Colportage krijgt verplichte afkoelperiode van 3 dagen","d":null,"dn":"nog niet bekend","sec":[],"sub":["bedrijfsvoering"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/colportage-krijgt-verplichte-afkoelperiode-van-3-dagen/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ondernemers die producten of diensten verkopen via deur-tot-deurverkoop","ondernemers die producten of diensten verkopen via straatverkoop"],"vwt":"","wat":["Verkoopt u producten of diensten aan de deur of op straat? Uw klanten krijgen binnenkort eerst 3 werkdagen bedenktijd voordat u een overeenkomst met hen kunt sluiten. Dit heet de afkoelperiode deur- en straatverkoop.","In deze 3 werkdagen mag u:","• geen contract afsluiten met de klant\n• geen contact opnemen met de klant over de verkoop","De klant krijgt zo de rust om uw informatie door te lezen en aanbiedingen te vergelijken. Na de afkoelperiode kunt u wel een overeenkomst sluiten. De bestaande bedenktijd van 14 dagen na het sluiten van een contract blijft gewoon bestaan. Klanten kunnen binnen die tijd nog steeds zonder reden opzeggen."],"doen":[],"law":[{"href":"https://internetconsultatie.nl/colportage/b1","text":"Consultatie Wetsvoorstel afkoelperiode colportage (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/mandatory-3-day-cooling-off-period-door-to-door-sales/","mod":"2026-09-08"},{"id":"eerder-duidelijkheid-over-vervanging-van-zieke-werknemer","t":"Eerder duidelijkheid over vervanging van zieke werknemer","d":null,"dn":"nog niet bekend","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/eerder-duidelijkheid-over-vervanging-van-zieke-werknemer/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["kleine en middelgrote ondernemers met personeel","re-integratiebedrijven","bedrijfsartsen en arbodiensten","verzuimverzekeraars"],"vwt":"","wat":["Bent u een mkb'er en is een van uw werknemers ziek? U weet straks eerder tot wanneer u de werkplek van een zieke werknemer beschikbaar moet houden. Zo kunt u sneller gaan zoeken naar vervanging van een zieke werknemer.","In de eerste 2 ziektejaren moet u samen met uw werknemer ervoor zorgen dat uw werknemer weer kan werken (re-integratieverplichting). U krijgt straks de mogelijkheid om vanaf de start van het 2e ziektejaar u alleen te richten op re-integratie in het tweede spoor. Dat betekent dat uw werknemer bij een andere werkgever aan het werk gaat. Dit kan als uw werknemer hiermee instemt of na toestemming van UWV.","Dit voorstel is een van de afspraken uit het brede arbeidsmarktpakket van april 2023."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/wetsvoorstelwijzigingreintegratieverplichtingentweedeziektejaar/b1","text":"Internetconsultatie wetsvoorstel tot wijziging van de re-integratieverplichtingen in het tweede ziektejaar bij werknemers van kleine en middelgrote werkgevers (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/clarity-replacing-sick-employee-sooner/","mod":"2026-09-08"},{"id":"ernstige-misstanden-op-de-werkvloer-worden-strafbaar","t":"Ernstige misstanden op de werkvloer worden strafbaar","d":null,"dn":"nog niet bekend","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/ernstige-misstanden-op-de-werkvloer-worden-strafbaar/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ondernemers met personeel"],"vwt":"","wat":["Werkt u met arbeidsmigranten? De strafbaarstelling van arbeidsuitbuiting wordt uitgebreid en makkelijker. Hierdoor kunnen daders beter worden opgespoord en vervolgd. Slachtoffers van mensenhandel en arbeidsuitbuiting worden zo beter beschermd.","Ernstige misstanden op de werkvloer worden strafbaar. Daarvoor wordt het nieuwe misdrijf ‘ernstige benadeling’ in de wet opgenomen. Dit zorgt ervoor dat werkgevers strafbaar zijn als zij op de werkvloer misbruik maken van een kwetsbare positie.","Naast misbruik moet er sprake zijn van grove benadeling zoals:","• veel te weinig loon betalen\n• overtreding van de arbeidsduur en arbeidstijden\n• slechte huisvesting\n• vrijheidsbeperkingen zoals inname van een paspoort","Ook worden de mogelijkheden groter om daders die financieel voordeel hebben van mensenhandel aan te pakken. Daarnaast wordt duidelijker omschreven welk gedrag strafbaar is.","Werkgevers moeten controleren","Ook werkgevers die mensen inhuren via een uitzendbureau moeten controleren dat de mensen die voor ze werken niet worden uitgebuit. Anders zijn ook zij strafbaar."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/mensenhandel/b1","text":"Consultatie Wetsvoorstel modernisering en uitbreiding strafbaarstelling mensenhandel (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/serious-workplace-abuse-punishable/","mod":"2026-09-08"},{"id":"faillissement-voorbereiden-wordt-makkelijker","t":"Faillissement voorbereiden wordt makkelijker","d":null,"dn":"nog niet bekend","sec":["persoonlijke-dienstverlening","zorg"],"sub":["bedrijf-stoppen-of-overdragen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/faillissement-voorbereiden-wordt-makkelijker/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ondernemingen met activiteiten waarbij maatschappelijke belangen worden gediend, zoals ziekenhuizen en onderwijsinstellingen"],"vwt":"","wat":["Heeft u een onderneming met activiteiten waarbij maatschappelijke belangen worden gediend, zoals een ziekenhuis of een onderwijsinstelling? En zit u in financiële problemen? Een mogelijk aankomend faillissement van uw bedrijf kunt u rustiger voorbereiden. Op die manier gaat de afwikkeling van een faillissement beter. En is de kans groter dat u door kunt gaan met het bedrijf of een doorstart kan maken met winstgevende bedrijfsonderdelen.","U kunt als ondernemer in financiële problemen de rechter vragen een stille bewindvoerder te benoemen. De stille bewindvoerder adviseert en begeleidt u in de omgang met uw schuldeisers. De stille bewindvoerder helpt u ook bij het vinden van een oplossing voor de financiële problemen om een faillissement te voorkomen."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/novelle_wet_continuiteit_ondernemingen_i","text":"Internetconsultatie. Novelle WCO I (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/preparing-bankruptcy-made-easier/","mod":"2026-09-08"},{"id":"gedragscode-wordt-verplicht-op-de-werkvloer","t":"Gedragscode wordt verplicht op de werkvloer","d":null,"dn":"nog niet bekend","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/gedragscode-wordt-verplicht-op-de-werkvloer/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["werkgevers met 10 of meer werknemers"],"vwt":"","wat":["Heeft u 10 of meer werknemers? U moet straks een gedragscode hebben tegen ongewenst gedrag op de werkvloer. Ongewenst gedrag is bijvoorbeeld pesten, seksuele intimidatie, discriminatie, agressie of geweld door collega’s of leidinggevenden.","In een duidelijke gedragscode beschrijft u wat wel en niet mag op en tijdens het werk. U moet uw personeel ook voorlichting geven over deze regels. Zo weten uw medewerkers waar zij aan toe zijn. Bedrijven krijgen ruimte om de gedragscode zelf in te vullen, zolang die aan basiseisen voldoet.","Door de gedragscode moet voor werkgevers duidelijk zijn welk gedrag zij wel en niet mogen laten zien.","Kleine bedrijven met minder dan 10 werknemers hoeven geen gedragscode te maken."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/wijzigingarbeidsomstandighedenwetivmverplichtegedragscodeongewenstgedrag/b1","text":"Consultatie Wijziging van de Arbeidsomstandighedenwet in verband met de invoering van een verplichte gedragscode ongewenst gedrag (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/code-of-conduct-mandatory-in-workplace/","mod":"2026-09-08"},{"id":"gegevens-van-mensen-met-schulden-makkelijker-uitgewisseld","t":"Gegevens van mensen met schulden makkelijker uitgewisseld","d":null,"dn":"nog niet bekend","sec":[],"sub":["bedrijfsvoering"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/gegevens-van-mensen-met-schulden-makkelijker-uitgewisseld/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["zzp’ers en dga's met schulden","werkgevers van werknemers met schulden"],"vwt":"","wat":["Bent u zzp’er of dga en heeft u schulden? Overheidsorganisaties en gerechtsdeurwaarders gaan informatie uitwisselen over beslagen en verrekeningen van mensen met schulden. Om de gegevens makkelijker uit te wisselen komt er een gezamenlijk informatiesysteem voor onder andere gerechtsdeurwaarders, gemeenten, waterschappen, UWV, de Belastingdienst en het Centraal Justitieel Incassobureau (CJIB).","Het informatiesysteem is onderdeel van het programma Stroomlijning Keten voor Derdenbeslag uit de Wet vereenvoudiging beslagvrije voet. Het systeem moet voorkomen dat meerdere partijen tegelijk beslag leggen op uw inkomen of het inkomen van uw werknemer."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/wetstroomlijningketenvoorderdenbeslag/b1","text":"Consultatie Wet stroomlijning keten voor derdenbeslag 2025 (Overheid.nl)"},{"href":"https://wetgevingskalender.overheid.nl/Regeling/WGK009943","text":"Wet stroomlijning keten voor derdenbeslag (Wetgevingskalender)"},{"href":"https://www.internetconsultatie.nl/stroomlijningketenderdenbeslag","text":"Consultatie. Besluit stroomlijning keten voor derdenbeslag (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/stroomlijningderdenbeslag","text":"Consultatie. Wet stroomlijning keten voor derdenbeslag 2020 (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/data-exchange-people-debts/","mod":"2026-09-08"},{"id":"inkomstenbelasting-omhoog-in-2027-en-2028","t":"Inkomstenbelasting omhoog in 2027 en 2028","d":null,"dn":"nog niet bekend","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/inkomstenbelasting-omhoog-in-2027-en-2028/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["ondernemers die inkomstenbelasting betalen"],"vwt":"","wat":["De inkomstenbelasting gaat omhoog in 2027 en 2028. De belastingschijven en heffingskortingen worden dan niet volledig gecompenseerd voor inflatie. In 2027 wordt de inflatiecorrectie-standaard voor 48% toegepast en in 2028 voor 12,2%. Als zelfstandig ondernemer met een eenmanszaak, vof of andere niet-rechtspersoon, gaat u in 2027 en 2028 daardoor meer inkomstenbelasting betalen.","Als de belastingschijven en heffingskortingen wel volledig voor inflatie zouden worden gecompenseerd, zou u tot een hoger bedrag onder schijf 1 of 2 vallen. U zou dan dus minder belasting betalen.","Ook wordt het tarief van de eerste en tweede schijf verhoogd met 0,06%."],"doen":[],"law":[{"href":"https://www.rijksoverheid.nl/documenten/2026/09/15/wetsvoorstel-belastingplan-2027","text":"Wetsvoorstel Belastingplan 2027 (Rijksoverheid)"}],"en":"https://business.gov.nl/amendments/income-tax-up-in-2027-and-2028/","mod":"2026-11-13"},{"id":"kilometerregistratie-voor-middelgrote-bedrijven-afgeschaft","t":"Kilometerregistratie voor middelgrote bedrijven wordt afgeschaft","d":null,"dn":"nog niet bekend","sec":[],"sub":["klimaat-energie-en-natuur"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/kilometerregistratie-voor-middelgrote-bedrijven-afgeschaft/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ondernemers die meer dan 100 maar minder dan 251 werknemers in dienst hebben"],"vwt":"","wat":["Heeft u 250 of minder werknemers in dienst, maar meer dan 100? Dan hoeft u in de toekomst niet meer te rapporteren hoeveel kilometers uw werknemers afleggen voor zakelijk verkeer of woon-werkverkeer.","Bedrijven met 100 of minder werknemers hoeven nu al niet bij te houden hoeveel kilometers hun werknemers afleggen. Deze grens wordt verhoogd naar 250 werknemers. Het kabinet wil met deze wijziging de regeldruk voor het mkb verminderen."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/wijziging_hoofdstuk_18_bal/b1","text":"Consultatie. Organisaties met minder dan 250 werknemers uitzonderen van de rapportageverplichting zakelijk en woon-werkverkeer (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/keeping-kilometre-records-no-longer-obliged-for-sme/","mod":"2026-09-08"},{"id":"kinderopvang-moet-ernstige-incidenten-melden","t":"Kinderopvang moet ernstige incidenten melden","d":null,"dn":"nog niet bekend","sec":["kinderopvang"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/kinderopvang-moet-ernstige-incidenten-melden/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["kinderopvangorganisaties","gastouders"],"vwt":"","wat":["Werkt u in de kinderopvang? Kinderopvangorganisaties en gastouders moeten ernstige veiligheidsincidenten melden. Als er een ernstig incident gebeurt in uw kinderopvang of bij u als gastouder, moet u dit zo snel mogelijk melden bij de GGD. Denk hierbij aan situaties waarin een kind in het ziekenhuis moet worden opgenomen of overlijdt als gevolg van een ongeluk."],"doen":[],"law":[{"href":"https://wetgevingskalender.overheid.nl/Regeling/WGK025939","text":"Wijziging Wet kinderopvang voor invoeren meldplicht incidenten (wetgevingskalender)"},{"href":"https://www.internetconsultatie.nl/wijzigingwetkinderopvanginverbandmetmeldplicht/b1","text":"Consultatie Wijziging Wet kinderopvang voor invoeren meldplicht (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/reporting-duty-serious-incidents-childcare/","mod":"2026-09-08"},{"id":"kinderopvang-moet-overzichten-beroepskrachten-en-presentielijsten-bewaren","t":"Kinderopvang moet overzichten beroepskrachten en presentielijsten bewaren","d":null,"dn":"nog niet bekend","sec":["kinderopvang"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/kinderopvang-moet-overzichten-beroepskrachten-en-presentielijsten-bewaren/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["kinderopvangorganisaties (dagopvang en buitenschoolse opvang)"],"vwt":"","wat":["Heeft u een kinderopvangorganisatie? Kinderopvangorganisaties moeten de overzichten van beroepskrachten die hebben gewerkt en de presentielijsten van kinderen 6 weken bewaren. De verplichting geldt voor de dagopvang en de buitenschoolse opvang (BSO).","U kunt als houder van de kinderopvangorganisatie met de overzichten laten zien dat uw organisatie voldoet aan de eisen voor de beroepskracht-kindratio (BKR), de drie-uursregeling en het vaste gezichtencriterium. U moet bij een controle door de GGD de overzichten van de afgelopen 6 weken kunnen geven."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/wijzigingregelingwetkinderopvang/b1","text":"Consultatie Regeling tot wijziging van de Regeling Wet kinderopvang ten behoeve van het uitbreiden van de administratieplicht van kindercentra (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/keeping-attendance-records-childcare/","mod":"2026-09-08"},{"id":"langer-korting-motorrijtuigenbelasting-autos-zonder-uitstoot","t":"Korting motorrijtuigenbelasting waterstof- en elektrische auto’s tot 2030","d":null,"dn":"1 januari 2026, 1 januari 2029 en 1 januari 2030","sec":[],"sub":["klimaat-energie-en-natuur","belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/langer-korting-motorrijtuigenbelasting-autos-zonder-uitstoot/","sh":"","se":"","ph":"onbekend","vw":["ondernemers die een elektrische personenauto hebben of willen kopen"],"vwt":"","wat":["Rijdt u in een waterstof- en elektrische personenauto? U krijgt ook na 2025 korting op de motorrijtuigenbelasting (wegenbelasting). De korting geldt tot en met 2029 en is voor nieuwe en tweedehands personenauto’s zonder uitstoot, zoals elektrische auto's en auto's die rijden op waterstof.","• In 2024 betaalde u geen motorrijtuigenbelasting voor een waterstof- of elektrische personenauto.\n• In 2025 betaalde u motorrijtuigenbelasting met 75% korting voor een uitstootvrije personenauto.\n• Van 2026 tot en met 2028 betaalt u motorrijtuigenbelasting met 30% korting voor een waterstof- en elektrische personenauto.\n• In 2029 betaalt u motorrijtuigenbelasting met 25% korting voor een uitstootvrije personenauto.\n• In 2030 is er geen korting meer en betaalt u het normale tarief voor de motorrijtuigenbelasting voor uw uitstootvrije personenauto.","De regering wil dat zoveel mogelijk mensen kiezen voor een auto die geen schadelijke stoffen uitstoot. De korting moet ervoor zorgen dat mensen met een waterstof- of elektrische personenauto niet meer motorrijtuigenbelasting betalen dan mensen met een vergelijkbare auto die rijdt op fossiele brandstof. Hoeveel mrb u betaalt heeft te maken met het gewicht van de auto. En elektrische auto’s zijn zwaarder dan benzineauto’s door de accu.","Geen korting voor elektrische bestelbussen en plug-in hybrides na 2025","De korting na 2025 geldt niet voor elektrische bestelbussen en overige voertuigen zonder uitstoot of plug-in hybrides. In 2025 was er nog wel korting voor de motorrijtuigenbelasting voor elektrische bestelbussen (75%) en plug-in hybride personenauto's (25%)."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2024-434.html","text":"Belastingplan 2025 (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/reduced-motor-vehicle-tax-electric-cars/","mod":"2026-06-30"},{"id":"maatregelen-om-kwaliteit-in-de-bouw-te-verbeteren-voor-bestaande-gebouwen-wkb","t":"Maatregelen om kwaliteit in de bouw te verbeteren voor bestaande gebouwen (Wkb)","d":null,"dn":"nog niet bekend","sec":["bouwnijverheid"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/maatregelen-om-kwaliteit-in-de-bouw-te-verbeteren-voor-bestaande-gebouwen-wkb/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["bouwbedrijven","kwaliteitsborgers in de bouw","zakelijke consumenten die utiliteitsbouw (bijvoorbeeld kantoren, scholen en ziekenhuizen) laten (ver-)bouwen en gebruiken","particuliere consumenten die een woning laten (ver-)bouwen en gebruiken"],"vwt":"","wat":["Maatregelen om de algehele kwaliteit van werk in de bouwsector te verbeteren zijn ingevoerd voor de bouw van nieuwe gebouwen. Voor renovatie, herbouw en ombouw van bestaande gebouwen zijn deze wijzigingen nog niet van kracht. De positie van zowel particuliere als zakelijke consumenten wordt beschermd.","De veranderingen bestaan uit:","• Bouwers zijn verplicht een onafhankelijke en gecertificeerde kwaliteitscontroleur in te schakelen. Deze private kwaliteitsborger toetst het bouwplan op risico’s en controleert op de bouwplaats of het werk aan alle wettelijke bouwvoorschriften voldoet.\n• Een beperkte omgevingsvergunning is voldoende. U hoeft niet meer te wachten op de goedkeuring van de bouwtechnische kwaliteit van het plan. Niet bij de eerste aanvraag en ook niet bij tussentijdse wijzigingen.\n• De verdeling van de aansprakelijkheid bij verborgen gebreken is zo verbeterd. De positie van de opdrachtgever is versterkt.\n• U moet als bouwende partij meer rekening houden met de wensen van de consument en opdrachtgever. Bijvoorbeeld over de indeling van een gebouw, de keuze van installaties en de afbouw.\n• Er komt een eindnorm waaraan alle bestaande utiliteitsbouw in 2050 zal moeten voldoen. Grote gebouweigenaren binnen het maatschappelijk en commercieel vastgoed worden gestimuleerd om een verduurzamingsstrategie te integreren in hun meerjarenonderhoudsplanning. Ook wordt er nieuwe wet- en regelgeving verwacht op het gebied van energiebesparing voor de utiliteitsbouw."],"doen":[],"law":[{"href":"https://wetten.overheid.nl/BWBR0042732/","text":"Wet kwaliteitsborging voor het bouwen (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2019-382.html","text":"Wet kwaliteitsborging voor het bouwen (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2022-145.html","text":"Besluit kwaliteitsborging voor het bouwen (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/measures-improve-quality-construction-sector/","mod":"2026-09-08"},{"id":"meerprijs-wegwerpbekers-en-bakjes-verdwijnt","t":"Meerprijs wegwerpbekers en -bakjes verdwijnt","d":null,"dn":"in 2027","sec":["horeca-recreatie-en-catering"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/meerprijs-wegwerpbekers-en-bakjes-verdwijnt/","sh":"Er is een plan om de regels te veranderen","se":"Het kabinet wil de regels veranderen. De wijziging is nog niet definitief. De regels kunnen dus nog anders worden, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ondernemers die eten en drinken voor onderweg aanbieden"],"vwt":"","wat":["Werkt u in de horeca? De wet over wegwerpplastic voor consumpties onderweg verandert. U hoeft geen extra kosten meer te rekenen voor plastic bekers en bakjes. Geen meerprijs voor plastic bekers en bakjes betekent minder administratie en eenvoudigere kassa-afhandeling voor horeca. Klanten betalen minder en bestellen eerder.","Sinds 1 juli 2023 moest u een meerprijs vragen voor plastic bekers en bakjes. Dit was onderdeel van de Europese regels tegen wegwerpplastic. Maar na een evaluatie en een aangenomen motie (voorstel voor een verandering) in de Tweede Kamer verdwijnt deze toeslag.","Als de wijziging ingaat, gelden deze regels voor uw bedrijf:","• Geen verplichte meerprijs: U hoeft geen extra kosten te rekenen voor wegwerpbekers of -bakjes van plastic.\n• Herbruikbaar alternatief blijft verplicht: U moet nog steeds een herbruikbare optie aanbieden. U kunt bijvoorbeeld herbruikbare bekers of bakjes aanbieden of door de klant meegenomen bekers en bakjes accepteren.\n• Korting geven mag: Wilt u klanten belonen die hun eigen beker of bakje meenemen? Dat mag! U beslist zelf of u korting geeft."],"doen":[],"law":[{"href":"https://www.rijksoverheid.nl/documenten/kamerstukken/2025/12/19/wijziging-regelgeving-voor-plastic-wegwerpbekers-en-bakjes-en-stand-van-zaken-moties-en-toezeggingen","text":"Kamerbrief met reactie op moties over wijziging regelgeving voor plastic wegwerpbekers en wegwerpbakjes (Rijksoverheid)"}],"en":"https://business.gov.nl/amendments/extra-charge-for-disposable-plastic-cups-and-containers-discontinued/","mod":"2026-09-30"},{"id":"minder-verkooppunten-tabaksproducten","t":"Minder verkooppunten tabaksproducten","d":null,"dn":"nog niet bekend","sec":["detailhandel-groothandel-en-ambachten"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/minder-verkooppunten-tabaksproducten/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["verkopers van tabaksproducten en aanverwante producten (zoals e-sigaretten en navulverpakkingen)"],"vwt":"","wat":["Verkoopt u tabaksproducten? Het aantal verkooppunten voor tabaksproducten en e-sigaretten wordt stap voor stap kleiner.","Datum nader te bepalen: E-sigaretten, navulverpakkingen en patronen zijn alleen nog te koop in tabaksspeciaalzaken. Supermarkten, tankstations en gemakswinkels mogen deze producten dan niet meer verkopen.","Vanaf 2030: Ook tabaksproducten zoals sigaretten en shag mogen alleen nog worden verkocht in gemakszaken en tabaksspeciaalzaken.","Vanaf 2032: Alleen tabaksspeciaalzaken mogen nog tabaksproducten, e-sigaretten en andere rookwaren verkopen."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/tabaksverkooppunten/b1","text":"Consultatie Beperken verkooppunten tabaksproducten en aanverwante producten (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/fewer-sales-points-tobacco-products/","mod":"2026-09-08"},{"id":"recht-op-reparatie-product-repareren-aantrekkelijker-voor-consumenten","t":"Nieuwe EU-regels bevorderen reparatie van producten","d":null,"dn":"in 2026","sec":["detailhandel-groothandel-en-ambachten"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/recht-op-reparatie-product-repareren-aantrekkelijker-voor-consumenten/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["fabrikanten van goederen"],"vwt":"","wat":["Maakt u elektronische producten zoals wasmachines, laptops of andere spullen die kapot kunnen gaan? Er komen nieuwe regels uit de Europese richtlijn Richtlijn (EU) 2024/1799. Deze richtlijn bevat regels om reparatie van bepaalde producten te bevorderen. Het doel is dat consumenten makkelijker en aantrekkelijker producten laten repareren in plaats van vervangen. Zo kan er minder afval ontstaan.","Dit verandert er voor u:","• Bevordering van reparatie: Als u producten maakt waarvoor de EU-regels op reparatie gelden, kan het zijn dat u deze moet repareren als de klant hierom vraagt, ook als de garantieperiode is verlopen. Dit geldt alleen voor producten die in de richtlijn zijn opgenomen, niet voor alle elektronische producten. U mag een redelijke prijs vragen of het gratis doen.\n• Duidelijke informatie: U kunt een standaardformulier gebruiken om klanten te laten zien wat een reparatie kost en hoelang het duurt. Dit heet het Europees reparatie-informatieformulier.\n• Onlineplatform: Er komt een Europees online platform waar mensen reparateurs kunnen vinden. Landen kunnen kiezen of ze een eigen deel op dit platform maken of een nationaal platform hebben dat via links op het Europese platform te bereiken is. Reparateurs kunnen zich aanmelden als ze aan de kwaliteitseisen voldoen.\n• Garantie verlengen: In de Europese richtlijn staat dat bij reparatie binnen de wettelijke garantieperiode de garantie met 12 maanden wordt verlengd. Hoe dit in Nederland wordt uitgewerkt, is nog niet duidelijk. Nederland heeft geen vaste wettelijke garantietermijn."],"doen":[],"law":[{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=OJ:L_202401799","text":"Richtlijn (EU) 2024/1799 Reparatierichtlijn (EU)"}],"en":"https://business.gov.nl/amendments/right-to-repair/","mod":"2026-09-08"},{"id":"nieuwe-regels-beperken-winst-en-salarissen-kinderopvang","t":"Nieuwe regels beperken winst en salarissen kinderopvang","d":null,"dn":"nog niet bekend","sec":["kinderopvang"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/nieuwe-regels-beperken-winst-en-salarissen-kinderopvang/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ondernemers in de kinderopvang","bestuurders en toezichthouders in de kinderopvang"],"vwt":"","wat":["Bent u ondernemer in de kinderopvang? Vanaf 2029 mag uw opvang niet meer onbeperkt winst maken. Ook gaat een maximumsalaris gelden voor bestuurders. Zij mogen niet meer verdienen dan het maximumsalaris in de publieke sector (€ 262.000 per jaar, peildatum 2026). Kinderopvangorganisaties gaan namelijk vallen onder de Wet normering topinkomens (WNT).","Om kinderopvang bijna gratis te kunnen maken, wil het kabinet dat daar vanaf 2029 veel meer overheidsgeld naartoe gaat. De beperking van winsten en salarissen staat daar tegenover. Dat past bij de belangrijke taak die kinderopvang voor de samenleving heeft."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/wetfinancieringkinderopvang/b1","text":"Consultatie Wet financiering kinderopvang (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/new-rules-restrict-profits-salaries-childcare-sector/","mod":"2026-09-08"},{"id":"nieuwe-regels-voor-rijinstructeurs-en-rijexamens","t":"Nieuwe regels voor rijinstructeurs en rijexamens","d":null,"dn":"nog niet bekend","sec":["persoonlijke-dienstverlening"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/nieuwe-regels-voor-rijinstructeurs-en-rijexamens/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ondernemers in de rijscholenbranche (bijvoorbeeld rijschoolhouders en rijinstructeurs)"],"vwt":"","wat":["Bent u rijinstructeur? Er komen nieuwe regels voor het rijonderwijs. Die moeten de rijvaardigheid van nieuwe automobilisten verbeteren en de slagingspercentages bij rijexamens verhogen. Bovendien moet beter rijonderwijs het aantal verkeersongevallen onder beginnende bestuurders verlagen.","Daarom komen er nieuwe regels, zoals:","• Mensen die hun rijbewijs willen halen, moeten eerst rijlessen volgen. Op dit moment is alleen het examen verplicht.\n• Rijlessen moeten aan meer eisen voldoen. Bijvoorbeeld aan de verplichting om tijdens de opleiding in het donker te hebben gereden en om een keer 130 te hebben gereden.\n• Rijinstructeurs moeten een opleiding volgen bij een door het IBKI erkend opleidingsinstituut.\n• Elke 5 jaar moeten instructeurs zelf ook weer een theorie- en een praktijkexamen doen. Als een instructeur 3 keer een onvoldoende haalt, verliest deze zijn bevoegdheid."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/new-rules-driving-instructors-tests/","mod":"2026-09-08"},{"id":"wet-zorgplicht-kinderarbeid","t":"Ondernemer moet kinderarbeid voorkomen","d":null,"dn":"nog niet bekend","sec":["detailhandel-groothandel-en-ambachten"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/wet-zorgplicht-kinderarbeid/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Er is een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["alle bedrijven die fysiek in Nederland goederen en diensten verkopen","bedrijven die in Nederland gevestigd zijn en hun goederen en/of diensten online verkopen en zich daarbij (ook) richten op de Nederlandse markt","bedrijven die online verkopen en zich expliciet richten op de Nederlandse markt"],"vwt":"","wat":["Verkoopt u goederen of diensten? U moet voorkomen dat u goederen of diensten verkoopt die met behulp van kinderarbeid zijn gemaakt.","U moet verklaren dat u het nodige doet om kinderarbeid te voorkomen.","Is er een klacht over uw bedrijf? En blijkt na een controle dat uw bedrijf niet genoeg doet? Dan kunt u bestuurlijke boete krijgen. Bestuurders van bedrijven die meerdere boetes hebben gekregen, kunnen strafrechtelijk worden vervolgd."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2019-401.html","text":"Wet zorgplicht kinderarbeid (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/preventing-child-labour/","mod":"2026-09-10"},{"id":"ondernemers-moeten-stagevergoeding-betalen","t":"Ondernemers moeten stagevergoeding betalen","d":null,"dn":"nog niet bekend","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/ondernemers-moeten-stagevergoeding-betalen/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ondernemers met stagiairs uit het mbo, hbo en wo"],"vwt":"","wat":["Heeft u stagiairs? Dan moet u straks een stagevergoeding betalen. Studenten in het mbo, hbo en wo krijgen recht op een stagevergoeding als hun stage onderdeel is van hun opleiding.","De belangrijkste veranderingen zijn:","• U moet een stagevergoeding betalen aan stagiairs uit het mbo, hbo en wo.\n• De hoogte van de stagevergoeding komt niet in de wet te staan. Sectoren en stagebedrijven maken zelf afspraken over het bedrag.\n• Korte stages en stages in het buitenland krijgen geen verplichte stagevergoeding.\n• Voor stages in het hbo en wo wordt een stageovereenkomst verplicht.","Het verplicht maken van een stagevergoeding is onderdeel van een groter pakket regels. Het kabinet wil met die regels de kwaliteit van stages verbeteren."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/employers-must-pay-interns-allowance/","mod":"2026-09-08"},{"id":"opkoper-moet-digitaal-registreren","t":"Opkoper moet digitaal registreren","d":null,"dn":"nog niet bekend","sec":["detailhandel-groothandel-en-ambachten"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/opkoper-moet-digitaal-registreren/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["opkopers","handelaren van tweedehands goederen"],"vwt":"","wat":["Bent u opkoper of handelaar in tweedehands goederen? U wordt verplicht om tweedehands goederen en de personen die deze goederen aanbieden, in het Digitaal Opkopersregister (DOR) te zetten. Opkopers en handelaren zetten in sommige gemeentes dat nu nog in een papieren register.","Het DOR is verbonden aan de database van Stop Heling. In deze database staan gestolen goederen waarvan aangifte is gedaan bij de politie of de Koninklijke marechaussee. Als u een gestolen product opkoopt en inschrijft in het DOR, ontstaat een match met Stop Heling en krijgt de politie automatisch een melding.","Digitaal Opkopersloket","Opkopers en handelaren moeten zich melden bij de gemeente waar zij hun bedrijf of beroep uitoefenen. Voortaan moet dit in alle gemeenten bij het Digitaal Opkopersloket (DOL)."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/opkopersregister/b1","text":"Internetconsultatie. Besluit Digitaal opkopersregister en Digitaal opkopersloket (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/helingbestrijding","text":"Internetconsultatie. Wetsvoorstel verbetering bestrijding heling (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/digital-register-second-hand-traders/","mod":"2026-09-08"},{"id":"ouders-moeten-ontheffing-aanvragen-voor-kindvlogs","t":"Ouders moeten ontheffing aanvragen voor kindvlogs","d":null,"dn":"nog niet bekend","sec":["cultuur-amusement-sport-en-media"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/ouders-moeten-ontheffing-aanvragen-voor-kindvlogs/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ouders die vlogs maken waarin hun kind te zien is","vlogfamilies die geld verdienen met hun online video’s","bedrijven of merken die samenwerken met kindvloggers"],"vwt":"","wat":["Maakt u vlogs of filmpjes waarin uw kind regelmatig in beeld komt én verdient u daar geld mee? Dan krijgt u te maken met strengere regels. De overheid wil kinderen beter beschermen tegen de risico’s van online werk. De regels gaan gelden voor vlogfamilies en (ouders van) kidfluencers en kindvloggers.","Dit verandert er:","• U moet een ontheffing aanvragen voor kinderen onder de 13 jaar in vlogs met meer dan 50.000 volgers waar geld mee wordt verdiend. Dit geldt bijvoorbeeld voor vlogs op YouTube, TikTok of Instagram.\n• Voor 13- tot 15-jarigen is geen ontheffing nodig. Voor deze groep zijn wettelijke arbeids- en rusttijden waar werkgevers zich aan moeten houden.\n• U wordt als ouder gezien als werkgever. U kunt dus verantwoordelijk worden gehouden als de regels niet worden nageleefd.\n• De Arbeidsinspectie krijgt meer mogelijkheden om te controleren. Met een verplichte ontheffing, is voor de inspectie makkelijker te controleren of u zich aan de regels houdt.\n• De boetes op overtreding van de regels worden hoger, vooral als uw kind commerciële druk ervaart.\n• Er komt meer voorlichting. Ouders krijgen meer informatie over de risico’s van online zichtbaarheid voor hun kind én over de regels die gelden."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/parents-must-have-exemption-for-vlogs-showing-their-children/","mod":"2026-09-08"},{"id":"platforms-worden-btw-plichtig-voor-verhuur-en-vervoer","t":"Platforms worden btw-plichtig voor verhuur en vervoer","d":null,"dn":"tussen 1 juli 2028 en 1 januari 2030","sec":["horeca-recreatie-en-catering","vervoer"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/platforms-worden-btw-plichtig-voor-verhuur-en-vervoer/","sh":"De EU heeft deze nieuwe regels aangenomen: houd hier rekening mee","se":"Dit is een Europese Richtlijn. Nederland moet deze nieuwe regels de komende 2 jaar invoeren. De precieze Nederlandse regels en datums zijn er nog niet.","ph":"vast","vw":["platforms die kortdurende verhuur van accommodatie faciliteren","platforms die passagiersvervoer over de weg faciliteren","ondernemers die via deze platforms diensten verrichten","particulieren die af en toe via deze platforms kortdurend accommodatie verhuren"],"vwt":"Werkt u met een digitaal platform voor accommodatieverhuur of personenvervoer? Dan krijgt u te maken met nieuwe btw-regels. Platforms worden btw-plichtig voor de diensten die via hen worden aangeboden en verricht.","wat":["Verhuurt u via een platform een accommodatie voor maximaal 30 nachten? Of heeft u een platform waarmee u personenvervoer over de weg faciliteert. Dan moet het platform straks btw gaan betalen over dat aanbod. Dit is onderdeel van ‘ViDA’: nieuwe Europese regels om het btw-systeem beter te laten aansluiten op de digitale economie.","Bij de platforms die kortdurende verhuur faciliteren","• Het platform wordt verantwoordelijk voor de btw. Platforms die kortdurende verhuur van accommodatie (maximaal 30 nachten) faciliteren, moeten btw afdragen over de diensten die via hun platform worden verricht.\n• Draagt u als aanbieder zelf al btw af? Dan moet u dit aan het platform melden en uw btw-nummer doorgeven. Het platform is dan niet verantwoordelijk voor de btw.\n• Het platform moet uw gegevens bijhouden. Platforms moeten goed controleren of u zelf btw betaalt en deze informatie goed bewaren.","Bij de platforms die passagiersvervoer faciliteren","Voor taxidiensten en ander personenvervoer over de weg gelden aanvullende regels:","• Werkt u via een platform als chauffeur en valt u onder de kleineondernemersregeling (KOR)? Dan moet u dit aan het platform melden en uw btw-nummer doorgeven Het platform hoeft dan over uw diensten geen btw af te dragen.\n• Het platform moet wel kunnen aantonen dat u de KOR toepast. Platforms moeten bijhouden welke chauffeurs gebruikmaken van de KOR.","Waarom deze verandering?","De concurrentie wordt zo eerlijker. Nu betalen sommige aanbieders van accomodaties via platforms geen btw, bijvoorbeeld omdat ze onder de kleineondernemersregeling (KOR) vallen of maar af en toe iets verhuren. Hierdoor hebben ze een voordeel op traditionele hotels en taxibedrijven die wel btw betalen. Met de nieuwe regels betaalt altijd iemand btw: het platform of de aanbieder zelf."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/btw_platformeconomie/b1","text":"Consultatie Wet implementatie Richtlijn Btw in het digitale tijdperk inzake de platformeconomie (Overheid.nl)"},{"href":"https://eur-lex.europa.eu/legal-content/NL/TXT/HTML/?uri=OJ:L_202500516","text":"Europese richtlijn btw in het digitale tijdperk (ViDA), Richtlijn (EU) 2025/516 (EU)"}],"en":"https://business.gov.nl/amendments/digital-platforms-liable-for-vat-rentals-transport/","mod":"2026-09-09"},{"id":"invoering-rdw-controleert-waarde-bij-import-autos","t":"RDW controleert waarde bij import auto’s","d":null,"dn":"nog niet bekend","sec":["vervoer"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/invoering-rdw-controleert-waarde-bij-import-autos/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["importeurs van auto’s","taxateurs","belastingadviseurs"],"vwt":"","wat":["Importeert u tweedehands auto’s? De getaxeerde waarde van geïmporteerde tweedehands auto’s wordt in de toekomst onafhankelijk gecontroleerd door de RDW.","Bij geïmporteerde tweedehands auto’s hangt de belasting op personenauto’s en motorrijwielen (bpm) af van de waarde van de auto. De nieuwe maatregel houdt in dat de waarde van de auto onafhankelijk wordt gecontroleerd voordat er aangifte bpm kan worden gedaan."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/bpm/b1","text":"Consultatie Wijziging van regelgeving inzake koerslijsten en taxatierapporten bij de aangifte van bpm (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/netherlands-vehicle-autority-rdw-will-check-value-imported-cars/","mod":"2026-09-08"},{"id":"regels-concurrentiebeding-aangescherpt","t":"Regels concurrentiebeding aangescherpt","d":null,"dn":"nog niet bekend","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/regels-concurrentiebeding-aangescherpt/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["ondernemers met personeel"],"vwt":"","wat":["Heeft u personeel en gebruikt u een concurrentiebeding? In contracten staat steeds vaker een concurrentiebeding, zonder goede reden. Hierdoor kunnen werknemers minder makkelijk van baan wisselen en werkgevers minder makkelijk mensen vinden. De regels voor het concurrentiebeding worden daarom aangescherpt:","• Een concurrentiebeding kan tot maximaal 1 jaar na het einde van de arbeidsovereenkomst gelden.\n• U moet het geografische gebied waarin de werknemer door het concurrentiebeding niet mag werken benoemen.\n• U moet voor alle werknemers uitleggen waarom het nodig is om een concurrentiebeding te hebben, niet alleen voor tijdelijke contracten zoals nu.\n• Als u een concurrentiebeding gebruikt, moet u de werknemer hiervoor betalen.\n• De vergoeding is de helft van wat de werknemer de laatste maand verdiende, voor elke maand dat het concurrentiebeding van kracht is. Als het concurrentiebeding bijvoorbeeld 6 maanden geldt, heeft de werknemer recht op een vergoeding van 3 maanden salaris."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/moderniseringvanhetconcurrentiebeding/b1","text":"Consultatie Wijziging artikel 653 Boek 7 Burgerlijk Wetboek en van de Overgangswet nieuw Burgerlijk Wetboek voor modernisering concurrentiebeding (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/rules-non-compete-clause-tightened/","mod":"2026-11-13"},{"id":"regels-voor-kennismigranten-veranderen","t":"Regels voor kennismigranten veranderen","d":null,"dn":"nog niet bekend","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/regels-voor-kennismigranten-veranderen/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["bedrijven die kennismigranten willen aannemen","erkende referenten die al gebruik maken van de kennismigrantenregeling","IT-bedrijven, ingenieursbureaus en consultancybedrijven"],"vwt":"","wat":["Werkt u met kennismigranten? Dan krijgt u mogelijk te maken met strengere regels. Het kabinet wil de kenniseconomie versterken en tegelijk de migratie naar Nederland verminderen. Daarom is het kabinet van plan om de kennismigrantenregeling aan te scherpen. Het doel is om misbruik van de regeling tegen te gaan en ervoor te zorgen dat kennismigranten echt bijdragen aan de Nederlandse economie.","De belangrijkste plannen van het kabinet zijn:","• Het kabinet wil het salaris dat nodig is om als kennismigrant te worden gezien verhogen. Waarschijnlijk moet u straks een hoger salaris betalen aan kennismigranten die u wilt aannemen en in dienst heeft. Voor kennismigranten jonger dan 30 jaar stijgt het minimale bruto maandsalaris mogelijk met honderden euro's per maand. Het kabinet is van plan om het huidige bruto maandsalaris van minimaal € 4.171 te verhogen tot 1,1 keer het gemiddeld bruto jaarsalaris.\n• Strengere eisen voor uw bedrijf: Wilt u kennismigranten aannemen? Dan moet uw bedrijf eerst een erkenning als 'erkend referent' krijgen. Het kabinet is van plan de bestaande eisen te verzwaren en aan te scherpen, zoals bijvoorbeeld:Bij 3 of meer boetes in 4 jaar (voor fiscale vergrijpen, te laag loon of illegale arbeid) krijgt u geen erkenning meer.Ook overtredingen van andere relevante wetten wegen nu mee bij uw aanvraag.Heeft u 2 jaar geen kennismigrant in dienst gehad? Dan verliest u uw erkenning.\n• Bij 3 of meer boetes in 4 jaar (voor fiscale vergrijpen, te laag loon of illegale arbeid) krijgt u geen erkenning meer.\n• Ook overtredingen van andere relevante wetten wegen nu mee bij uw aanvraag.\n• Heeft u 2 jaar geen kennismigrant in dienst gehad? Dan verliest u uw erkenning."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/rules-highly-skilled-migrants-change/","mod":"2026-09-08"},{"id":"rouwverlof-wettelijk-vastgelegd","t":"Rouwverlof wettelijk vastgelegd","d":null,"dn":"nog niet bekend","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/rouwverlof-wettelijk-vastgelegd/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Er is een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ondernemers met personeel"],"vwt":"","wat":["Heeft u personeel? Uw werknemers kunnen door een overlijden te maken krijgen met rouw. Voor rouw als gevolg van een sterfgeval in een gezinssituatie, wordt rouwverlof in de wet vastgelegd. Werknemers die fulltime werken krijgen het recht 5 werkdagen rouwverlof op te nemen. De werkgever moet de werknemer tijdens het rouwverlof doorbetalen. Voor dit wettelijke rouwverlof gelden de volgende voorwaarden:","• De werknemer heeft een gezin met minderjarige kinderen.\n• Een partner of minderjarig kind is overleden.","Deze wetswijziging moet ervoor zorgen dat werknemers die na een rouwperiode terugkeren op de werkvloer aan het werk blijven. Het moet langdurig verzuim voorkomen en verzuimkosten voor werknemers laag houden.","Rouwverlof geven is nu nog niet wettelijk verplicht. Maar in de cao voor uw bedrijfstak kunnen wel regels staan voor rouwverlof. Het bestaande wettelijk recht op verlof bij een overlijden is kortdurend, geldt tot aan de uitvaart en is niet bedoeld als rouwverlof."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/rouwverlof/b1","text":"Consultatie Wet invoering rouwverlof (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/bereavement-leave-legally-defined/","mod":"2026-11-03"},{"id":"sociale-onderneming-krijgt-betere-herkenning-en-erkenning","t":"Sociale onderneming krijgt betere herkenning met BVm","d":null,"dn":"nog niet bekend","sec":[],"sub":["bedrijf-starten-of-overnemen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/sociale-onderneming-krijgt-betere-herkenning-en-erkenning/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["sociaal ondernemers","ondernemers die zaken willen doen met maatschappelijke ondernemingen"],"vwt":"","wat":["Heeft uw bedrijf een sociaal of maatschappelijk doel? De regelgeving en het speelveld voor bedrijven met sociale of maatschappelijke doelen wordt verbeterd. Er komt een nieuwe juridische vormgeving van sociaal ondernemerschap. Sociale ondernemingen kunnen de status van maatschappelijke BV (BVm) krijgen. Het gaat hierbij niet om een nieuwe rechtsvorm.","Sociale ondernemingen worden ook wel maatschappelijke ondernemingen genoemd. Zij spelen een rol bij het aanpakken van maatschappelijke vraagstukken op het terrein van bijvoorbeeld energie en klimaat, zorg, onderwijs en veiligheid in binnen- en buitenland.","Duidelijk herkenbaar met BVm","Met de BVm kunnen maatschappelijke ondernemingen zich straks duidelijk herkenbaar maken. Voor met name zakelijke relaties wordt daarmee duidelijk dat ze met een bedrijf te maken hebben dat maatschappelijke impact vooropstelt boven het uitkeren van winst aan aandeelhouders. De winst blijft voor een goed deel behouden voor het verder realiseren en uitbouwen van maatschappelijke impact.","De Code Sociaal Ondernemen wordt mogelijk in een wet vastgelegd."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/bvm","text":"Internetconsultatie. Besloten vennootschap met een maatschappelijk doel (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/legal-form-social-entrepreneurship-explored/","mod":"2026-10-28"},{"id":"tarieven-voor-belastingen-op-personenautos-en-motorrijwielen-bpm-omhoog","t":"Tarieven voor belastingen op personenauto's en motorrijwielen (bpm) omhoog","d":null,"dn":"Stapsgewijs: op 1 januari 2026, 1 januari 2027 en 1 januari 2028","sec":[],"sub":["belastingen-en-heffingen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/tarieven-voor-belastingen-op-personenautos-en-motorrijwielen-bpm-omhoog/","sh":"Deze wet gaat door: bereid uw bedrijf nu voor","se":"Deze wet is aangenomen. U kunt zich voorbereiden.","ph":"vast","vw":["ondernemers die personenauto’s en motorrijwielen kopen of importeren"],"vwt":"","wat":["Importeert of koopt u een personenauto, bestelauto of motor? Dan betaalt u belasting op personenauto's en motorrijwielen (bpm). Hoe meer CO₂ de auto of motor uitstoot, hoe hoger de bpm. Dit wordt bepaald op basis van schijfgrenzen. Deze schijfgrenzen gaan omlaag. Tegelijkertijd worden de bpm-tarieven (bedragen per gram CO₂) per jaar verhoogd.","Voor de jaren 2026, 2027 en 2028 zijn deze percentages vastgesteld:","• 2026: schijfgrenzen zijn gedaald met 1,55% en tarieven zijn gestegen met 1,57%\n• 2027: schijfgrenzen dalen met 1,46% en tarieven stijgen met 1,48%\n• 2028: schijfgrenzen dalen met 1,38% en tarieven stijgen met 1,40%","De regering voert deze verandering door omdat nieuwe auto’s ieder jaar minder CO₂ uitstoten. Hierdoor wordt de bpm automatisch lager. Om de belastingopbrengst gelijk te houden, past de overheid de bpm-tarieven en CO₂-grenzen aan."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2025-444.html","text":"Belastingplan 2026 (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/tariffs-on-private-vehicle-and-motorcycle-tax-going-up/","mod":"2026-08-28"},{"id":"verplicht-bijmengen-biobrandstof-binnenvaart","t":"Verplicht bijmengen biobrandstof binnenvaart","d":null,"dn":"nog niet bekend","sec":["vervoer"],"sub":[],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/verplicht-bijmengen-biobrandstof-binnenvaart/","sh":"","se":"","ph":"onbekend","vw":["brandstofleveranciers voor de binnenvaart"],"vwt":"","wat":["Brandstofleveranciers voor binnenvaartschepen moeten een bepaald percentage duurzame biobrandstof bijmengen. Door biobrandstoffen bij te mengen wordt de CO2-uitstoot minder.","In de Green Deal Zeevaart, Binnenvaart en Havens is afgesproken dat de uitstoot door de binnenvaart omlaag moet. In 2030 moet 40% tot 50% minder CO2 worden uitgestoten door de binnenvaart dan in 2015.","Voor vrachtverkeer op de weg bestaat de bijmengverplichting al."],"doen":[],"law":[{"href":"https://zoek.officielebekendmakingen.nl/stb-2022-494.html#d17e127","text":"Besluit tot wijziging van Besluit inwerkingtreding Wet wijziging Wet milieubeheer ter bevordering gebruik energie uit hernieuwbare bronnen en inwerkingtreding wijziging Besluit energie vervoer (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2021-620.html","text":"Besluit inwerkingtreding Wet wijziging Wet milieubeheer ter bevordering gebruik energie uit hernieuwbare bronnen en inwerkingtreding wijziging Besluit energie vervoer (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2021-619.html","text":"Besluit wijziging Besluit energie vervoer in verband met de implementatie van Richtlijn (EU) 2018/2001 ter bevordering gebruik energie uit hernieuwbare bronnen (Overheid.nl)"},{"href":"https://zoek.officielebekendmakingen.nl/stb-2021-334.html","text":"Wet wijziging Wet milieubeheer voor implementatie Richtlijn (EU) 2018/2001 ter bevordering gebruik energie uit hernieuwbare bronnen (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/blending-biofuel-mandatory-inland-vessels/","mod":"2025-09-25"},{"id":"vereenvoudiging-verschil-maatschap-en-vof-gaat-verdwijnen","t":"Verschil maatschap en vof verdwijnt","d":null,"dn":"nog niet bekend","sec":[],"sub":["bedrijf-starten-of-overnemen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/vereenvoudiging-verschil-maatschap-en-vof-gaat-verdwijnen/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ondernemers die samen met andere ondernemers 1 bedrijf willen hebben","maten in een maatschap","vennoten van een vennootschap onder firma (VOF)"],"vwt":"","wat":["Wilt u samen met collega’s ondernemen? Er komen nieuwe regels voor de personenvennootschap. Het verschil tussen maatschap en vof gaat verdwijnen.","Er zijn nu 3 personenvennootschappen:","• maatschap\n• vennootschap onder firma (VOF)\n• commanditaire vennootschap (CV)","Straks vallen onder de personenvennootschap nog maar 2 rechtsvormen:","• vennootschap\n• commanditaire vennootschap","De namen ‘maatschap’ en ‘vennootschap onder firma’ blijven bestaan, maar de verschillen verdwijnen. Wat zijn straks de regels voor zo’n ‘personenvennootschap’?","• De vennoten zijn hoofdelijk (ieder voor het geheel) aansprakelijk voor de hele schuld.\n• De vennoten mogen aanspraak op winst verpanden.\n• De aansprakelijkheid bij een opdracht kan worden beperkt tot de vennoot aan wie de opdracht uitdrukkelijk is toevertrouwd.\n• De personenvennootschap kan rechtspersoonlijkheid worden toegekend."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/moderniseringpv2","text":"Consultatie. Wetsvoorstellen modernisering personenvennootschappen (Overheid.nl)"},{"href":"https://wetgevingskalender.overheid.nl/Regeling/WGK007901#:~:text=Dit%20wetsvoorstel%20voorziet%20in%20de,en%20is%20toe%20aan%20vernieuwing.","text":"Wetgevingskalender. Wetsvoorstel modernisering personenvennootschappen (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/1313","text":"Consultatie. Wetsvoorstel modernisering personenvennootschappen (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/difference-professional-partnership-general-partnership/","mod":"2026-09-08"},{"id":"vertrouwenspersoon-verplicht","t":"Vertrouwenspersoon wordt verplicht","d":null,"dn":"nog niet bekend","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/vertrouwenspersoon-verplicht/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Er is een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ondernemers met 10 of meer werknemers"],"vwt":"","wat":["Als werkgever moet u zorgen voor een veilige werkomgeving voor uw personeel. U moet ongewenst gedrag en mentale arbeidsbelasting bij uw werknemers zoveel mogelijk voorkomen. Het is daarom binnenkort verplicht om een vertrouwenspersoon te hebben voor uw organisatie. Dit kan iemand vanuit de eigen organisatie zijn, maar ook iemand via een branchevereniging of een arbodienst.","De vertrouwenspersoon van uw organisatie heeft wettelijke taken. Dat zijn onder andere:","• het opvangen, begeleiden en adviseren van werknemers en als het nodig is, doorverwijzen naar een hulpverlener\n• de werkgever gevraagd en ongevraagd adviseren over hoe die ongewenst gedrag kan voorkomen en aanpakken\n• jaarlijks verslag uitbrengen van waarnemingen aan werkgever, ondernemingsraad of personeelsvertegenwoordiging\n• de werkgever en werknemers informeren over wat de vertrouwenspersoon doet en waarvoor personeel contact kan zoeken met de vertrouwenspersoon","Deze wijziging wordt opgenomen in artikel 13a van de Arbeidsomstandighedenwet (Arbowet)."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/vertrouwenspersonen","text":"Consultatie Wet vertrouwenspersonen (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/confidential-officer-mandatory/","mod":"2026-09-08"},{"id":"werkgever-kan-asielzoeker-na-3-maanden-inzetten","t":"Werkgever kan asielzoeker na 3 maanden inzetten","d":null,"dn":"nog niet bekend","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/werkgever-kan-asielzoeker-na-3-maanden-inzetten/","sh":"Er is een plan, de Eerste Kamer moet nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Dit voorstel wordt nog besproken in de Eerste Kamer. Mogelijk is dit voorstel veranderd in de Tweede Kamer. Deze verandering wordt zo snel mogelijk doorgevoerd op deze pagina.","ph":"plan","vw":["werkgevers met personeelstekort","ondernemers die asielzoekers willen aannemen","uitzendbureaus en detacheerders"],"vwt":"","wat":["Bent u werkgever en wilt u een asielzoeker aannemen? Dan mag dat straks eerder. Asielzoekers met een grote kans op een asielvergunning mogen al na 3 maanden werken. Nu geldt nog een wachttijd van 6 maanden.","Wat blijft gelden?","• U vraagt bij het UWV een tewerkstellingsvergunning (TWV) aan voordat een asielzoeker bij u aan de slag gaat."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/aanpassinglagereregelgevingtoegangtotdearbeidsmarktvoorasielzoekers/b1","text":"Consultatie Aanpassing lagere regelgeving toegang tot de arbeidsmarkt voor asielzoekers (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/employers-may-employ-asylum-seekers-after-three-months/","mod":"2026-11-13"},{"id":"werkgevers-moeten-betaling-van-minimumloon-bewijzen","t":"Werkgevers moeten betaling van minimumloon bewijzen","d":null,"dn":"nog niet bekend","sec":[],"sub":["personeel"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/werkgevers-moeten-betaling-van-minimumloon-bewijzen/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ondernemers met personeel"],"vwt":"","wat":["Bent u werkgever? Dan moet u straks kunnen bewijzen dat u uw werknemers minimaal het wettelijk minimumloon betaalt. Het kabinet werkt aan een nieuwe wet die werknemers beter beschermt tegen onderbetaling.","Nu moeten een werknemer of de Nederlandse Arbeidsinspectie bewijzen dat sprake is van onderbetaling. Straks ligt die bewijslast bij u als werkgever.","De belangrijkste veranderingen zijn:","• Kunt u niet aantonen dat u uw werknemer minimaal het wettelijk minimumloon heeft betaald? Dan kan de overheid ervan uitgaan dat uw werknemer is onderbetaald. U moet dan bewijzen dat u wel het juiste loon heeft betaald.\n• Kan de Nederlandse Arbeidsinspectie door een gebrekkige administratie niet vaststellen of een werknemer het wettelijk minimumloon heeft gekregen? Dan kan de Arbeidsinspectie een bedrag aan onderbetaling berekenen. U moet dat bedrag alsnog aan uw werknemer betalen.","Met deze wetswijziging wil het kabinet werknemers beter beschermen tegen onderbetaling. Vooral als niet duidelijk is of een werkgever het wettelijk minimumloon heeft betaald."],"doen":[],"law":[],"en":"https://business.gov.nl/amendments/employers-must-prove-payment-of-minimum-wage/","mod":"2026-09-08"},{"id":"werknemers-beter-beschermd-bij-faillissement-en-doorstart","t":"Werknemers beter beschermd bij faillissement en doorstart","d":null,"dn":"nog niet bekend","sec":[],"sub":["bedrijf-starten-of-overnemen"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/werknemers-beter-beschermd-bij-faillissement-en-doorstart/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["ondernemers die een failliet bedrijf overnemen en een doorstart maken"],"vwt":"","wat":["Gaat uw bedrijf failliet en maakt het een doorstart? Dan gelden straks nieuwe regels. Door de Wet overgang van onderneming in faillissement (Wovof) zijn uw werknemers beter beschermd bij een doorstart van uw bedrijf.","De belangrijkste veranderingen:","• U moet bij een doorstart de meeste werknemers overnemen.\n• Een doorstart mag geen reden zijn om werknemers geen contract aan te bieden.\n• Heeft u bedrijfseconomische redenen om minder werknemers mee te nemen? Zoals minder klanten, een verhuizing of automatisering? U mag dan minder werknemers meenemen, maar wie u meeneemt, bepaalt u op basis van objectieve criteria, zoals dienstjaren, functie of afdeling. Dit gaat op een vergelijkbare manier als bij selectie bij ontslag buiten faillissement. De rechter-commissaris controleert of uw selectie op een juiste en eerlijke manier gebeurt. De regels gelden niet voor bedrijven met minder dan 20 werknemers, behalve als u vrijwillig meedoet.\n• Het concurrentiebeding vervalt automatisch als een werknemer geen nieuw contract krijgt.\n• De ondernemingsraad, personeelsvertegenwoordiging en personeelsvergadering mogen advies geven over de doorstart."],"doen":[],"law":[{"href":"https://www.internetconsultatie.nl/positie_werknemers_in_faillissement/b1","text":"2e Consultatie Wet overgang van onderneming in faillissement (Overheid.nl)"},{"href":"https://www.internetconsultatie.nl/overgang_van_onderneming_in_faillissement","text":"1e Consultatie Wet overgang van onderneming in faillissement (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/better-protection-employees-in-case-of-bankruptcy-and-restart/","mod":"2026-09-08"},{"id":"zelfstandigen-verplicht-verzekerd-tegen-arbeidsongeschiktheid","t":"Zelfstandigen verplicht verzekerd tegen arbeidsongeschiktheid","d":null,"dn":"nog niet bekend","sec":[],"sub":["bedrijfsvoering"],"url":"https://ondernemersplein.overheid.nl/wetswijzigingen/zelfstandigen-verplicht-verzekerd-tegen-arbeidsongeschiktheid/","sh":"Er is een plan, de Tweede en Eerste Kamer moeten nog beslissen","se":"Het kabinet heeft een voorstel gedaan om de regels te veranderen. Het voorstel wordt nog besproken in de Tweede en Eerste Kamer. Het voorstel kan dus nog veranderen, maar het is goed om dit alvast te weten.","ph":"plan","vw":["zelfstandige ondernemers"],"vwt":"","wat":["Het kabinet wil dat straks alle zelfstandigen verplicht verzekerd zijn tegen arbeidsongeschiktheid.","Zelfstandigen moeten straks een arbeidsongeschiktheidsverzekering (AOV) hebben. Door een nieuwe verplichte verzekering lopen zij minder financiële risico’s door ziekte. Zelfstandigen krijgen straks recht op een arbeidsongeschiktheidsuitkering als ze door langdurige ziekte niet meer het minimumloon kunnen verdienen.","Met een verzekeringsplicht voor zelfstandigen zijn straks alle werkenden beschermd tegen de gevolgen van arbeidsongeschiktheid. Met een verplichte verzekering worden ook kosten en risico’s voor de samenleving kleiner."],"doen":[],"law":[{"href":"https://internetconsultatie.nl/wetbasisverzekeringarbeidsongeschiktheidzelfstandigen/b1","text":"Consultatie. Wet basisverzekering arbeidsongeschiktheid zelfstandigen (Overheid.nl)"}],"en":"https://business.gov.nl/amendments/occupational-disability-insurance-aov-self-employed-professionals/","mod":"2026-09-08"}]};
